export interface ServiceRoles {
  gate: string;    // Portão
  praise: string;  // Louvor
  word: string;    // Palavra (Texto livre agora)
  scripture: string; // Texto Bíblico (Leitura)
}

export interface ServiceRecord {
  id: string;
  date: string;
  description: string; // EBD, DOM, ou Dia da Semana
  songs: string[];
  roles: ServiceRoles;
}

export interface ServiceDraft {
  date: string;
  description: string;
  songs: string[];
  roles: ServiceRoles;
}

export interface SongStats {
  song: string;
  count: number;
  lastDate: string | null;
  history: string[];
}

export interface AppData {
  history: ServiceRecord[];
  customSongs?: string[];
  draft?: ServiceDraft;
}

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const emptyRoles = {
    gate: '',
    praise: '',
    word: '',
    scripture: ''
  };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '', // Será definido pelo Form baseado na data
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) {
            setDraft({
              ...data.draft,
              date: getTodayDate(),
              roles: data.draft.roles || { ...emptyRoles }
            });
          }
        }
      } catch (e) {
        console.error("Erro ao carregar banco de dados local", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) {
      saveData({ history, customSongs, draft });
    }
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    const combined = [...new Set([...INITIAL_PRAISE_LIST.map(s => s.trim()), ...customSongs.map(s => s.trim())])];
    return combined.sort((a, b) => {
      const aIsCIAS = a.startsWith('(CIAS)');
      const bIsCIAS = b.startsWith('(CIAS)');
      if (aIsCIAS && !bIsCIAS) return 1;
      if (!aIsCIAS && bIsCIAS) return -1;
      return a.localeCompare(b);
    });
  }, [customSongs]);

  const saveServiceRecord = (recordData: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...recordData, id: editingId } : r));
      setEditingId(null);
    } else {
      const newRecord: ServiceRecord = { ...recordData, id: crypto.randomUUID() };
      setHistory(prev => [newRecord, ...prev]);
    }

    setDraft({
      date: getTodayDate(),
      description: '',
      songs: [],
      roles: { ...emptyRoles }
    });
    setActiveTab('history');
  };

  const handleStartEdit = (record: ServiceRecord) => {
    setEditingId(record.id);
    setDraft({
      date: record.date,
      description: record.description,
      songs: record.songs,
      roles: record.roles || { ...emptyRoles }
    });
    setActiveTab('new');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setDraft({
      date: getTodayDate(),
      description: '',
      songs: [],
      roles: { ...emptyRoles }
    });
  };

  const deleteServiceRecord = (id: string) => {
    if (editingId === id) setEditingId(null);
    setHistory(prev => prev.filter(r => r.id !== id));
  };

  const registerNewSong = (songName: string) => {
    const trimmedName = songName.trim();
    if (!fullSongList.includes(trimmedName)) {
      setCustomSongs(prev => [...prev, trimmedName]);
    }
  };

  const restoreData = (newHistory: ServiceRecord[], newCustomSongs?: string[]) => {
    setHistory(newHistory);
    if (newCustomSongs) setCustomSongs(newCustomSongs);
  };

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    const sortedHistory = [...history].sort((a, b) => b.date.localeCompare(a.date));
    sortedHistory.forEach(record => {
      record.songs.forEach(song => {
        const trimmedSong = song.trim();
        if (!stats[trimmedSong]) stats[trimmedSong] = { song: trimmedSong, count: 0, lastDate: null, history: [] };
        stats[trimmedSong].count += 1;
        stats[trimmedSong].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(song => {
      stats[song].history.sort((a, b) => b.localeCompare(a));
      stats[song].lastDate = stats[song].history[0] || null;
    });
    return stats;
  }, [history]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-6 text-center">
        <div className="text-white space-y-4">
          <div className="animate-spin rounded-full h-14 w-14 border-4 border-white/20 border-t-white mx-auto"></div>
          <p className="font-bold text-lg tracking-wide uppercase">Carregando...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col pb-24 md:pb-0">
      {isOffline && (
        <div className="bg-amber-500 text-white text-[10px] font-black uppercase tracking-[0.2em] py-1.5 text-center flex items-center justify-center gap-2 animate-pulse z-[200]">
          <span className="material-icons text-sm">cloud_off</span>
          Modo Offline Ativado
        </div>
      )}

      <header className="glass-effect sticky top-0 z-[100] border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 p-2.5 rounded-2xl shadow-lg shadow-indigo-200 transform rotate-3">
              <span className="material-icons text-white text-2xl">library_music</span>
            </div>
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 leading-tight">ICM Santo Antônio II</h1>
              <span className="text-[10px] font-black uppercase tracking-[0.15em] text-indigo-500 block">Gestão de Louvores</span>
            </div>
          </div>
          <nav className="hidden lg:flex bg-slate-100 p-1 rounded-2xl gap-1">
            <button onClick={() => setActiveTab('new')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'new' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Novo Culto</button>
            <button onClick={() => setActiveTab('history')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'history' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Histórico</button>
            <button onClick={() => setActiveTab('unplayed')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'unplayed' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Restantes</button>
            <button onClick={() => setActiveTab('settings')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'settings' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Backup</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-6xl mx-auto p-4 md:p-8">
        <div className="animate-fadeIn">
          {activeTab === 'new' && (
            <div className="max-w-4xl mx-auto space-y-8">
              <ServiceForm 
                onSave={saveServiceRecord} 
                songStats={songStats}
                fullSongList={fullSongList}
                onRegisterNewSong={registerNewSong}
                draft={draft}
                setDraft={setDraft}
                editingId={editingId}
                onCancelEdit={handleCancelEdit}
              />
              <RankingList songStats={songStats} />
            </div>
          )}
          {activeTab === 'history' && (
            <HistoryList history={history} onDelete={deleteServiceRecord} onEdit={handleStartEdit} onClearAll={() => { if(confirm("Apagar todo o histórico?")) setHistory([]); }} />
          )}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={restoreData} />}
        </div>
      </main>

      <nav className="md:hidden fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] glass-effect border border-slate-200/50 flex justify-around p-3 z-[100] shadow-2xl rounded-3xl">
        <button onClick={() => setActiveTab('new')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'new' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">{editingId ? 'edit' : 'add_circle'}</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Novo</span>
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'history' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">history</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Histórico</span>
        </button>
        <button onClick={() => setActiveTab('unplayed')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'unplayed' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">assignment_late</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Restantes</span>
        </button>
        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'settings' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">settings</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Backup</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ 
  onSave, 
  songStats, 
  fullSongList, 
  onRegisterNewSong,
  draft,
  setDraft,
  editingId,
  onCancelEdit
}) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [infoModalData, setInfoModalData] = useState<{ song: string; type: 'history' | 'count' } | null>(null);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return {
      name: dayOfWeekNames[dayIndex],
      fullName: fullDayNames[dayIndex],
      isSunday: dayIndex === 0
    };
  }, [draft.date]);

  // Sincronizar descrição automaticamente se não for domingo
  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) {
      setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    } else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) {
      setDraft(prev => ({ ...prev, description: 'DOM' }));
    }
  }, [dateInfo, editingId]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node) && 
          inputRef.current && !inputRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const suggestions = useMemo(() => {
    const search = inputValue.toLowerCase().trim();
    if (!search) return fullSongList.slice(0, 10);
    return fullSongList.filter(s => s.toLowerCase().includes(search)).slice(0, 15);
  }, [inputValue, fullSongList]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({
      ...prev,
      roles: { ...prev.roles, [role]: name }
    }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));
      if (diffDays <= 30) {
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate });
        setShowSuggestions(false);
        return;
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  const shareViaWhatsApp = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${draft.description}\n\n`;
    message += `*Escala do Culto:*\n`;
    message += `🚪 Portão: ${draft.roles.gate || 'Não informado'}\n`;
    message += `🎵 Louvor: ${draft.roles.praise || 'Não informado'}\n`;
    message += `📖 Texto: ${draft.roles.scripture || 'Não informado'}\n`;
    message += `🎤 Palavra: ${draft.roles.word || 'Não informado'}\n\n`;
    message += `*Louvores:* \n`;
    draft.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleFinalSave = () => {
    onSave({ date: draft.date, description: draft.description, songs: draft.songs, roles: draft.roles });
    setShowSaveConfirm(false);
  };

  const RoleSelect = ({ label, icon, value, roleKey }: { label: string, icon: string, value: string, roleKey: keyof typeof draft.roles }) => (
    <div className="flex flex-col gap-2">
      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 px-1">
        <span className="material-icons text-[14px]">{icon}</span> {label}
      </label>
      <div className="relative">
        <select 
          value={value}
          onChange={(e) => updateRole(roleKey, e.target.value)}
          className="w-full bg-white border border-slate-200 rounded-2xl pl-4 pr-10 py-3.5 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm appearance-none cursor-pointer"
        >
          <option value="">Selecione...</option>
          {WORKERS_LIST.map(name => (
            <option key={name} value={name}>{name}</option>
          ))}
        </select>
        <span className="material-icons absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none">expand_more</span>
      </div>
    </div>
  );

  return (
    <div className={`bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 p-6 md:p-10 animate-fadeIn border ${editingId ? 'border-amber-400 border-2' : 'border-slate-100'}`}>
      <div className="flex flex-col gap-8">
        {editingId && (
          <div className="bg-amber-100 text-amber-900 p-3 rounded-2xl flex items-center justify-center gap-2 font-black uppercase text-[10px] tracking-widest animate-pulse">
            <span className="material-icons text-sm">edit</span> Editando Registro
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50/80 p-6 rounded-[2rem] border border-slate-100">
          <div>
            <div className="flex justify-between items-center mb-3 px-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Data do Culto</label>
              <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${dateInfo.isSunday ? 'bg-indigo-600' : 'bg-slate-400'}`}>
                {dateInfo.name}
              </span>
            </div>
            <div className="relative">
              <span className="material-icons absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400">event</span>
              <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-white border border-slate-200 rounded-2xl pl-12 pr-4 py-4 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block px-1">Tipo de Culto</label>
            {dateInfo.isSunday ? (
              <div className="flex bg-white border border-slate-200 p-1.5 rounded-2xl shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>EBD (Manhã)</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>DOM (Noite)</button>
              </div>
            ) : (
              <div className="w-full bg-slate-100 border border-slate-200 rounded-2xl px-4 py-4 font-bold text-slate-400 text-sm flex items-center gap-2">
                <span className="material-icons text-sm">info_outline</span> {dateInfo.fullName}
              </div>
            )}
          </div>
        </div>

        {/* ESCALA DE OBREIROS */}
        <div className="space-y-4">
          <h3 className="font-extrabold text-slate-800 text-sm flex items-center gap-2 px-1">
            <span className="material-icons text-indigo-600">people</span>
            Escala do Culto
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100">
            <RoleSelect label="Portão" icon="door_front" value={draft.roles.gate} roleKey="gate" />
            <RoleSelect label="Louvor" icon="music_note" value={draft.roles.praise} roleKey="praise" />
            <RoleSelect label="Texto Bíblico" icon="auto_stories" value={draft.roles.scripture} roleKey="scripture" />

            {/* NOVO CAMPO PALAVRA (TEXTO) */}
            <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 px-1">
                <span className="material-icons text-[14px]">record_voice_over</span> Palavra
              </label>
              <input 
                type="text"
                value={draft.roles.word}
                onChange={(e) => updateRole('word', e.target.value)}
                placeholder="Livro e versículo..."
                className="w-full bg-white border border-slate-200 rounded-2xl px-4 py-3.5 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm placeholder:font-normal placeholder:text-slate-300"
              />
            </div>
          </div>
        </div>

        {/* BUSCA DE LOUVORES */}
        <div className="relative">
          <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-3 block px-1">Adicionar Louvor</label>
          <div className="flex gap-3">
            <div className="relative flex-1 group">
              <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
              <input ref={inputRef} type="text" value={inputValue} onKeyDown={(e) => e.key === 'Enter' && checkAndAddSong(inputValue)} onChange={(e) => { setInputValue(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className="w-full pl-14 pr-4 py-5 bg-slate-50 border-2 border-transparent rounded-[1.5rem] focus:bg-white focus:border-indigo-100 outline-none transition-all font-semibold" placeholder="Buscar hino..." />
              {showSuggestions && suggestions.length > 0 && (
                <div ref={suggestionRef} className="absolute z-[110] w-full mt-3 bg-white border border-slate-200 rounded-[2rem] shadow-2xl overflow-hidden animate-scaleUp max-h-80 overflow-y-auto">
                  {suggestions.map((s, idx) => (
                    <div key={idx} onMouseDown={(e) => { e.preventDefault(); checkAndAddSong(s); }} className="px-6 py-4 hover:bg-indigo-50 transition border-b border-slate-50 last:border-0 cursor-pointer flex justify-between items-center group">
                      <span className="text-slate-700 group-hover:text-indigo-700 font-bold text-sm">{s}</span>
                      <span className="material-icons text-slate-300 group-hover:text-indigo-400 text-lg">add_circle</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <button onClick={() => checkAndAddSong(inputValue)} className="bg-indigo-600 text-white rounded-[1.5rem] px-6 hover:bg-indigo-700 active:scale-90"><span className="material-icons">add</span></button>
          </div>
        </div>

        {/* LISTA DE LOUVORES */}
        <div className="space-y-5">
          <div className="flex justify-between items-center px-1">
            <h3 className="font-extrabold text-slate-800 flex items-center gap-3">
              <span className="bg-indigo-600 text-white w-7 h-7 rounded-xl flex items-center justify-center text-[10px]">{draft.songs.length}</span>
              Louvores Selecionados
            </h3>
            {draft.songs.length > 0 && (
              <button onClick={shareViaWhatsApp} className="text-emerald-600 text-[10px] font-black uppercase tracking-widest hover:bg-emerald-50 px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <span className="material-icons text-sm">share</span> WhatsApp
              </button>
            )}
          </div>

          {draft.songs.length === 0 ? (
            <div className="text-center py-10 bg-slate-50/50 rounded-[2.5rem] border-2 border-dashed border-slate-200 text-slate-400">
              <p className="font-bold text-sm">Nenhum hino adicionado.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar p-1">
              {draft.songs.map((song, index) => (
                <div key={`${song}-${index}`} draggable onDragStart={() => setDraggedItemIndex(index)} onDragOver={(e) => { e.preventDefault(); if(draggedItemIndex !== null && draggedItemIndex !== index) { const songs = [...draft.songs]; const dragged = songs[draggedItemIndex]; songs.splice(draggedItemIndex, 1); songs.splice(index, 0, dragged); setDraggedItemIndex(index); setDraft(prev => ({ ...prev, songs })); } }} onDragEnd={() => setDraggedItemIndex(null)} className={`flex flex-col bg-white p-4 rounded-[1.5rem] border transition-all cursor-move ${draggedItemIndex === index ? 'opacity-40 border-indigo-400' : 'border-slate-100 hover:shadow-lg hover:border-indigo-100'}`}>
                  <div className="flex items-start gap-3 w-full mb-3">
                    <span className="material-icons text-slate-300 text-xl">reorder</span>
                    <span className="font-extrabold text-slate-700 text-sm flex-1">{song}</span>
                    <button onClick={() => setDraft(prev => ({ ...prev, songs: prev.songs.filter((_, i) => i !== index) }))} className="text-rose-300 hover:text-rose-600"><span className="material-icons">close</span></button>
                  </div>
                  <div className="flex gap-4 border-t border-slate-50 pt-3">
                    <button onMouseDown={() => setInfoModalData({ song, type: 'history' })} className="text-[8px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1"><span className="material-icons text-xs">history</span> Datas</button>
                    <button onMouseDown={() => setInfoModalData({ song, type: 'count' })} className="text-[8px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1"><span className="material-icons text-xs">bar_chart</span> Ranking</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <button onClick={() => setShowSaveConfirm(true)} disabled={draft.songs.length === 0} className={`w-full py-6 rounded-[2rem] font-black text-lg tracking-widest shadow-2xl transition-all active:scale-[0.97] flex items-center justify-center gap-4 ${draft.songs.length > 0 ? (editingId ? 'bg-amber-500 hover:bg-amber-600' : 'bg-indigo-600 hover:bg-indigo-700') + ' text-white shadow-indigo-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
          <span className="material-icons text-2xl">{editingId ? 'update' : 'save'}</span>
          {editingId ? 'ATUALIZAR CULTO' : 'SALVAR RELATÓRIO'}
        </button>
        {editingId && <button onClick={onCancelEdit} className="w-full py-2 text-slate-400 font-black uppercase text-[10px] tracking-widest">Cancelar Edição</button>}
      </div>

      {showSaveConfirm && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-sm p-10 animate-scaleUp text-center">
            <h3 className="text-2xl font-black text-slate-800 mb-4">{editingId ? 'Salvar Alterações?' : 'Finalizar Registro?'}</h3>
            <p className="text-slate-500 text-sm mb-6">Deseja confirmar o relatório de {draft.description} com {draft.songs.length} louvores?</p>
            <div className="flex flex-col gap-3">
              <button onClick={handleFinalSave} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 uppercase">Confirmar e Salvar</button>
              <button onClick={() => setShowSaveConfirm(false)} className="w-full py-3 text-slate-400 font-bold uppercase text-xs">Voltar</button>
            </div>
          </div>
        </div>
      )}

      {pendingSong && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm p-10 border-t-[12px] border-amber-400 animate-scaleUp text-center">
            <h3 className="text-2xl font-black text-slate-800 mb-2">Louvor Recente</h3>
            <p className="text-slate-500 text-sm mb-6">Cantado há {pendingSong.diff} dias.</p>
            <div className="flex flex-col gap-4">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl">ADICIONAR ASSIM MESMO</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}

      {infoModalData && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm" onClick={() => setInfoModalData(null)}>
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-extrabold text-slate-800 mb-8">{infoModalData.song}</h3>
            <div className="py-8 border-y border-slate-100 mb-8 max-h-60 overflow-y-auto custom-scrollbar">
              {infoModalData.type === 'history' ? (
                songStats[infoModalData.song]?.history.map((d, i) => (
                  <div key={i} className="p-4 bg-slate-50 rounded-2xl mb-2 flex justify-between">
                    <span className="font-bold">{new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  </div>
                ))
              ) : (
                <div className="text-center py-4"><span className="text-5xl font-black text-indigo-600">{songStats[infoModalData.song]?.count || 0}</span><p className="uppercase text-[10px] font-black text-slate-400 mt-2">Vezes cantado</p></div>
              )}
            </div>
            <button onClick={() => setInfoModalData(null)} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl">FECHAR</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, onClearAll }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(record => 
      record.date.includes(search) || 
      record.description?.toLowerCase().includes(search) ||
      record.songs.some(song => song.toLowerCase().includes(search)) ||
      (record.roles && (
        record.roles.gate.toLowerCase().includes(search) ||
        record.roles.praise.toLowerCase().includes(search) ||
        record.roles.word.toLowerCase().includes(search) ||
        record.roles.scripture.toLowerCase().includes(search)
      ))
    );
  }, [history, searchTerm]);

  const getDayOfWeek = (dateStr: string) => {
    const days = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
    return days[new Date(dateStr + 'T12:00:00').getDay()];
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr + 'T12:00:00');
    return date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });
  };

  const shareIndividual = (record: ServiceRecord) => {
    const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;

    if (record.roles) {
      message += `*Escala do Culto:*\n`;
      message += `🚪 Portão: ${record.roles.gate || '-'}\n`;
      message += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
      message += `📖 Texto: ${record.roles.scripture || '-'}\n`;
      message += `🎤 Palavra: ${record.roles.word || '-'}\n\n`;
    }

    message += `*Louvores:* \n`;
    record.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const RoleTag = ({ icon, label, name, isLong }: { icon: string, label: string, name?: string, isLong?: boolean }) => (
    <div className={`flex items-center gap-1.5 bg-slate-50 border border-slate-100 px-2 py-1 rounded-lg ${isLong ? 'flex-1 min-w-[120px]' : ''}`}>
      <span className="material-icons text-[12px] text-indigo-400">{icon}</span>
      <div className="flex flex-col overflow-hidden">
        <span className="text-[7px] font-black uppercase text-slate-400 leading-none">{label}</span>
        <span className="text-[9px] font-bold text-slate-700 leading-tight truncate max-w-[150px]">{name || '-'}</span>
      </div>
    </div>
  );

  if (history.length === 0) {
    return (
      <div className="bg-white rounded-[2.5rem] p-10 text-center animate-fadeIn border border-slate-100">
        <span className="material-icons text-6xl text-slate-200 mb-4">history_toggle_off</span>
        <h2 className="text-2xl font-black text-slate-400">Histórico Vazio</h2>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="flex justify-between items-center px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800">Histórico</h2>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{history.length} Cultos Salvos</span>
        </div>
      </div>

      <div className="relative">
        <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
        <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar por obreiro, data ou hino..." className="w-full pl-14 pr-4 py-5 bg-white border border-slate-200 rounded-[1.5rem] focus:ring-4 focus:ring-indigo-50 outline-none shadow-sm font-semibold" />
      </div>

      <div className="grid gap-4">
        {filteredHistory.map((record) => (
          <div key={record.id} className="bg-white rounded-[2rem] shadow-sm overflow-hidden border border-slate-100 animate-fadeIn group">
            <div className="bg-slate-50/80 px-6 py-4 flex justify-between items-center border-b border-slate-100">
              <div className="flex gap-3 items-center">
                <div className="bg-indigo-600 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm">
                  {getDayOfWeek(record.date)}
                </div>
                <div className="flex flex-col">
                  <span className="text-slate-800 font-black text-sm">{formatDate(record.date)}</span>
                  <span className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">{record.description}</span>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => onEdit(record)} className="w-9 h-9 text-amber-600 bg-white rounded-xl shadow-sm border border-amber-50 flex items-center justify-center"><span className="material-icons text-lg">edit</span></button>
                <button onClick={() => shareIndividual(record)} className="w-9 h-9 text-emerald-600 bg-white rounded-xl shadow-sm border border-emerald-50 flex items-center justify-center"><span className="material-icons text-lg">share</span></button>
                <button onClick={() => setItemToDelete(record.id)} className="w-9 h-9 text-rose-500 bg-white rounded-xl shadow-sm border border-rose-50 flex items-center justify-center"><span className="material-icons text-lg">delete_outline</span></button>
              </div>
            </div>

            {/* ESCALA VISUAL NO HISTÓRICO */}
            {record.roles && (
              <div className="px-6 py-3 flex flex-wrap gap-2 border-b border-slate-50 bg-white">
                <RoleTag icon="door_front" label="Portão" name={record.roles.gate} />
                <RoleTag icon="music_note" label="Louvor" name={record.roles.praise} />
                <RoleTag icon="auto_stories" label="Texto" name={record.roles.scripture} />
                <RoleTag icon="record_voice_over" label="Palavra" name={record.roles.word} isLong />
              </div>
            )}

            <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-1">
              {record.songs.map((song, i) => (
                <div key={i} className="flex items-center gap-3 py-1 border-b border-slate-50 last:border-0">
                  <span className="text-[10px] font-black text-indigo-300">{String(i + 1).padStart(2, '0')}</span>
                  <span className="text-slate-600 font-bold text-xs truncate">{song}</span>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp text-center">
            <h3 className="text-xl font-black text-slate-800">Apagar Registro?</h3>
            <div className="mt-8 flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete); setItemToDelete(null); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl">APAGAR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-3 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

export interface ServiceRoles {
  gate: string;      // Portão
  praise: string;    // Louvor
  word: string;      // Palavra (Obreiro selecionado)
  scripture: string; // Texto Bíblico (Livro e versículo digitados)
}

export interface ServiceRecord {
  id: string;
  date: string;
  description: string; // EBD, DOM, ou Dia da Semana
  songs: string[];
  roles: ServiceRoles;
}

export interface ServiceDraft {
  date: string;
  description: string;
  songs: string[];
  roles: ServiceRoles;
}

export interface SongStats {
  song: string;
  count: number;
  lastDate: string | null;
  history: string[];
}

export interface AppData {
  history: ServiceRecord[];
  customSongs?: string[];
  draft?: ServiceDraft;
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ 
  onSave, 
  songStats, 
  fullSongList, 
  onRegisterNewSong,
  draft,
  setDraft,
  editingId,
  onCancelEdit
}) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [infoModalData, setInfoModalData] = useState<{ song: string; type: 'history' | 'count' } | null>(null);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);

  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return {
      name: dayOfWeekNames[dayIndex],
      fullName: fullDayNames[dayIndex],
      isSunday: dayIndex === 0,
      isMonday: dayIndex === 1,
      isWednesday: dayIndex === 3
    };
  }, [draft.date]);

  // Sincronizar descrição automaticamente
  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) {
      setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    } else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) {
      setDraft(prev => ({ ...prev, description: 'DOM' }));
    }
  }, [dateInfo, editingId]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node) && 
          inputRef.current && !inputRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const suggestions = useMemo(() => {
    const search = inputValue.toLowerCase().trim();
    if (!search) return fullSongList.slice(0, 10);
    return fullSongList.filter(s => s.toLowerCase().includes(search)).slice(0, 15);
  }, [inputValue, fullSongList]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({
      ...prev,
      roles: { ...prev.roles, [role]: name }
    }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));
      if (diffDays <= 30) {
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate });
        setShowSuggestions(false);
        return;
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
    setTimeout(() => inputRef.current?.focus(), 100);
  };

  const shareViaWhatsApp = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${draft.description}\n\n`;
    message += `*Escala do Culto:*\n`;
    message += `🚪 Portão: ${draft.roles.gate || '-'}\n`;

    if (!dateInfo.isWednesday) {
      message += `🎵 Louvor: ${draft.roles.praise || '-'}\n`;
      if (!dateInfo.isMonday) {
        message += `🎤 Palavra: ${draft.roles.word || '-'}\n`;
      }
      if (draft.roles.word !== 'TRANSMISSÃO') {
        message += `📖 Texto Bíblico: ${draft.roles.scripture || '-'}\n`;
      }
    }

    message += `\n*Louvores:* \n`;
    draft.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const handleFinalSave = () => {
    onSave({ date: draft.date, description: draft.description, songs: draft.songs, roles: draft.roles });
    setShowSaveConfirm(false);
  };

  const RoleSelect = ({ label, icon, value, roleKey }: { label: string, icon: string, value: string, roleKey: keyof typeof draft.roles }) => (
    <div className="flex flex-col gap-2">
      <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 px-1">
        <span className="material-icons text-[14px]">{icon}</span> {label}
      </label>
      <div className="relative">
        <select 
          value={value}
          onChange={(e) => updateRole(roleKey, e.target.value)}
          className="w-full bg-white border border-slate-200 rounded-2xl pl-4 pr-10 py-3.5 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm appearance-none cursor-pointer"
        >
          <option value="">Selecione...</option>
          {WORKERS_LIST.map(name => (
            <option key={name} value={name}>{name}</option>
          ))}
        </select>
        <span className="material-icons absolute right-3 top-1/2 -translate-y-1/2 text-slate-300 pointer-events-none">expand_more</span>
      </div>
    </div>
  );

  return (
    <div className={`bg-white rounded-[2.5rem] shadow-xl shadow-slate-200/50 p-6 md:p-10 animate-fadeIn border ${editingId ? 'border-amber-400 border-2' : 'border-slate-100'}`}>
      <div className="flex flex-col gap-8">
        {editingId && (
          <div className="bg-amber-100 text-amber-900 p-3 rounded-2xl flex items-center justify-center gap-2 font-black uppercase text-[10px] tracking-widest animate-pulse">
            <span className="material-icons text-sm">edit</span> Editando Registro
          </div>
        )}

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 bg-slate-50/80 p-6 rounded-[2rem] border border-slate-100">
          <div>
            <div className="flex justify-between items-center mb-3 px-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block">Data do Culto</label>
              <span className={`px-2 py-0.5 rounded-lg text-[10px] font-black text-white ${dateInfo.isSunday ? 'bg-indigo-600' : 'bg-slate-400'}`}>
                {dateInfo.name}
              </span>
            </div>
            <div className="relative">
              <span className="material-icons absolute left-4 top-1/2 -translate-y-1/2 text-indigo-400">event</span>
              <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-white border border-slate-200 rounded-2xl pl-12 pr-4 py-4 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm" />
            </div>
          </div>

          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 block px-1">Tipo de Culto</label>
            {dateInfo.isSunday ? (
              <div className="flex bg-white border border-slate-200 p-1.5 rounded-2xl shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>EBD (Manhã)</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-400 hover:bg-slate-50'}`}>DOM (Noite)</button>
              </div>
            ) : (
              <div className="w-full bg-slate-100 border border-slate-200 rounded-2xl px-4 py-4 font-bold text-slate-400 text-sm flex items-center gap-2">
                <span className="material-icons text-sm">info_outline</span> {dateInfo.fullName}
              </div>
            )}
          </div>
        </div>

        {/* ESCALA DE OBREIROS COM LÓGICA DE VISIBILIDADE */}
        <div className="space-y-4">
          <h3 className="font-extrabold text-slate-800 text-sm flex items-center gap-2 px-1">
            <span className="material-icons text-indigo-600">people</span>
            Escala do Culto
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 bg-slate-50/50 p-6 rounded-[2rem] border border-slate-100">
            {/* PORTÃO: Sempre visível */}
            <RoleSelect label="Portão" icon="door_front" value={draft.roles.gate} roleKey="gate" />

            {/* LOUVOR: Visível exceto quarta */}
            {!dateInfo.isWednesday && (
              <RoleSelect label="Louvor" icon="music_note" value={draft.roles.praise} roleKey="praise" />
            )}

            {/* PALAVRA (Obreiro): Visível exceto segunda e quarta */}
            {!dateInfo.isWednesday && !dateInfo.isMonday && (
              <RoleSelect label="Palavra" icon="record_voice_over" value={draft.roles.word} roleKey="word" />
            )}

            {/* TEXTO BÍBLICO (Texto livre): Visível exceto quarta e se Palavra for Transmissão */}
            {!dateInfo.isWednesday && draft.roles.word !== 'TRANSMISSÃO' && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1.5 px-1">
                  <span className="material-icons text-[14px]">auto_stories</span> Texto Bíblico
                </label>
                <input 
                  type="text"
                  value={draft.roles.scripture}
                  onChange={(e) => updateRole('scripture', e.target.value)}
                  placeholder="Livro e versículo..."
                  className="w-full bg-white border border-slate-200 rounded-2xl px-4 py-3.5 focus:ring-4 focus:ring-indigo-50 outline-none font-bold text-slate-700 shadow-sm placeholder:font-normal placeholder:text-slate-300"
                />
              </div>
            )}
          </div>
        </div>

        {/* BUSCA DE LOUVORES */}
        <div className="relative">
          <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest mb-3 block px-1">Adicionar Louvor</label>
          <div className="flex gap-3">
            <div className="relative flex-1 group">
              <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
              <input ref={inputRef} type="text" value={inputValue} onKeyDown={(e) => e.key === 'Enter' && checkAndAddSong(inputValue)} onChange={(e) => { setInputValue(e.target.value); setShowSuggestions(true); }} onFocus={() => setShowSuggestions(true)} className="w-full pl-14 pr-4 py-5 bg-slate-50 border-2 border-transparent rounded-[1.5rem] focus:bg-white focus:border-indigo-100 outline-none transition-all font-semibold" placeholder="Buscar hino..." />
              {showSuggestions && suggestions.length > 0 && (
                <div ref={suggestionRef} className="absolute z-[110] w-full mt-3 bg-white border border-slate-200 rounded-[2rem] shadow-2xl overflow-hidden animate-scaleUp max-h-80 overflow-y-auto">
                  {suggestions.map((s, idx) => (
                    <div key={idx} onMouseDown={(e) => { e.preventDefault(); checkAndAddSong(s); }} className="px-6 py-4 hover:bg-indigo-50 transition border-b border-slate-50 last:border-0 cursor-pointer flex justify-between items-center group">
                      <span className="text-slate-700 group-hover:text-indigo-700 font-bold text-sm">{s}</span>
                      <span className="material-icons text-slate-300 group-hover:text-indigo-400 text-lg">add_circle</span>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <button onClick={() => checkAndAddSong(inputValue)} className="bg-indigo-600 text-white rounded-[1.5rem] px-6 hover:bg-indigo-700 active:scale-90"><span className="material-icons">add</span></button>
          </div>
        </div>

        {/* LISTA DE LOUVORES */}
        <div className="space-y-5">
          <div className="flex justify-between items-center px-1">
            <h3 className="font-extrabold text-slate-800 flex items-center gap-3">
              <span className="bg-indigo-600 text-white w-7 h-7 rounded-xl flex items-center justify-center text-[10px]">{draft.songs.length}</span>
              Louvores Selecionados
            </h3>
            {draft.songs.length > 0 && (
              <button onClick={shareViaWhatsApp} className="text-emerald-600 text-[10px] font-black uppercase tracking-widest hover:bg-emerald-50 px-3 py-1.5 rounded-full flex items-center gap-1.5">
                <span className="material-icons text-sm">share</span> WhatsApp
              </button>
            )}
          </div>

          {draft.songs.length === 0 ? (
            <div className="text-center py-10 bg-slate-50/50 rounded-[2.5rem] border-2 border-dashed border-slate-200 text-slate-400">
              <p className="font-bold text-sm">Nenhum hino adicionado.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-3 max-h-[400px] overflow-y-auto pr-2 custom-scrollbar p-1">
              {draft.songs.map((song, index) => (
                <div key={`${song}-${index}`} draggable onDragStart={() => setDraggedItemIndex(index)} onDragOver={(e) => { e.preventDefault(); if(draggedItemIndex !== null && draggedItemIndex !== index) { const songs = [...draft.songs]; const dragged = songs[draggedItemIndex]; songs.splice(draggedItemIndex, 1); songs.splice(index, 0, dragged); setDraggedItemIndex(index); setDraft(prev => ({ ...prev, songs })); } }} onDragEnd={() => setDraggedItemIndex(null)} className={`flex flex-col bg-white p-4 rounded-[1.5rem] border transition-all cursor-move ${draggedItemIndex === index ? 'opacity-40 border-indigo-400' : 'border-slate-100 hover:shadow-lg hover:border-indigo-100'}`}>
                  <div className="flex items-start gap-3 w-full mb-3">
                    <span className="material-icons text-slate-300 text-xl">reorder</span>
                    <span className="font-extrabold text-slate-700 text-sm flex-1">{song}</span>
                    <button onClick={() => setDraft(prev => ({ ...prev, songs: prev.songs.filter((_, i) => i !== index) }))} className="text-rose-300 hover:text-rose-600"><span className="material-icons">close</span></button>
                  </div>
                  <div className="flex gap-4 border-t border-slate-50 pt-3">
                    <button onMouseDown={() => setInfoModalData({ song, type: 'history' })} className="text-[8px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1"><span className="material-icons text-xs">history</span> Datas</button>
                    <button onMouseDown={() => setInfoModalData({ song, type: 'count' })} className="text-[8px] font-black text-slate-400 uppercase tracking-widest flex items-center gap-1"><span className="material-icons text-xs">bar_chart</span> Ranking</button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        <button onClick={() => setShowSaveConfirm(true)} disabled={draft.songs.length === 0} className={`w-full py-6 rounded-[2rem] font-black text-lg tracking-widest shadow-2xl transition-all active:scale-[0.97] flex items-center justify-center gap-4 ${draft.songs.length > 0 ? (editingId ? 'bg-amber-500 hover:bg-amber-600' : 'bg-indigo-600 hover:bg-indigo-700') + ' text-white shadow-indigo-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
          <span className="material-icons text-2xl">{editingId ? 'update' : 'save'}</span>
          {editingId ? 'ATUALIZAR CULTO' : 'SALVAR RELATÓRIO'}
        </button>
        {editingId && <button onClick={onCancelEdit} className="w-full py-2 text-slate-400 font-black uppercase text-[10px] tracking-widest">Cancelar Edição</button>}
      </div>

      {showSaveConfirm && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp text-center">
            <h3 className="text-2xl font-black text-slate-800 mb-4">{editingId ? 'Salvar Alterações?' : 'Finalizar Registro?'}</h3>
            <p className="text-slate-500 text-sm mb-6">Deseja confirmar o relatório de {draft.description} com {draft.songs.length} louvores?</p>
            <div className="flex flex-col gap-3">
              <button onClick={handleFinalSave} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-xl shadow-indigo-100 uppercase">Confirmar e Salvar</button>
              <button onClick={() => setShowSaveConfirm(false)} className="w-full py-3 text-slate-400 font-bold uppercase text-xs">Voltar</button>
            </div>
          </div>
        </div>
      )}

      {pendingSong && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm p-10 border-t-[12px] border-amber-400 animate-scaleUp text-center">
            <h3 className="text-2xl font-black text-slate-800 mb-2">Louvor Recente</h3>
            <p className="text-slate-500 text-sm mb-6">Cantado há {pendingSong.diff} dias.</p>
            <div className="flex flex-col gap-4">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl">ADICIONAR ASSIM MESMO</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}

      {infoModalData && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm" onClick={() => setInfoModalData(null)}>
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-extrabold text-slate-800 mb-8">{infoModalData.song}</h3>
            <div className="py-8 border-y border-slate-100 mb-8 max-h-60 overflow-y-auto custom-scrollbar">
              {infoModalData.type === 'history' ? (
                songStats[infoModalData.song]?.history.map((d, i) => (
                  <div key={i} className="p-4 bg-slate-50 rounded-2xl mb-2 flex justify-between">
                    <span className="font-bold">{new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  </div>
                ))
              ) : (
                <div className="text-center py-4"><span className="text-5xl font-black text-indigo-600">{songStats[infoModalData.song]?.count || 0}</span><p className="uppercase text-[10px] font-black text-slate-400 mt-2">Vezes cantado</p></div>
              )}
            </div>
            <button onClick={() => setInfoModalData(null)} className="w-full py-5 bg-slate-900 text-white font-black rounded-2xl">FECHAR</button>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, onClearAll }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(record => 
      record.date.includes(search) || 
      record.description?.toLowerCase().includes(search) ||
      record.songs.some(song => song.toLowerCase().includes(search)) ||
      (record.roles && (
        record.roles.gate.toLowerCase().includes(search) ||
        record.roles.praise.toLowerCase().includes(search) ||
        record.roles.word.toLowerCase().includes(search) ||
        record.roles.scripture.toLowerCase().includes(search)
      ))
    );
  }, [history, searchTerm]);

  const getDayOfWeek = (dateStr: string) => {
    const days = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
    return days[new Date(dateStr + 'T12:00:00').getDay()];
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr + 'T12:00:00');
    return date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });
  };

  const shareIndividual = (record: ServiceRecord) => {
    const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
    const dayName = getDayOfWeek(record.date);
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;

    if (record.roles) {
      message += `*Escala do Culto:*\n`;
      message += `🚪 Portão: ${record.roles.gate || '-'}\n`;

      if (dayName !== 'QUA') {
        message += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
        if (dayName !== 'SEG') {
          message += `🎤 Palavra: ${record.roles.word || '-'}\n`;
        }
        if (record.roles.word !== 'TRANSMISSÃO') {
          message += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
        }
      }
      message += '\n';
    }

    message += `*Louvores:* \n`;
    record.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const RoleTag = ({ icon, label, name, isLong }: { icon: string, label: string, name?: string, isLong?: boolean }) => (
    <div className={`flex items-center gap-1.5 bg-slate-50 border border-slate-100 px-2 py-1 rounded-lg ${isLong ? 'flex-1 min-w-[120px]' : ''}`}>
      <span className="material-icons text-[12px] text-indigo-400">{icon}</span>
      <div className="flex flex-col overflow-hidden">
        <span className="text-[7px] font-black uppercase text-slate-400 leading-none">{label}</span>
        <span className="text-[9px] font-bold text-slate-700 leading-tight truncate max-w-[150px]">{name || '-'}</span>
      </div>
    </div>
  );

  if (history.length === 0) {
    return (
      <div className="bg-white rounded-[2.5rem] p-10 text-center animate-fadeIn border border-slate-100">
        <span className="material-icons text-6xl text-slate-200 mb-4">history_toggle_off</span>
        <h2 className="text-2xl font-black text-slate-400">Histórico Vazio</h2>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="flex justify-between items-center px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800">Histórico</h2>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{history.length} Cultos Salvos</span>
        </div>
      </div>

      <div className="relative">
        <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
        <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar por obreiro, data ou hino..." className="w-full pl-14 pr-4 py-5 bg-white border border-slate-200 rounded-[1.5rem] focus:ring-4 focus:ring-indigo-50 outline-none shadow-sm font-semibold" />
      </div>

      <div className="grid gap-4">
        {filteredHistory.map((record) => {
          const dayName = getDayOfWeek(record.date);
          const isWed = dayName === 'QUA';
          const isMon = dayName === 'SEG';
          const isTransmissao = record.roles.word === 'TRANSMISSÃO';

          return (
            <div key={record.id} className="bg-white rounded-[2rem] shadow-sm overflow-hidden border border-slate-100 animate-fadeIn group">
              <div className="bg-slate-50/80 px-6 py-4 flex justify-between items-center border-b border-slate-100">
                <div className="flex gap-3 items-center">
                  <div className="bg-indigo-600 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm">
                    {dayName}
                  </div>
                  <div className="flex flex-col">
                    <span className="text-slate-800 font-black text-sm">{formatDate(record.date)}</span>
                    <span className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">{record.description}</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => onEdit(record)} className="w-9 h-9 text-amber-600 bg-white rounded-xl shadow-sm border border-amber-50 flex items-center justify-center"><span className="material-icons text-lg">edit</span></button>
                  <button onClick={() => shareIndividual(record)} className="w-9 h-9 text-emerald-600 bg-white rounded-xl shadow-sm border border-emerald-50 flex items-center justify-center"><span className="material-icons text-lg">share</span></button>
                  <button onClick={() => setItemToDelete(record.id)} className="w-9 h-9 text-rose-500 bg-white rounded-xl shadow-sm border border-rose-50 flex items-center justify-center"><span className="material-icons text-lg">delete_outline</span></button>
                </div>
              </div>

              {/* ESCALA VISUAL NO HISTÓRICO COM RESPEITO ÀS REGRAS */}
              {record.roles && (
                <div className="px-6 py-3 flex flex-wrap gap-2 border-b border-slate-50 bg-white">
                  <RoleTag icon="door_front" label="Portão" name={record.roles.gate} />
                  {!isWed && (
                    <RoleTag icon="music_note" label="Louvor" name={record.roles.praise} />
                  )}
                  {!isWed && !isMon && (
                    <RoleTag icon="record_voice_over" label="Palavra" name={record.roles.word} />
                  )}
                  {!isWed && !isTransmissao && record.roles.scripture && (
                    <RoleTag icon="auto_stories" label="Texto Bíblico" name={record.roles.scripture} isLong />
                  )}
                </div>
              )}

              <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-1">
                {record.songs.map((song, i) => (
                  <div key={i} className="flex items-center gap-3 py-1 border-b border-slate-50 last:border-0">
                    <span className="text-[10px] font-black text-indigo-300">{String(i + 1).padStart(2, '0')}</span>
                    <span className="text-slate-600 font-bold text-xs truncate">{song}</span>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp text-center">
            <h3 className="text-xl font-black text-slate-800">Apagar Registro?</h3>
            <div className="mt-8 flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete); setItemToDelete(null); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl">APAGAR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-3 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'unplayed' | 'workers' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const emptyRoles = {
    gate: '',
    praise: '',
    word: '',
    scripture: ''
  };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '', // Será definido pelo Form baseado na data
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) {
            setDraft({
              ...data.draft,
              date: getTodayDate(),
              roles: data.draft.roles || { ...emptyRoles }
            });
          }
        }
      } catch (e) {
        console.error("Erro ao carregar banco de dados local", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) {
      saveData({ history, customSongs, draft });
    }
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    const combined = [...new Set([...INITIAL_PRAISE_LIST.map(s => s.trim()), ...customSongs.map(s => s.trim())])];
    return combined.sort((a, b) => {
      const aIsCIAS = a.startsWith('(CIAS)');
      const bIsCIAS = b.startsWith('(CIAS)');
      if (aIsCIAS && !bIsCIAS) return 1;
      if (!aIsCIAS && bIsCIAS) return -1;
      return a.localeCompare(b);
    });
  }, [customSongs]);

  const saveServiceRecord = (recordData: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...recordData, id: editingId } : r));
      setEditingId(null);
    } else {
      const newRecord: ServiceRecord = { ...recordData, id: crypto.randomUUID() };
      setHistory(prev => [newRecord, ...prev]);
    }

    setDraft({
      date: getTodayDate(),
      description: '',
      songs: [],
      roles: { ...emptyRoles }
    });
    setActiveTab('history');
  };

  const handleStartEdit = (record: ServiceRecord) => {
    setEditingId(record.id);
    setDraft({
      date: record.date,
      description: record.description,
      songs: record.songs,
      roles: record.roles || { ...emptyRoles }
    });
    setActiveTab('new');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setDraft({
      date: getTodayDate(),
      description: '',
      songs: [],
      roles: { ...emptyRoles }
    });
  };

  const deleteServiceRecord = (id: string) => {
    if (editingId === id) setEditingId(null);
    setHistory(prev => prev.filter(r => r.id !== id));
  };

  const registerNewSong = (songName: string) => {
    const trimmedName = songName.trim();
    if (!fullSongList.includes(trimmedName)) {
      setCustomSongs(prev => [...prev, trimmedName]);
    }
  };

  const restoreData = (newHistory: ServiceRecord[], newCustomSongs?: string[]) => {
    setHistory(newHistory);
    if (newCustomSongs) setCustomSongs(newCustomSongs);
  };

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    const sortedHistory = [...history].sort((a, b) => b.date.localeCompare(a.date));
    sortedHistory.forEach(record => {
      record.songs.forEach(song => {
        const trimmedSong = song.trim();
        if (!stats[trimmedSong]) stats[trimmedSong] = { song: trimmedSong, count: 0, lastDate: null, history: [] };
        stats[trimmedSong].count += 1;
        stats[trimmedSong].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(song => {
      stats[song].history.sort((a, b) => b.localeCompare(a));
      stats[song].lastDate = stats[song].history[0] || null;
    });
    return stats;
  }, [history]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-6 text-center">
        <div className="text-white space-y-4">
          <div className="animate-spin rounded-full h-14 w-14 border-4 border-white/20 border-t-white mx-auto"></div>
          <p className="font-bold text-lg tracking-wide uppercase">Carregando...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col pb-24 md:pb-0">
      {isOffline && (
        <div className="bg-amber-500 text-white text-[10px] font-black uppercase tracking-[0.2em] py-1.5 text-center flex items-center justify-center gap-2 animate-pulse z-[200]">
          <span className="material-icons text-sm">cloud_off</span>
          Modo Offline Ativado
        </div>
      )}

      <header className="glass-effect sticky top-0 z-[100] border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 p-2.5 rounded-2xl shadow-lg shadow-indigo-200 transform rotate-3">
              <span className="material-icons text-white text-2xl">library_music</span>
            </div>
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 leading-tight">ICM Santo Antônio II</h1>
              <span className="text-[10px] font-black uppercase tracking-[0.15em] text-indigo-500 block">Gestão de Louvores</span>
            </div>
          </div>
          <nav className="hidden lg:flex bg-slate-100 p-1 rounded-2xl gap-1">
            <button onClick={() => setActiveTab('new')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'new' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Novo Culto</button>
            <button onClick={() => setActiveTab('history')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'history' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Histórico</button>
            <button onClick={() => setActiveTab('workers')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'workers' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Escala</button>
            <button onClick={() => setActiveTab('unplayed')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'unplayed' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Restantes</button>
            <button onClick={() => setActiveTab('settings')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'settings' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Backup</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-6xl mx-auto p-4 md:p-8">
        <div className="animate-fadeIn">
          {activeTab === 'new' && (
            <div className="max-w-4xl mx-auto space-y-8">
              <ServiceForm 
                onSave={saveServiceRecord} 
                songStats={songStats}
                fullSongList={fullSongList}
                onRegisterNewSong={registerNewSong}
                draft={draft}
                setDraft={setDraft}
                editingId={editingId}
                onCancelEdit={handleCancelEdit}
              />
              <RankingList songStats={songStats} />
            </div>
          )}
          {activeTab === 'history' && (
            <HistoryList history={history} onDelete={deleteServiceRecord} onEdit={handleStartEdit} onClearAll={() => { if(confirm("Apagar todo o histórico?")) setHistory([]); }} />
          )}
          {activeTab === 'workers' && (
            <WorkerStats history={history} />
          )}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={restoreData} />}
        </div>
      </main>

      <nav className="md:hidden fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] glass-effect border border-slate-200/50 flex justify-around p-3 z-[100] shadow-2xl rounded-3xl">
        <button onClick={() => setActiveTab('new')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'new' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">{editingId ? 'edit' : 'add_circle'}</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Novo</span>
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'history' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">history</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Histórico</span>
        </button>
        <button onClick={() => setActiveTab('workers')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'workers' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">assignment_ind</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Escala</span>
        </button>
        <button onClick={() => setActiveTab('unplayed')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'unplayed' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">assignment_late</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Restantes</span>
        </button>
        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'settings' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">settings</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Backup</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, onClearAll }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(record => 
      record.date.includes(search) || 
      record.description?.toLowerCase().includes(search) ||
      record.songs.some(song => song.toLowerCase().includes(search)) ||
      (record.roles && (
        record.roles.gate.toLowerCase().includes(search) ||
        record.roles.praise.toLowerCase().includes(search) ||
        record.roles.word.toLowerCase().includes(search) ||
        record.roles.scripture.toLowerCase().includes(search)
      ))
    );
  }, [history, searchTerm]);

  const getDayOfWeek = (dateStr: string) => {
    const days = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
    return days[new Date(dateStr + 'T12:00:00').getDay()];
  };

  const formatDate = (dateStr: string) => {
    const date = new Date(dateStr + 'T12:00:00');
    return date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });
  };

  const shareIndividual = (record: ServiceRecord) => {
    const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
    const dayName = getDayOfWeek(record.date);
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;

    if (record.roles) {
      message += `*Escala do Culto:*\n`;
      message += `🚪 Portão: ${record.roles.gate || '-'}\n`;

      if (dayName !== 'QUA') {
        message += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
        if (dayName !== 'SEG') {
          message += `🎤 Palavra: ${record.roles.word || '-'}\n`;
        }
        if (record.roles.word !== 'TRANSMISSÃO') {
          message += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
        }
      }
      message += '\n';
    }

    message += `*Louvores:* \n`;
    record.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const shareBulk = (type: 'month' | 'all') => {
    let list = [...history].sort((a, b) => a.date.localeCompare(b.date));

    if (type === 'month') {
      const now = new Date();
      const currentMonth = now.getMonth();
      const currentYear = now.getFullYear();
      list = list.filter(r => {
        const d = new Date(r.date + 'T12:00:00');
        return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      });
    }

    if (list.length === 0) {
      alert("Nenhum registro encontrado para este período.");
      return;
    }

    const title = type === 'month' ? 'Resumo Mensal' : 'Histórico Completo';
    let message = `*${title} - ICM Santo Antônio II*\n\n`;

    list.forEach(record => {
      const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
      message += `📅 *${dateFormatted}* (${record.description})\n`;
      if (record.roles && record.roles.word) {
        message += `🎤 Palavra: ${record.roles.word}\n`;
      }
      message += `🎵 Louvores: ${record.songs.length}\n`;
      message += `------------------\n`;
    });

    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const RoleTag = ({ icon, label, name, isLong }: { icon: string, label: string, name?: string, isLong?: boolean }) => (
    <div className={`flex items-center gap-1.5 bg-slate-50 border border-slate-100 px-2 py-1 rounded-lg ${isLong ? 'flex-1 min-w-[120px]' : ''}`}>
      <span className="material-icons text-[12px] text-indigo-400">{icon}</span>
      <div className="flex flex-col overflow-hidden">
        <span className="text-[7px] font-black uppercase text-slate-400 leading-none">{label}</span>
        <span className="text-[9px] font-bold text-slate-700 leading-tight truncate max-w-[150px]">{name || '-'}</span>
      </div>
    </div>
  );

  if (history.length === 0) {
    return (
      <div className="bg-white rounded-[2.5rem] p-10 text-center animate-fadeIn border border-slate-100">
        <span className="material-icons text-6xl text-slate-200 mb-4">history_toggle_off</span>
        <h2 className="text-2xl font-black text-slate-400">Histórico Vazio</h2>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="flex flex-col md:flex-row md:justify-between md:items-end gap-4 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800">Histórico</h2>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{history.length} Cultos Salvos</span>
        </div>
        <div className="flex flex-wrap gap-2">
          <button onClick={() => shareBulk('month')} className="bg-emerald-50 text-emerald-700 border border-emerald-100 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-emerald-100 transition-all shadow-sm">
            <span className="material-icons text-sm">share</span> Do Mês
          </button>
          <button onClick={() => shareBulk('all')} className="bg-indigo-50 text-indigo-700 border border-indigo-100 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-100 transition-all shadow-sm">
            <span className="material-icons text-sm">list_alt</span> Todos
          </button>
        </div>
      </div>

      <div className="relative">
        <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
        <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar por obreiro, data ou hino..." className="w-full pl-14 pr-4 py-5 bg-white border border-slate-200 rounded-[1.5rem] focus:ring-4 focus:ring-indigo-50 outline-none shadow-sm font-semibold" />
      </div>

      <div className="grid gap-4">
        {filteredHistory.map((record) => {
          const dayName = getDayOfWeek(record.date);
          const isWed = dayName === 'QUA';
          const isMon = dayName === 'SEG';
          const isTransmissao = record.roles.word === 'TRANSMISSÃO';

          return (
            <div key={record.id} className="bg-white rounded-[2rem] shadow-sm overflow-hidden border border-slate-100 animate-fadeIn group">
              <div className="bg-slate-50/80 px-6 py-4 flex justify-between items-center border-b border-slate-100">
                <div className="flex gap-3 items-center">
                  <div className="bg-indigo-600 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm">
                    {dayName}
                  </div>
                  <div className="flex flex-col">
                    <span className="text-slate-800 font-black text-sm">{formatDate(record.date)}</span>
                    <span className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">{record.description}</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => onEdit(record)} className="w-9 h-9 text-amber-600 bg-white rounded-xl shadow-sm border border-amber-50 flex items-center justify-center"><span className="material-icons text-lg">edit</span></button>
                  <button onClick={() => shareIndividual(record)} className="w-9 h-9 text-emerald-600 bg-white rounded-xl shadow-sm border border-emerald-50 flex items-center justify-center"><span className="material-icons text-lg">share</span></button>
                  <button onClick={() => setItemToDelete(record.id)} className="w-9 h-9 text-rose-500 bg-white rounded-xl shadow-sm border border-rose-50 flex items-center justify-center"><span className="material-icons text-lg">delete_outline</span></button>
                </div>
              </div>

              {record.roles && (
                <div className="px-6 py-3 flex flex-wrap gap-2 border-b border-slate-50 bg-white">
                  <RoleTag icon="door_front" label="Portão" name={record.roles.gate} />
                  {!isWed && (
                    <RoleTag icon="music_note" label="Louvor" name={record.roles.praise} />
                  )}
                  {!isWed && !isMon && (
                    <RoleTag icon="record_voice_over" label="Palavra" name={record.roles.word} />
                  )}
                  {!isWed && !isTransmissao && record.roles.scripture && (
                    <RoleTag icon="auto_stories" label="Texto Bíblico" name={record.roles.scripture} isLong />
                  )}
                </div>
              )}

              <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-1">
                {record.songs.map((song, i) => (
                  <div key={i} className="flex items-center gap-3 py-1 border-b border-slate-50 last:border-0">
                    <span className="text-[10px] font-black text-indigo-300">{String(i + 1).padStart(2, '0')}</span>
                    <span className="text-slate-600 font-bold text-xs truncate">{song}</span>
                  </div>
                ))}
              </div>
            </div>
          );
        })}
      </div>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp text-center">
            <h3 className="text-xl font-black text-slate-800">Apagar Registro?</h3>
            <div className="mt-8 flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete); setItemToDelete(null); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl">APAGAR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-3 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

