import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const CULTOS = [
  { id: 'SEG', label: 'SEGUNDA', fullName: 'SEGUNDA-FEIRA', roles: ['gate', 'word'] },
  { id: 'TER', label: 'TERÇA', fullName: 'TERÇA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'QUA', label: 'QUARTA', fullName: 'QUARTA-FEIRA', roles: ['gate'] },
  { id: 'QUI', label: 'QUINTA', fullName: 'QUINTA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'SÁB', label: 'SÁBADO', fullName: 'SÁBADO', roles: ['gate', 'praise', 'word'] },
  { id: 'EBD', label: 'EBD', fullName: 'EBD', roles: ['gate', 'praise', 'word'] },
  { id: 'DOM', label: 'DOM', fullName: 'DOM', roles: ['gate', 'praise', 'word'] }
];

const ROLE_LABELS: Record<string, string> = {
  gate: 'Portão',
  praise: 'Louvor',
  word: 'Palavra'
};

const WorkerStats: React.FC<Props> = ({ history }) => {
  const [expandedDay, setExpandedDay] = useState<string | null>(null);

  // Filtrar obreiros oficiais
  const officialWorkers = useMemo(() => 
    WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name)),
  []);

  const getStats = (dayFullName: string, role: 'gate' | 'praise' | 'word') => {
    const today = new Date();
    today.setHours(12, 0, 0, 0);

    const stats = officialWorkers.map(name => {
      // Filtrar histórico deste dia e onde o obreiro fez a função
      const filtered = history
        .filter(r => r.description === dayFullName && r.roles[role] === name)
        .sort((a, b) => b.date.localeCompare(a.date));

      const lastDate = filtered[0]?.date || null;
      let daysSince = Infinity;

      if (lastDate) {
        const d = new Date(lastDate + 'T12:00:00');
        daysSince = Math.ceil((today.getTime() - d.getTime()) / (1000 * 60 * 60 * 24));
      }

      return { name, lastDate, daysSince };
    });

    // Ordenar por quem está há mais tempo sem fazer (maior daysSince)
    return stats.sort((a, b) => b.daysSince - a.daysSince);
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Sugestão de Escala</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">
          Obreiros ordenados por quem realizou a função há mais tempo
        </p>
      </div>

      <div className="grid gap-4">
        {CULTOS.map(culto => (
          <div key={culto.id} className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
            <button 
              onClick={() => setExpandedDay(expandedDay === culto.id ? null : culto.id)}
              className="w-full px-6 py-5 flex items-center justify-between bg-slate-50/50 hover:bg-slate-50 transition-colors"
            >
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-[10px] shadow-sm ${expandedDay === culto.id ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400 border border-slate-100'}`}>
                  {culto.id}
                </div>
                <div className="text-left">
                  <span className="block font-black text-slate-700 text-sm tracking-wide">{culto.fullName}</span>
                  <span className="text-[8px] font-bold text-slate-400 uppercase tracking-widest">Clique para ver sugestões</span>
                </div>
              </div>
              <span className={`material-icons text-slate-300 transition-transform ${expandedDay === culto.id ? 'rotate-180' : ''}`}>expand_more</span>
            </button>

            {expandedDay === culto.id && (
              <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fadeIn">
                {culto.roles.map(role => {
                  const stats = getStats(culto.fullName, role as any);
                  return (
                    <div key={role} className="space-y-4">
                      <div className="flex items-center gap-2 border-b border-slate-50 pb-2">
                        <span className="material-icons text-indigo-400 text-sm">
                          {role === 'gate' ? 'door_front' : role === 'praise' ? 'music_note' : 'record_voice_over'}
                        </span>
                        <h4 className="font-black text-[10px] text-slate-500 uppercase tracking-widest">{ROLE_LABELS[role]}</h4>
                      </div>
                      <div className="space-y-2">
                        {stats.map((worker, i) => (
                          <div key={worker.name} className={`flex items-center justify-between p-3 rounded-xl border ${i === 0 ? 'bg-indigo-50/50 border-indigo-100' : 'bg-slate-50/30 border-transparent'}`}>
                            <span className="text-xs font-bold text-slate-700">{worker.name}</span>
                            <div className="text-right">
                              <span className={`text-[9px] font-black uppercase ${worker.daysSince === Infinity ? 'text-emerald-500' : 'text-indigo-400'}`}>
                                {worker.daysSince === Infinity ? 'Nunca Realizou' : `Há ${worker.daysSince} dias`}
                              </span>
                              {worker.lastDate && (
                                <span className="block text-[7px] font-medium text-slate-400">
                                  {new Date(worker.lastDate + 'T12:00:00').toLocaleDateString('pt-BR')}
                                </span>
                              )}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default WorkerStats;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'ranking' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) {
            setDraft({
              ...data.draft,
              date: getTodayDate(),
              roles: data.draft.roles || { ...emptyRoles }
            });
          }
        }
      } catch (e) {
        console.error("Erro ao carregar banco de dados local", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) {
      saveData({ history, customSongs, draft });
    }
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    const combined = [...new Set([...INITIAL_PRAISE_LIST.map(s => s.trim()), ...customSongs.map(s => s.trim())])];
    return combined.sort((a, b) => {
      const aIsCIAS = a.startsWith('(CIAS)');
      const bIsCIAS = b.startsWith('(CIAS)');
      if (aIsCIAS && !bIsCIAS) return 1;
      if (!aIsCIAS && bIsCIAS) return -1;
      return a.localeCompare(b);
    });
  }, [customSongs]);

  const saveServiceRecord = (recordData: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...recordData, id: editingId } : r));
      setEditingId(null);
    } else {
      const newRecord: ServiceRecord = { ...recordData, id: crypto.randomUUID() };
      setHistory(prev => [newRecord, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
    setActiveTab('history');
  };

  const handleStartEdit = (record: ServiceRecord) => {
    setEditingId(record.id);
    setDraft({ date: record.date, description: record.description, songs: record.songs, roles: record.roles || { ...emptyRoles } });
    setActiveTab('new');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const deleteServiceRecord = (id: string) => {
    if (editingId === id) setEditingId(null);
    setHistory(prev => prev.filter(r => r.id !== id));
  };

  const registerNewSong = (songName: string) => {
    const trimmedName = songName.trim();
    if (!fullSongList.includes(trimmedName)) {
      setCustomSongs(prev => [...prev, trimmedName]);
    }
  };

  const restoreData = (newHistory: ServiceRecord[], newCustomSongs?: string[]) => {
    setHistory(newHistory);
    if (newCustomSongs) setCustomSongs(newCustomSongs);
  };

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    const sortedHistory = [...history].sort((a, b) => b.date.localeCompare(a.date));
    sortedHistory.forEach(record => {
      record.songs.forEach(song => {
        const trimmedSong = song.trim();
        if (!stats[trimmedSong]) stats[trimmedSong] = { song: trimmedSong, count: 0, lastDate: null, history: [] };
        stats[trimmedSong].count += 1;
        stats[trimmedSong].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(song => {
      stats[song].history.sort((a, b) => b.localeCompare(a));
      stats[song].lastDate = stats[song].history[0] || null;
    });
    return stats;
  }, [history]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-indigo-600 flex items-center justify-center p-6 text-center">
        <div className="text-white space-y-4">
          <div className="animate-spin rounded-full h-14 w-14 border-4 border-white/20 border-t-white mx-auto"></div>
          <p className="font-bold text-lg tracking-wide uppercase">Carregando...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col pb-24 md:pb-0">
      {isOffline && (
        <div className="bg-amber-500 text-white text-[10px] font-black uppercase tracking-[0.2em] py-1.5 text-center flex items-center justify-center gap-2 animate-pulse z-[200]">
          <span className="material-icons text-sm">cloud_off</span>
          Modo Offline Ativado
        </div>
      )}

      <header className="glass-effect sticky top-0 z-[100] border-b border-slate-200 shadow-sm">
        <div className="max-w-6xl mx-auto px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gradient-to-br from-indigo-500 to-indigo-700 p-2.5 rounded-2xl shadow-lg shadow-indigo-200 transform rotate-3">
              <span className="material-icons text-white text-2xl">library_music</span>
            </div>
            <div>
              <h1 className="text-xl font-extrabold text-slate-900 leading-tight">ICM Santo Antônio II</h1>
              <span className="text-[10px] font-black uppercase tracking-[0.15em] text-indigo-500 block">Gestão de Louvores</span>
            </div>
          </div>
          <nav className="hidden lg:flex bg-slate-100 p-1 rounded-2xl gap-1">
            <button onClick={() => setActiveTab('new')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'new' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Novo</button>
            <button onClick={() => setActiveTab('history')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'history' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Histórico</button>
            <button onClick={() => setActiveTab('ranking')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'ranking' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Ranking</button>
            <button onClick={() => setActiveTab('workers')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'workers' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Escala</button>
            <button onClick={() => setActiveTab('unplayed')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'unplayed' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Restantes</button>
            <button onClick={() => setActiveTab('settings')} className={`px-5 py-2.5 rounded-xl text-sm font-bold tab-transition ${activeTab === 'settings' ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}>Backup</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-6xl mx-auto p-4 md:p-8">
        <div className="animate-fadeIn">
          {activeTab === 'new' && (
            <div className="max-w-4xl mx-auto space-y-8">
              <ServiceForm onSave={saveServiceRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={registerNewSong} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={handleCancelEdit} />
              <RankingList songStats={songStats} />
            </div>
          )}
          {activeTab === 'history' && <HistoryList history={history} onDelete={deleteServiceRecord} onEdit={handleStartEdit} onClearAll={() => { if(confirm("Apagar tudo?")) setHistory([]); }} />}
          {activeTab === 'ranking' && <WorkerRanking history={history} />}
          {activeTab === 'workers' && <WorkerStats history={history} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={restoreData} />}
        </div>
      </main>

      <nav className="md:hidden fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] glass-effect border border-slate-200/50 flex justify-around p-3 z-[100] shadow-2xl rounded-3xl">
        <button onClick={() => setActiveTab('new')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'new' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">add_circle</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Novo</span>
        </button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'history' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">history</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Histórico</span>
        </button>
        <button onClick={() => setActiveTab('ranking')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'ranking' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">emoji_events</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Ranking</span>
        </button>
        <button onClick={() => setActiveTab('workers')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'workers' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">assignment_ind</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Escala</span>
        </button>
        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 transition-all ${activeTab === 'settings' ? 'text-indigo-600 scale-110' : 'text-slate-400'}`}>
          <span className="material-icons">settings</span>
          <span className="text-[10px] font-black uppercase tracking-tighter">Backup</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit, onClearAll }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [shareMonth, setShareMonth] = useState(new Date().getMonth());
  const [shareYear, setShareYear] = useState(new Date().getFullYear());

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(record => 
      record.date.includes(search) || 
      record.description?.toLowerCase().includes(search) ||
      record.songs.some(song => song.toLowerCase().includes(search)) ||
      (record.roles && (
        record.roles.gate.toLowerCase().includes(search) ||
        record.roles.praise.toLowerCase().includes(search) ||
        record.roles.word.toLowerCase().includes(search) ||
        record.roles.scripture.toLowerCase().includes(search)
      ))
    );
  }, [history, searchTerm]);

  const monthOptions = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

  const getDayOfWeek = (dateStr: string) => {
    const days = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
    return days[new Date(dateStr + 'T12:00:00').getDay()];
  };

  const shareIndividual = (record: ServiceRecord) => {
    const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
    const dayName = getDayOfWeek(record.date);
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;

    if (record.roles) {
      message += `*Escala do Culto:*\n`;
      message += `🚪 Portão: ${record.roles.gate || '-'}\n`;
      if (dayName !== 'QUA') {
        message += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
        if (dayName !== 'SEG') message += `🎤 Palavra: ${record.roles.word || '-'}\n`;
        if (record.roles.word !== 'TRANSMISSÃO') message += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      }
      message += '\n';
    }
    message += `*Louvores:* \n`;
    record.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const shareBySelectedMonth = () => {
    const list = [...history].filter(r => {
      const d = new Date(r.date + 'T12:00:00');
      return d.getMonth() === shareMonth && d.getFullYear() === shareYear;
    }).sort((a, b) => a.date.localeCompare(b.date));

    if (list.length === 0) {
      alert("Nenhum registro encontrado para este período.");
      return;
    }

    let message = `*Relatório Mensal (${monthOptions[shareMonth]} ${shareYear}) - ICM Santo Antônio II*\n\n`;
    list.forEach(record => {
      const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
      message += `📅 *${dateFormatted}* (${record.description})\n`;
      if (record.roles && record.roles.word) message += `🎤 Palavra: ${record.roles.word}\n`;
      message += `🎵 Louvores: ${record.songs.length}\n`;
      message += `------------------\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const shareAll = () => {
    const list = [...history].sort((a, b) => a.date.localeCompare(b.date));
    let message = `*Histórico Geral - ICM Santo Antônio II*\n\n`;
    list.forEach(record => {
      const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
      message += `📅 *${dateFormatted}* (${record.description}) - 🎤 ${record.roles?.word || '-'}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="flex flex-col md:flex-row md:justify-between md:items-end gap-6 px-2">
        <div>
          <h2 className="text-2xl font-black text-slate-800">Histórico</h2>
          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{history.length} Cultos Salvos</span>
        </div>
        <div className="bg-white p-4 rounded-[2rem] shadow-sm border border-slate-100 flex flex-wrap gap-4 items-center">
          <div className="flex gap-2">
            <select value={shareMonth} onChange={e => setShareMonth(parseInt(e.target.value))} className="bg-slate-50 border-none rounded-xl text-[10px] font-black uppercase px-3 py-2 outline-none">
              {monthOptions.map((m, i) => <option key={i} value={i}>{m}</option>)}
            </select>
            <select value={shareYear} onChange={e => setShareYear(parseInt(e.target.value))} className="bg-slate-50 border-none rounded-xl text-[10px] font-black uppercase px-3 py-2 outline-none">
              {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <div className="flex gap-2">
            <button onClick={shareBySelectedMonth} className="bg-emerald-500 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-emerald-600 shadow-lg shadow-emerald-100"><span className="material-icons text-sm">calendar_month</span> Mês</button>
            <button onClick={shareAll} className="bg-indigo-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-indigo-700 shadow-lg shadow-indigo-100"><span className="material-icons text-sm">public</span> Tudo</button>
          </div>
        </div>
      </div>

      <div className="relative">
        <span className="material-icons absolute left-5 top-1/2 -translate-y-1/2 text-slate-400">search</span>
        <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Buscar obreiro, hino..." className="w-full pl-14 pr-4 py-5 bg-white border border-slate-200 rounded-[1.5rem] focus:ring-4 focus:ring-indigo-50 outline-none shadow-sm font-semibold" />
      </div>

      <div className="grid gap-4">
        {filteredHistory.map((record) => {
          const dayName = getDayOfWeek(record.date);
          return (
            <div key={record.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-100 animate-fadeIn group">
              <div className="bg-slate-50/80 px-6 py-4 flex justify-between items-center border-b border-slate-100">
                <div className="flex gap-3 items-center">
                  <div className="bg-indigo-600 text-white text-[10px] font-black px-2 py-1 rounded-lg shadow-sm">{dayName}</div>
                  <div className="flex flex-col">
                    <span className="text-slate-800 font-black text-sm">{new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                    <span className="text-[9px] font-black text-indigo-500 uppercase tracking-widest">{record.description}</span>
                  </div>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => onEdit(record)} className="w-9 h-9 text-amber-600 bg-white rounded-xl shadow-sm border border-amber-50 flex items-center justify-center"><span className="material-icons text-lg">edit</span></button>
                  <button onClick={() => shareIndividual(record)} className="w-9 h-9 text-emerald-600 bg-white rounded-xl shadow-sm border border-emerald-50 flex items-center justify-center"><span className="material-icons text-lg">share</span></button>
                  <button onClick={() => setItemToDelete(record.id)} className="w-9 h-9 text-rose-500 bg-white rounded-xl shadow-sm border border-rose-50 flex items-center justify-center"><span className="material-icons text-lg">delete_outline</span></button>
                </div>
              </div>
              {record.roles && (
                <div className="px-6 py-3 flex flex-wrap gap-2 border-b border-slate-50 bg-white">
                  <div className="flex items-center gap-1.5 bg-slate-50 border px-2 py-1 rounded-lg"><span className="material-icons text-[12px] text-indigo-400">door_front</span><span className="text-[9px] font-bold text-slate-700">{record.roles.gate || '-'}</span></div>
                  {dayName !== 'QUA' && <div className="flex items-center gap-1.5 bg-slate-50 border px-2 py-1 rounded-lg"><span className="material-icons text-[12px] text-indigo-400">music_note</span><span className="text-[9px] font-bold text-slate-700">{record.roles.praise || '-'}</span></div>}
                  {dayName !== 'QUA' && dayName !== 'SEG' && <div className="flex items-center gap-1.5 bg-slate-50 border px-2 py-1 rounded-lg"><span className="material-icons text-[12px] text-indigo-400">record_voice_over</span><span className="text-[9px] font-bold text-slate-700">{record.roles.word || '-'}</span></div>}
                  {record.roles.word !== 'TRANSMISSÃO' && record.roles.scripture && <div className="flex items-center gap-1.5 bg-slate-50 border px-2 py-1 rounded-lg"><span className="material-icons text-[12px] text-indigo-400">auto_stories</span><span className="text-[9px] font-bold text-slate-700">{record.roles.scripture}</span></div>}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[200] p-6 backdrop-blur-sm">
          <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp text-center">
            <h3 className="text-xl font-black text-slate-800">Apagar Registro?</h3>
            <div className="mt-8 flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete); setItemToDelete(null); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl">APAGAR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-3 text-slate-400 font-bold">CANCELAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, dates: string[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: string[], praise: string[], word: string[], total: number }> = {};

    // Inicializar apenas obreiros oficiais
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));
    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });

    history.forEach(r => {
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(r.date);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(r.date);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(r.date);
    });

    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.localeCompare(a));
      data[name].praise.sort((a, b) => b.localeCompare(a));
      data[name].word.sort((a, b) => b.localeCompare(a));
    });

    return Object.entries(data)
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => b.total - a.total);
  }, [history]);

  const StatCard = ({ label, count, onClick }: { label: string, count: number, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 group"
    >
      <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1 group-hover:text-indigo-500">{label}</span>
      <span className="text-2xl font-black text-indigo-700 leading-none mb-2">{count}</span>
      <span className="material-icons text-slate-300 text-sm group-hover:text-indigo-300">history</span>
    </button>
  );

  return (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Ranking Geral</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Soma de atividades registradas</p>
      </div>

      <div className="grid gap-8">
        {stats.map((worker) => (
          <div key={worker.name} className="bg-slate-50 rounded-[2.5rem] overflow-hidden shadow-xl shadow-slate-200/50 border border-white">
            {/* Header Navy */}
            <div className="bg-[#1a1c3d] px-8 py-6 flex justify-between items-center">
              <h3 className="text-white font-black text-xl tracking-tight uppercase">{worker.name}</h3>
              <div className="bg-[#ffcc00] text-[#1a1c3d] px-5 py-2 rounded-full font-black text-xs shadow-lg">
                {worker.total} ATOS
              </div>
            </div>

            {/* Cards Content */}
            <div className="p-4 flex gap-4">
              <StatCard label="Portão" count={worker.gate.length} onClick={() => setModalData({ worker: worker.name, role: 'Portão', dates: worker.gate })} />
              <StatCard label="Louvor" count={worker.praise.length} onClick={() => setModalData({ worker: worker.name, role: 'Louvor', dates: worker.praise })} />
              <StatCard label="Palavra" count={worker.word.length} onClick={() => setModalData({ worker: worker.name, role: 'Palavra', dates: worker.word })} />
            </div>
          </div>
        ))}
      </div>

      {modalData && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[300] p-6 backdrop-blur-md" onClick={() => setModalData(null)}>
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-md p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-800 leading-tight">{modalData.worker}</h3>
                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em]">{modalData.role}</span>
              </div>
              <button onClick={() => setModalData(null)} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center"><span className="material-icons text-slate-400">close</span></button>
            </div>

            <div className="max-h-[60vh] overflow-y-auto pr-4 custom-scrollbar space-y-3">
              {modalData.dates.length > 0 ? (
                modalData.dates.map((d, i) => (
                  <div key={i} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <span className="font-bold text-slate-700">{new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                    <span className="text-[8px] font-black text-slate-300 uppercase">#{modalData.dates.length - i}</span>
                  </div>
                ))
              ) : (
                <div className="py-10 text-center text-slate-300 italic">Nenhuma atividade registrada</div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkerRanking;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props { history: ServiceRecord[]; }

const CULTOS = [
  { id: 'SEG', label: 'SEGUNDA', fullName: 'SEGUNDA-FEIRA', roles: ['gate', 'word'] },
  { id: 'TER', label: 'TERÇA', fullName: 'TERÇA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'QUA', label: 'QUARTA', fullName: 'QUARTA-FEIRA', roles: ['gate'] },
  { id: 'QUI', label: 'QUINTA', fullName: 'QUINTA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'SÁB', label: 'SÁBADO', fullName: 'SÁBADO', roles: ['gate', 'praise', 'word'] },
  { id: 'EBD', label: 'EBD', fullName: 'EBD', roles: ['gate', 'praise', 'word'] },
  { id: 'DOM', label: 'DOM', fullName: 'DOM', roles: ['gate', 'praise', 'word'] }
];

const WorkerStats: React.FC<Props> = ({ history }) => {
  const [expandedDay, setExpandedDay] = useState<string | null>(null);
  const [expandedRoles, setExpandedRoles] = useState<Record<string, boolean>>({});

  const officialWorkers = useMemo(() => WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name)), []);

  const getStats = (dayFullName: string, role: 'gate' | 'praise' | 'word') => {
    const today = new Date(); today.setHours(12, 0, 0, 0);
    return officialWorkers.map(name => {
      const filtered = history.filter(r => r.description === dayFullName && r.roles[role] === name).sort((a, b) => b.date.localeCompare(a.date));
      const lastDate = filtered[0]?.date || null;
      let daysSince = Infinity;
      if (lastDate) daysSince = Math.ceil((today.getTime() - new Date(lastDate + 'T12:00:00').getTime()) / (1000 * 60 * 60 * 24));
      return { name, lastDate, daysSince };
    }).sort((a, b) => b.daysSince - a.daysSince);
  };

  const toggleRole = (dayId: string, role: string) => {
    const key = `${dayId}-${role}`;
    setExpandedRoles(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Sugestão de Escala</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Quem realizou a função há mais tempo</p>
      </div>

      <div className="grid gap-4">
        {CULTOS.map(culto => (
          <div key={culto.id} className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
            <button onClick={() => setExpandedDay(expandedDay === culto.id ? null : culto.id)} className="w-full px-6 py-5 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-[10px] shadow-sm ${expandedDay === culto.id ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{culto.id}</div>
                <span className="font-black text-slate-700 text-sm tracking-wide">{culto.fullName}</span>
              </div>
              <span className={`material-icons text-slate-300 transition-transform ${expandedDay === culto.id ? 'rotate-180' : ''}`}>expand_more</span>
            </button>

            {expandedDay === culto.id && (
              <div className="p-6 space-y-6 animate-fadeIn">
                {culto.roles.map(role => {
                  const isRoleExpanded = expandedRoles[`${culto.id}-${role}`];
                  const stats = getStats(culto.fullName, role as any);
                  return (
                    <div key={role} className="border border-slate-50 rounded-2xl overflow-hidden">
                      <button onClick={() => toggleRole(culto.id, role)} className="w-full px-4 py-3 flex items-center justify-between bg-white hover:bg-slate-50">
                        <div className="flex items-center gap-2">
                          <span className="material-icons text-indigo-400 text-sm">{role === 'gate' ? 'door_front' : role === 'praise' ? 'music_note' : 'record_voice_over'}</span>
                          <span className="font-black text-[10px] text-slate-500 uppercase tracking-widest">{role === 'gate' ? 'Portão' : role === 'praise' ? 'Louvor' : 'Palavra'}</span>
                        </div>
                        <span className={`material-icons text-slate-200 text-sm transition-transform ${isRoleExpanded ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
                      </button>
                      {isRoleExpanded && (
                        <div className="p-4 bg-slate-50/30 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                          {stats.map((worker, i) => (
                            <div key={worker.name} className={`flex items-center justify-between p-3 rounded-xl border ${i === 0 ? 'bg-indigo-50/50 border-indigo-100' : 'bg-white border-transparent'}`}>
                              <span className="text-xs font-bold text-slate-700">{worker.name}</span>
                              <div className="text-right">
                                <span className={`text-[9px] font-black uppercase ${worker.daysSince === Infinity ? 'text-emerald-500' : 'text-indigo-400'}`}>
                                  {worker.daysSince === Infinity ? 'Inédito' : `${worker.daysSince}d`}
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default WorkerStats;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praises' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) {
            setDraft({
              ...data.draft,
              date: getTodayDate(),
              roles: data.draft.roles || { ...emptyRoles }
            });
          }
        }
      } catch (e) {
        console.error("Erro ao carregar banco de dados local", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) {
      saveData({ history, customSongs, draft });
    }
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    const combined = [...new Set([...INITIAL_PRAISE_LIST.map(s => s.trim()), ...customSongs.map(s => s.trim())])];
    return combined.sort((a, b) => {
      const aIsCIAS = a.startsWith('(CIAS)');
      const bIsCIAS = b.startsWith('(CIAS)');
      if (aIsCIAS && !bIsCIAS) return 1;
      if (!aIsCIAS && bIsCIAS) return -1;
      return a.localeCompare(b);
    });
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    const sortedHistory = [...history].sort((a, b) => b.date.localeCompare(a.date));
    sortedHistory.forEach(record => {
      record.songs.forEach(song => {
        const trimmedSong = song.trim();
        if (!stats[trimmedSong]) stats[trimmedSong] = { song: trimmedSong, count: 0, lastDate: null, history: [] };
        stats[trimmedSong].count += 1;
        stats[trimmedSong].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(song => {
      stats[song].history.sort((a, b) => b.localeCompare(a));
      stats[song].lastDate = stats[song].history[0] || null;
    });
    return stats;
  }, [history]);

  const saveServiceRecord = (recordData: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...recordData, id: editingId } : r));
      setEditingId(null);
    } else {
      const newRecord: ServiceRecord = { ...recordData, id: crypto.randomUUID() };
      setHistory(prev => [newRecord, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
    setActiveTab('history');
  };

  const handleStartEdit = (record: ServiceRecord) => {
    setEditingId(record.id);
    setDraft({ date: record.date, description: record.description, songs: record.songs, roles: record.roles || { ...emptyRoles } });
    setActiveTab('new');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleCancelEdit = () => {
    setEditingId(null);
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const deleteServiceRecord = (id: string) => {
    if (editingId === id) setEditingId(null);
    setHistory(prev => prev.filter(r => r.id !== id));
  };

  const registerNewSong = (songName: string) => {
    const trimmedName = songName.trim();
    if (!fullSongList.includes(trimmedName)) {
      setCustomSongs(prev => [...prev, trimmedName]);
    }
  };

  const restoreData = (newHistory: ServiceRecord[], newCustomSongs?: string[]) => {
    setHistory(newHistory);
    if (newCustomSongs) setCustomSongs(newCustomSongs);
  };

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col pb-24 md:pb-0">
      <header className="bg-[#1a1c3d] text-white py-4 px-6 sticky top-0 z-[100] shadow-xl">
        <div className="max-w-6xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            <span className="material-icons text-amber-400">church</span>
            <h1 className="font-black text-lg tracking-tight">ICM SANTO ANTÔNIO II</h1>
          </div>
          <nav className="hidden lg:flex gap-1 bg-white/5 p-1 rounded-xl">
            <button onClick={() => setActiveTab('new')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'new' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Novo</button>
            <button onClick={() => setActiveTab('history')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'history' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Histórico</button>
            <button onClick={() => setActiveTab('workers')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'workers' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Obreiros</button>
            <button onClick={() => setActiveTab('suggestions')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'suggestions' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Escala</button>
            <button onClick={() => setActiveTab('praises')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'praises' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Louvores</button>
            <button onClick={() => setActiveTab('settings')} className={`px-4 py-2 rounded-lg text-xs font-black uppercase tracking-widest ${activeTab === 'settings' ? 'bg-amber-400 text-[#1a1c3d]' : 'hover:bg-white/10'}`}>Backup</button>
          </nav>
        </div>
      </header>

      <main className="flex-1 w-full max-w-6xl mx-auto p-4 md:p-8">
        <div className="animate-fadeIn">
          {activeTab === 'new' && (
            <div className="max-w-4xl mx-auto">
              <ServiceForm onSave={saveServiceRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={registerNewSong} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={handleCancelEdit} />
            </div>
          )}
          {activeTab === 'history' && (
            <HistoryList history={history} onDelete={deleteServiceRecord} onEdit={handleStartEdit} onClearAll={() => {}} />
          )}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praises' && (
            <div className="space-y-8">
              <RankingList songStats={songStats} />
              <UnplayedList fullSongList={fullSongList} history={history} />
            </div>
          )}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={restoreData} />}
        </div>
      </main>

      <nav className="lg:hidden fixed bottom-6 left-1/2 -translate-x-1/2 w-[95%] bg-[#1a1c3d] text-white flex justify-around p-3 z-[100] shadow-2xl rounded-[2rem]">
        <button onClick={() => setActiveTab('new')} className={`flex flex-col items-center gap-1 ${activeTab === 'new' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">add_circle</span><span className="text-[8px] font-black uppercase">Novo</span></button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 ${activeTab === 'history' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">history</span><span className="text-[8px] font-black uppercase">Histórico</span></button>
        <button onClick={() => setActiveTab('workers')} className={`flex flex-col items-center gap-1 ${activeTab === 'workers' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">emoji_events</span><span className="text-[8px] font-black uppercase">Ranking</span></button>
        <button onClick={() => setActiveTab('suggestions')} className={`flex flex-col items-center gap-1 ${activeTab === 'suggestions' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">assignment_ind</span><span className="text-[8px] font-black uppercase">Escala</span></button>
        <button onClick={() => setActiveTab('praises')} className={`flex flex-col items-center gap-1 ${activeTab === 'praises' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">library_music</span><span className="text-[8px] font-black uppercase">Hinos</span></button>
      </nav>
    </div>
  );
};

