import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareMonth, setShareMonth] = useState(new Date().getMonth());
  const [shareYear, setShareYear] = useState(new Date().getFullYear());

  const monthOptions = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(r => r.date.includes(search) || r.roles?.word.toLowerCase().includes(search) || r.songs.some(s => s.toLowerCase().includes(search)));
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const dateFormatted = new Date(record.date + 'T12:00:00').toLocaleDateString('pt-BR');
    const dayIndex = new Date(record.date + 'T12:00:00').getDay();
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;
    message += `*Escala do Culto:*\n`;
    message += `🚪 Portão: ${record.roles.gate || '-'}\n`;
    if (dayIndex !== 3) {
      message += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
      if (dayIndex !== 1) message += `🎤 Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') message += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
    }
    message += `\n*Louvores:* \n`;
    record.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const shareBulk = (type: 'month' | 'all') => {
    let list = [...history].sort((a, b) => a.date.localeCompare(b.date));
    if (type === 'month') {
      list = list.filter(r => {
        const d = new Date(r.date + 'T12:00:00');
        return d.getMonth() === shareMonth && d.getFullYear() === shareYear;
      });
    }
    if (list.length === 0) return alert("Nenhum registro para este período.");
    let message = `*Relatório ${type === 'month' ? 'Mensal' : 'Completo'} - ICM Santo Antônio II*\n\n`;
    list.forEach(r => {
      const dF = new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR');
      message += `📅 *${dF}* (${r.description})\n🎤 Palavra: ${r.roles.word}\n🎵 Louvores: ${r.songs.length}\n----------\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      {/* HEADER DESIGN IMAGEM ENVIADA */}
      <div className="bg-[#1a1c3d] -mx-4 md:-mx-8 px-4 md:px-8 py-8 mb-8 rounded-b-[3rem] shadow-2xl relative">
        <div className="max-w-4xl mx-auto flex items-center gap-3">
          <div className="relative flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-inner">
            <span className="material-icons text-slate-300 mr-3">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar..." 
              className="w-full bg-transparent outline-none text-slate-600 font-medium placeholder:text-slate-300"
            />
          </div>
          <button onClick={() => setShowShareModal(true)} className="bg-white/10 hover:bg-white/20 w-12 h-12 rounded-full flex items-center justify-center transition-all">
            <span className="material-icons text-white">calendar_month</span>
          </button>
          <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] hover:bg-[#ffaa00] w-14 h-14 rounded-full flex items-center justify-center shadow-lg shadow-orange-950/20 transition-all transform active:scale-90">
            <span className="material-icons text-white text-3xl">auto_stories</span>
          </button>
        </div>
      </div>

      <div className="grid gap-4 max-w-4xl mx-auto">
        {filteredHistory.map(r => (
          <div key={r.id} className="bg-white rounded-[2rem] shadow-sm border border-slate-200 overflow-hidden">
            <div className="px-8 py-5 flex justify-between items-center bg-slate-50/50 border-b border-slate-100">
              <div className="flex flex-col">
                <span className="text-slate-900 font-black text-sm">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{r.description}</span>
              </div>
              <div className="flex gap-2">
                <button onClick={() => onEdit(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-amber-500"><span className="material-icons text-lg">edit</span></button>
                <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-emerald-500"><span className="material-icons text-lg">share</span></button>
                <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-rose-500"><span className="material-icons text-lg">delete</span></button>
              </div>
            </div>
            <div className="p-8 grid grid-cols-1 sm:grid-cols-2 gap-2">
              {r.songs.map((s, i) => (
                <div key={i} className="text-xs font-bold text-slate-600 flex items-center gap-2">
                  <span className="text-indigo-300">#{(i+1).toString().padStart(2,'0')}</span> {s}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center z-[300] p-6 backdrop-blur-xl" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-black text-slate-800 mb-8 text-center">Compartilhar Relatórios</h3>
            <div className="space-y-6">
              <div className="flex gap-2">
                <select value={shareMonth} onChange={e => setShareMonth(parseInt(e.target.value))} className="flex-1 bg-slate-50 border-none rounded-xl px-4 py-3 font-bold text-sm">
                  {monthOptions.map((m, i) => <option key={i} value={i}>{m}</option>)}
                </select>
                <select value={shareYear} onChange={e => setShareYear(parseInt(e.target.value))} className="w-24 bg-slate-50 border-none rounded-xl px-4 py-3 font-bold text-sm">
                  {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
              </div>
              <button onClick={() => shareBulk('month')} className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl flex items-center justify-center gap-3 shadow-lg shadow-emerald-100">
                <span className="material-icons">calendar_month</span> MÊS SELECIONADO
              </button>
              <button onClick={() => shareBulk('all')} className="w-full py-4 text-indigo-600 font-black border-2 border-indigo-50 rounded-2xl flex items-center justify-center gap-3">
                <span className="material-icons">history</span> TODO O HISTÓRICO
              </button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-slate-900/80 flex items-center justify-center z-[300] p-6" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-xs animate-scaleUp text-center" onClick={e => e.stopPropagation()}>
            <h3 className="text-lg font-black text-slate-800 mb-8">Confirmar exclusão?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-4 bg-rose-600 text-white font-black rounded-2xl">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-3 text-slate-400 font-bold uppercase text-[10px]">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, dates: string[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: string[], praise: string[], word: string[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));
    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });
    history.forEach(r => {
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(r.date);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(r.date);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(r.date);
    });
    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.localeCompare(a));
      data[name].praise.sort((a, b) => b.localeCompare(a));
      data[name].word.sort((a, b) => b.localeCompare(a));
    });
    return Object.entries(data).map(([name, val]) => ({ name, ...val })).sort((a, b) => b.total - a.total);
  }, [history]);

  const StatCard = ({ label, count, onClick }: { label: string, count: number, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-[1.5rem] p-6 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 group"
    >
      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">{label}</span>
      <span className="text-4xl font-black text-indigo-700 leading-none mb-3">{count}</span>
      <span className="material-icons text-slate-200 text-sm">history</span>
    </button>
  );

  return (
    <div className="space-y-8 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Ranking Obreiros</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Dados consolidados de atividades</p>
      </div>

      <div className="grid gap-8 max-w-4xl mx-auto">
        {stats.map((worker) => (
          <div key={worker.name} className="bg-white rounded-[3rem] overflow-hidden shadow-2xl shadow-slate-200/60 border border-white">
            <div className="bg-[#1a1c3d] px-10 py-8 flex justify-between items-center">
              <h3 className="text-white font-black text-2xl tracking-tight">{worker.name}</h3>
              <div className="bg-[#ffcc00] text-[#1a1c3d] px-6 py-2.5 rounded-full font-black text-xs shadow-xl">
                {worker.total} ATOS
              </div>
            </div>
            <div className="p-6 flex gap-4 bg-slate-50/30">
              <StatCard label="Portão" count={worker.gate.length} onClick={() => setModalData({ worker: worker.name, role: 'Portão', dates: worker.gate })} />
              <StatCard label="Louvor" count={worker.praise.length} onClick={() => setModalData({ worker: worker.name, role: 'Louvor', dates: worker.praise })} />
              <StatCard label="Palavra" count={worker.word.length} onClick={() => setModalData({ worker: worker.name, role: 'Palavra', dates: worker.word })} />
            </div>
          </div>
        ))}
      </div>

      {modalData && (
        <div className="fixed inset-0 bg-slate-900/90 flex items-center justify-center z-[300] p-6 backdrop-blur-xl" onClick={() => setModalData(null)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-md p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-800">{modalData.worker}</h3>
                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{modalData.role}</span>
              </div>
              <button onClick={() => setModalData(null)} className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center"><span className="material-icons text-slate-400">close</span></button>
            </div>
            <div className="max-h-[50vh] overflow-y-auto pr-4 custom-scrollbar space-y-3">
              {modalData.dates.map((d, i) => (
                <div key={i} className="flex justify-between items-center p-5 bg-slate-50 rounded-2xl border border-slate-100">
                  <span className="font-bold text-slate-700">{new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[9px] font-black text-slate-300 uppercase">Ato #{modalData.dates.length - i}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

