import React, { useState, useMemo, useRef, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [infoModalData, setInfoModalData] = useState<{ song: string; type: 'history' | 'count' } | null>(null);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showSaveConfirm, setShowSaveConfirm] = useState(false);
  const [draggedItemIndex, setDraggedItemIndex] = useState<number | null>(null);
  const inputRef = useRef<HTMLInputElement>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);
    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));
      if (diffDays <= 30) { setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); return; }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareViaWhatsApp = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${draft.description}\n\n`;
    message += `*Escala do Culto:*\n`;
    message += `🚪 Portão: ${draft.roles.gate || '-'}\n`;
    if (!dateInfo.isWednesday) {
      message += `🎵 Louvor: ${draft.roles.praise || '-'}\n`;
      if (!dateInfo.isMonday) message += `🎤 Palavra: ${draft.roles.word || '-'}\n`;
      if (draft.roles.word !== 'TRANSMISSÃO') message += `📖 Texto Bíblico: ${draft.roles.scripture || '-'}\n`;
    }
    message += `\n*Louvores:* \n`;
    draft.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className={`bg-white rounded-[3rem] shadow-2xl p-8 md:p-12 animate-fadeIn border ${editingId ? 'border-amber-400 border-2' : 'border-slate-100'}`}>
      <div className="flex flex-col gap-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100">
          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Data do Culto</label>
            <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-white border border-slate-200 rounded-2xl px-5 py-4 font-bold text-slate-700 shadow-sm outline-none" />
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Tipo de Culto</label>
            {dateInfo.isSunday ? (
              <div className="flex bg-white border border-slate-200 p-1.5 rounded-2xl shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-xl ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-xl ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white' : 'text-slate-400'}`}>DOM</button>
              </div>
            ) : (
              <div className="w-full bg-slate-200/50 border border-slate-200 rounded-2xl px-5 py-4 font-black text-slate-400 text-sm">{dateInfo.fullName}</div>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="font-black text-slate-800 text-sm tracking-widest uppercase">Escala</h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 bg-slate-50/50 p-8 rounded-[2.5rem] border border-slate-100">
            <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🚪 Portão</label>
              <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            {!dateInfo.isWednesday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎵 Louvor</label>
                <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && !dateInfo.isMonday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎤 Palavra</label>
                <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && draft.roles.word !== 'TRANSMISSÃO' && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">📖 Texto Bíblico</label>
                <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro/Versículo" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none" />
              </div>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Buscar Louvor</label>
          <div className="flex gap-4">
            <input type="text" value={inputValue} onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} onFocus={() => setShowSuggestions(true)} className="flex-1 px-8 py-5 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none" placeholder="Nome ou número..." />
            <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white px-8 rounded-2xl active:scale-95"><span className="material-icons">add</span></button>
          </div>
          {showSuggestions && inputValue.length > 1 && (
            <div className="absolute z-[200] w-full max-w-lg bg-white shadow-2xl rounded-3xl overflow-hidden border border-slate-200 max-h-64 overflow-y-auto">
              {fullSongList.filter(s => s.toLowerCase().includes(inputValue.toLowerCase())).slice(0, 20).map(s => (
                <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-sm text-slate-700">{s}</div>
              ))}
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="flex justify-between items-center px-2">
            <h4 className="font-black text-slate-800 uppercase text-xs tracking-widest">Lista do Culto</h4>
            {draft.songs.length > 0 && <button onClick={shareViaWhatsApp} className="text-emerald-600 font-black text-[10px] uppercase flex items-center gap-2"><span className="material-icons text-sm">share</span> WhatsApp</button>}
          </div>
          <div className="space-y-3">
            {draft.songs.map((s, i) => (
              <div key={i} className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100 group">
                <span className="font-bold text-slate-700 text-sm"><span className="text-indigo-300 mr-2">#{i+1}</span> {s}</span>
                <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-300 opacity-0 group-hover:opacity-100 transition-opacity"><span className="material-icons">close</span></button>
              </div>
            ))}
          </div>
        </div>

        <button onClick={() => onSave(draft)} disabled={draft.songs.length === 0} className={`w-full py-6 rounded-3xl font-black text-lg tracking-widest transition-all active:scale-95 ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white shadow-xl shadow-indigo-200' : 'bg-slate-200 text-slate-400'}`}>
          {editingId ? 'ATUALIZAR' : 'SALVAR RELATÓRIO'}
        </button>
      </div>
    </div>
  );
};

export default ServiceForm;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) setDraft({ ...data.draft, date: getTodayDate(), roles: data.draft.roles || { ...emptyRoles } });
        }
      } catch (e) {
        console.error("Erro no DB", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) saveData({ history, customSongs, draft });
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
    setActiveTab('history');
  };

  const NavItem = ({ id, icon, label }: { id: typeof activeTab, icon: string, label: string }) => (
    <button 
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/60 hover:text-white hover:bg-white/5'}`}
    >
      <span className="material-icons">{icon}</span>
      <span className="text-xs uppercase tracking-widest">{label}</span>
    </button>
  );

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex items-center justify-center text-white font-black">CARREGANDO...</div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl">
        <div className="p-8 border-b border-white/5">
          <h1 className="text-white font-black text-xl leading-tight">ICM SANTO<br/>ANTÔNIO II</h1>
          <div className="mt-2 w-12 h-1.5 bg-amber-400 rounded-full"></div>
        </div>
        <nav className="flex-1 py-6 overflow-y-auto custom-scrollbar">
          <NavItem id="new" icon="add_circle" label="Novo Culto" />
          <NavItem id="history" icon="history" label="Histórico" />
          <NavItem id="workers" icon="emoji_events" label="Ranking Obreiros" />
          <NavItem id="suggestions" icon="assignment_ind" label="Escala / Dias" />
          <NavItem id="praise-ranking" icon="trending_up" label="Ranking Hinos" />
          <NavItem id="unplayed" icon="assignment_late" label="Restantes" />
          <NavItem id="settings" icon="settings" label="Backup e Config" />
        </nav>
        <div className="p-6 border-t border-white/5 text-[10px] text-white/30 font-black uppercase tracking-[0.2em]">
          Versão 2.5 Pro
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 min-w-0">
        {isOffline && (
          <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-1.5 text-center">Modo Offline</div>
        )}

        <div className="p-4 md:p-10 animate-fadeIn">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={(h, c) => { setHistory(h); setCustomSongs(c); }} />}
        </div>
      </main>

      {/* Mobile Nav */}
      <nav className="md:hidden fixed bottom-0 left-0 right-0 bg-[#1a1c3d] text-white flex justify-around p-3 z-[200] border-t border-white/5 shadow-2xl overflow-x-auto no-scrollbar">
        <button onClick={() => setActiveTab('new')} className={`flex flex-col items-center gap-1 min-w-[60px] ${activeTab === 'new' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">add_circle</span><span className="text-[7px] font-black uppercase">Novo</span></button>
        <button onClick={() => setActiveTab('history')} className={`flex flex-col items-center gap-1 min-w-[60px] ${activeTab === 'history' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">history</span><span className="text-[7px] font-black uppercase">Histórico</span></button>
        <button onClick={() => setActiveTab('workers')} className={`flex flex-col items-center gap-1 min-w-[60px] ${activeTab === 'workers' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">emoji_events</span><span className="text-[7px] font-black uppercase">Ranking</span></button>
        <button onClick={() => setActiveTab('suggestions')} className={`flex flex-col items-center gap-1 min-w-[60px] ${activeTab === 'suggestions' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">assignment_ind</span><span className="text-[7px] font-black uppercase">Escala</span></button>
        <button onClick={() => setActiveTab('settings')} className={`flex flex-col items-center gap-1 min-w-[60px] ${activeTab === 'settings' ? 'text-amber-400' : 'text-white/40'}`}><span className="material-icons">settings</span><span className="text-[7px] font-black uppercase">Backup</span></button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [showShareModal, setShowShareModal] = useState(false);
  const [shareMonth, setShareMonth] = useState(new Date().getMonth());
  const [shareYear, setShareYear] = useState(new Date().getFullYear());

  const monthOptions = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(r => r.date.includes(search) || r.roles?.word.toLowerCase().includes(search) || r.songs.some(s => s.toLowerCase().includes(search)));
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;
    msg += `🚪 Portão: ${record.roles.gate || '-'}\n`;
    if (day !== 3) {
      msg += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `🎤 Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
    }
    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareBulk = (type: 'month' | 'all') => {
    let list = [...history].sort((a, b) => a.date.localeCompare(b.date));
    if (type === 'month') list = list.filter(r => { const d = new Date(r.date + 'T12:00:00'); return d.getMonth() === shareMonth && d.getFullYear() === shareYear; });
    if (list.length === 0) return alert("Nenhum registro para este período.");
    let msg = `*Relatório ${type === 'month' ? 'Mensal' : 'Geral'} - ICM Santo Antônio II*\n\n`;
    list.forEach(r => msg += `📅 *${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}* (${r.description})\n🎤 Palavra: ${r.roles.word}\n🎵 Louvores: ${r.songs.length}\n----------\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-6 animate-fadeIn">
      {/* HEADER DESIGN EXATO DA IMAGEM */}
      <div className="bg-[#1a1c3d] -mx-4 md:-mx-10 px-6 md:px-10 py-10 rounded-b-[4rem] shadow-2xl relative">
        <div className="max-w-5xl mx-auto flex items-center gap-4">
          <div className="relative flex-1 bg-white rounded-full flex items-center px-8 py-5 shadow-2xl">
            <span className="material-icons text-slate-300 mr-4 text-2xl">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar..." 
              className="w-full bg-transparent outline-none text-slate-600 font-bold text-lg placeholder:text-slate-300 placeholder:font-medium"
            />
          </div>
          <button onClick={() => setShowShareModal(true)} className="bg-white/10 hover:bg-white/20 w-14 h-14 rounded-full flex items-center justify-center transition-all group">
            <span className="material-icons text-white group-hover:scale-110">calendar_month</span>
          </button>
          <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] hover:bg-[#ffaa00] w-16 h-16 rounded-full flex items-center justify-center shadow-2xl shadow-orange-950/40 transition-all transform active:scale-90">
            <span className="material-icons text-white text-3xl">auto_stories</span>
          </button>
        </div>
      </div>

      <div className="grid gap-6 max-w-5xl mx-auto pt-6">
        {filteredHistory.map(r => (
          <div key={r.id} className="bg-white rounded-[2.5rem] shadow-lg border border-slate-100 overflow-hidden group hover:shadow-xl transition-all">
            <div className="px-8 py-6 flex justify-between items-center bg-slate-50/50 border-b border-slate-100">
              <div className="flex items-center gap-4">
                <div className="bg-indigo-600 w-12 h-12 rounded-2xl flex items-center justify-center text-white font-black text-xs shadow-lg">
                  {new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR', { day: '2-digit' })}
                </div>
                <div className="flex flex-col">
                  <span className="text-slate-900 font-black text-lg">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR', { month: 'long', year: 'numeric' })}</span>
                  <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em]">{r.description}</span>
                </div>
              </div>
              <div className="flex gap-2">
                <button onClick={() => onEdit(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-amber-500 hover:bg-amber-50"><span className="material-icons text-xl">edit</span></button>
                <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-emerald-500 hover:bg-emerald-50"><span className="material-icons text-xl">share</span></button>
                <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-rose-500 hover:bg-rose-50"><span className="material-icons text-xl">delete</span></button>
              </div>
            </div>
            <div className="p-8 space-y-3">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {r.songs.map((s, i) => (
                  <div key={i} className="text-sm font-bold text-slate-600 flex items-center gap-3 bg-slate-50 p-3 rounded-xl border border-transparent group-hover:border-slate-100">
                    <span className="text-indigo-400 font-black">#{(i+1).toString().padStart(2,'0')}</span>
                    <span className="truncate">{s}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        ))}
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[300] p-6 backdrop-blur-md" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm p-12 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <h3 className="text-2xl font-black text-slate-800 mb-10 text-center tracking-tight">RELATÓRIOS</h3>
            <div className="space-y-6">
              <div className="flex gap-2">
                <select value={shareMonth} onChange={e => setShareMonth(parseInt(e.target.value))} className="flex-1 bg-slate-50 border-none rounded-2xl px-5 py-4 font-black text-sm outline-none">
                  {monthOptions.map((m, i) => <option key={i} value={i}>{m}</option>)}
                </select>
                <select value={shareYear} onChange={e => setShareYear(parseInt(e.target.value))} className="w-28 bg-slate-50 border-none rounded-2xl px-5 py-4 font-black text-sm outline-none">
                  {[2024, 2025, 2026].map(y => <option key={y} value={y}>{y}</option>)}
                </select>
              </div>
              <button onClick={() => shareBulk('month')} className="w-full py-6 bg-emerald-600 text-white font-black rounded-3xl flex items-center justify-center gap-4 shadow-2xl shadow-emerald-900/20 active:scale-95 transition-all">
                <span className="material-icons">share</span> MÊS ESCOLHIDO
              </button>
              <button onClick={() => shareBulk('all')} className="w-full py-5 text-indigo-600 font-black border-4 border-indigo-50 rounded-3xl flex items-center justify-center gap-4 hover:bg-indigo-50 active:scale-95 transition-all">
                <span className="material-icons">history</span> TUDO O QUE JÁ FOI
              </button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[300] p-6" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3rem] p-12 w-full max-w-xs animate-scaleUp text-center" onClick={e => e.stopPropagation()}>
            <div className="w-20 h-20 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-6">
              <span className="material-icons text-rose-500 text-4xl">delete_forever</span>
            </div>
            <h3 className="text-xl font-black text-slate-800 mb-10">Deseja realmente apagar?</h3>
            <div className="flex flex-col gap-4">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-xl shadow-rose-900/20 active:scale-95">SIM, APAGAR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-400 font-black uppercase text-xs tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, dates: string[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: string[], praise: string[], word: string[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));
    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });
    history.forEach(r => {
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(r.date);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(r.date);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(r.date);
    });
    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.localeCompare(a));
      data[name].praise.sort((a, b) => b.localeCompare(a));
      data[name].word.sort((a, b) => b.localeCompare(a));
    });
    return Object.entries(data).map(([name, val]) => ({ name, ...val })).sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick }: { label: string, count: number, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-[1.5rem] p-6 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 group-hover:text-indigo-500">{label}</span>
      <span className="text-5xl font-black text-indigo-700 leading-none mb-4">{count}</span>
      <span className="material-icons text-slate-200 group-hover:text-indigo-200">history</span>
    </button>
  );

  return (
    <div className="space-y-10 animate-fadeIn pb-10 max-w-5xl mx-auto">
      <div className="px-2">
        <h2 className="text-3xl font-black text-slate-800 tracking-tight">Obreiros em Atividade</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] mt-2">Relatório consolidado de participações</p>
      </div>

      <div className="grid gap-12">
        {stats.map((worker) => (
          <div key={worker.name} className="bg-white rounded-[3.5rem] overflow-hidden shadow-2xl shadow-slate-200/80 border border-white">
            {/* Navy Header - DESIGN DA IMAGEM */}
            <div className="bg-[#1a1c3d] px-10 py-10 flex justify-between items-center">
