import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) setDraft({ ...data.draft, date: getTodayDate(), roles: data.draft.roles || { ...emptyRoles } });
        }
      } catch (e) {
        console.error("Erro no DB", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) saveData({ history, customSongs, draft });
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
    setActiveTab('history');
  };

  const NavItem = ({ id, icon, label }: { id: typeof activeTab, icon: string, label: string }) => (
    <button 
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-4 px-6 py-4 transition-all duration-300 ${activeTab === id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/60 hover:text-white hover:bg-white/5'}`}
    >
      <span className="material-icons">{icon}</span>
      <span className="text-xs uppercase tracking-widest">{label}</span>
    </button>
  );

  const MobileNavItem = ({ id, icon, label }: { id: typeof activeTab, icon: string, label: string }) => (
    <button 
      onClick={() => setActiveTab(id)} 
      className={`flex flex-col items-center gap-1 min-w-[75px] shrink-0 transition-all ${activeTab === id ? 'text-amber-400 scale-110' : 'text-white/40'}`}
    >
      <span className="material-icons text-xl">{icon}</span>
      <span className="text-[8px] font-black uppercase tracking-tighter whitespace-nowrap">{label}</span>
    </button>
  );

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex items-center justify-center text-white font-black tracking-widest animate-pulse">CARREGANDO...</div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      {/* Sidebar - Desktop */}
      <aside className="hidden md:flex w-72 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-8 border-b border-white/5">
          <h1 className="text-white font-black text-xl leading-tight">ICM SANTO<br/>ANTÔNIO II</h1>
          <div className="mt-2 w-12 h-1.5 bg-amber-400 rounded-full"></div>
        </div>
        <nav className="flex-1 py-6 overflow-y-auto custom-scrollbar">
          <NavItem id="new" icon="add_circle" label="Novo Culto" />
          <NavItem id="history" icon="history" label="Histórico" />
          <NavItem id="workers" icon="emoji_events" label="Ranking Obreiros" />
          <NavItem id="suggestions" icon="assignment_ind" label="Escala / Dias" />
          <NavItem id="praise-ranking" icon="trending_up" label="Ranking Hinos" />
          <NavItem id="unplayed" icon="assignment_late" label="Restantes" />
          <NavItem id="settings" icon="settings" label="Backup e Config" />
        </nav>
        <div className="p-6 border-t border-white/5 text-[10px] text-white/30 font-black uppercase tracking-[0.2em]">
          Menu Lateral Ativo
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 min-w-0 mb-24 md:mb-0">
        {isOffline && (
          <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-1.5 text-center sticky top-0 z-[200]">Modo Offline</div>
        )}

        <div className="p-4 md:p-10 animate-fadeIn">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={(h, c) => { setHistory(h); setCustomSongs(c); }} />}
        </div>
      </main>

      {/* Mobile Nav - Refatorado para scroll horizontal com TODOS os itens */}
      <nav className="md:hidden fixed bottom-4 left-1/2 -translate-x-1/2 w-[92%] bg-[#1a1c3d] text-white flex items-center justify-start gap-2 p-4 z-[200] shadow-2xl rounded-[2.5rem] border border-white/5 overflow-x-auto no-scrollbar scroll-smooth">
        <MobileNavItem id="new" icon="add_circle" label="Novo" />
        <MobileNavItem id="history" icon="history" label="Histórico" />
        <MobileNavItem id="workers" icon="emoji_events" label="Obreiros" />
        <MobileNavItem id="suggestions" icon="assignment_ind" label="Escala" />
        <MobileNavItem id="praise-ranking" icon="trending_up" label="Ranking" />
        <MobileNavItem id="unplayed" icon="assignment_late" label="Restantes" />
        <MobileNavItem id="settings" icon="settings" label="Backup" />
      </nav>

      <style dangerouslySetInnerHTML={{ __html: `
        .no-scrollbar::-webkit-scrollbar { display: none; }
        .no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
      `}} />
    </div>
  );
};

