      <span className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4 group-hover:text-indigo-600 transition-colors">{label}</span>
      <span className="text-6xl font-black text-[#1a1c3d] leading-none mb-4">{count}</span>
      <span className="material-icons text-slate-200 group-hover:text-indigo-100 transition-colors">history</span>
    </button>
  );

  return (
    <div className="space-y-12 animate-fadeIn pb-10 max-w-5xl mx-auto">
      <div className="px-2">
        <h2 className="text-4xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-3">Ranking consolidado de atos</p>
      </div>

      <div className="grid gap-16">
        {stats.map((worker) => (
          <div key={worker.name} className="bg-white rounded-[4rem] overflow-hidden shadow-2xl shadow-slate-200/50 border border-white">
            {/* NAVY HEADER DESIGN FOTO 2 */}
            <div className="bg-[#1a1c3d] px-12 py-10 flex justify-between items-center">
