              <div className="bg-[#ffcc00] text-[#1a1c3d] px-8 py-3.5 rounded-full font-black text-sm shadow-xl flex items-center gap-2">
                <span className="material-icons text-sm">stars</span>
                {worker.total} ATOS
              </div>
            </div>

            {/* BODY DESIGN FOTO 2 */}
            <div className="p-8 flex flex-col sm:flex-row gap-6 bg-slate-50/20">
              <StatBox label="Portão" count={worker.gate.length} onClick={() => setModalData({ worker: worker.name, role: 'Portão', dates: worker.gate })} />
              <StatBox label="Louvor" count={worker.praise.length} onClick={() => setModalData({ worker: worker.name, role: 'Louvor', dates: worker.praise })} />
              <StatBox label="Palavra" count={worker.word.length} onClick={() => setModalData({ worker: worker.name, role: 'Palavra', dates: worker.word })} />
            </div>
