          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 bg-slate-50/50 p-8 rounded-[2.5rem] border border-slate-100">
            <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🚪 Portão</label>
              <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            {!dateInfo.isWednesday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎵 Louvor</label>
                <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && !dateInfo.isMonday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎤 Palavra</label>
                <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && draft.roles.word !== 'TRANSMISSÃO' && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">📖 Texto Bíblico</label>
                <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro/Versículo" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none" />
              </div>
            )}
          </div>
        </div>

        <div className="space-y-4 relative">
          <label className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Buscar Louvor (Prioridade Principal)</label>
          <div className="flex gap-4">
            <input 
              type="text" 
              value={inputValue} 
              onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
              onFocus={() => setShowSuggestions(true)} 
              className="flex-1 px-8 py-5 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-4 focus:ring-indigo-50 transition-all" 
              placeholder="Nome ou número do hino..." 
            />
            <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white px-8 rounded-2xl active:scale-95 transition-transform"><span className="material-icons">add</span></button>
          </div>
          {showSuggestions && suggestions.length > 0 && (
            <div className="absolute z-[250] w-full bg-white shadow-2xl rounded-[2rem] overflow-hidden border border-slate-200 max-h-80 overflow-y-auto mt-2 animate-fadeIn">
              {suggestions.map(s => (
                <div 
                  key={s} 
                  onMouseDown={() => checkAndAddSong(s)} 
                  className="p-5 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-sm text-slate-700 flex justify-between items-center group"
                >
                  <span className={s.startsWith('(CIAS)') ? 'text-slate-400 font-medium' : 'text-slate-800'}>{s}</span>
                  <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-300 transition-opacity">add_circle</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="flex justify-between items-center px-2">
            <h4 className="font-black text-slate-800 uppercase text-xs tracking-widest">Lista Selecionada</h4>
            {draft.songs.length > 0 && <button onClick={shareViaWhatsApp} className="text-emerald-600 font-black text-[10px] uppercase flex items-center gap-2 bg-emerald-50 px-4 py-2 rounded-full hover:bg-emerald-100 transition-colors"><span className="material-icons text-sm">share</span> Enviar WhatsApp</button>}
          </div>
          <div className="space-y-3">
            {draft.songs.length === 0 ? (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-[2rem]">
                <p className="text-slate-300 text-xs font-black uppercase tracking-widest">Nenhum hino adicionado</p>
              </div>
            ) : (
              draft.songs.map((s, i) => (
                <div key={i} className="flex items-center justify-between p-5 bg-slate-50 rounded-2xl border border-slate-100 group hover:bg-white hover:shadow-md transition-all">
                  <span className="font-bold text-slate-700 text-sm"><span className="text-indigo-300 mr-2 font-black">#{(i+1).toString().padStart(2,'0')}</span> {s}</span>
                  <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-300 opacity-0 group-hover:opacity-100 transition-opacity hover:text-rose-500"><span className="material-icons">close</span></button>
                </div>
              ))
            )}
          </div>
        </div>

        <button onClick={() => onSave(draft)} disabled={draft.songs.length === 0} className={`w-full py-6 rounded-3xl font-black text-lg tracking-widest transition-all active:scale-95 ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white shadow-xl shadow-indigo-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
          {editingId ? 'ATUALIZAR RELATÓRIO' : 'SALVAR RELATÓRIO'}
        </button>
      </div>

      {/* MODAL DE CONFIRMAÇÃO DE RECORRÊNCIA - FIXING THE ISSUE */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-md flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-md shadow-2xl animate-scaleUp text-center">
            <div className="w-24 h-24 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-amber-500 text-5xl">warning</span>
            </div>
            <h3 className="text-2xl font-black text-slate-800 mb-4 tracking-tight uppercase">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed">
              O hino <span className="text-[#1a1c3d] font-black">"{pendingSong.name}"</span> foi cantado há apenas <span className="text-amber-600 font-black">{pendingSong.diff} dias</span> (em {new Date(pendingSong.lastDate + 'T12:00:00').toLocaleDateString('pt-BR')}).
              <br/><br/>
              Deseja adicionar mesmo assim?
            </p>
            <div className="flex flex-col gap-4">
              <button 
                onClick={() => executeAdd(pendingSong.name)} 
                className="w-full py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-900/20 active:scale-95 hover:bg-indigo-700 transition-colors"
              >
                ADICIONAR MESMO ASSIM
              </button>
              <button 
                onClick={() => setPendingSong(null)} 
                className="w-full py-4 text-slate-400 font-black uppercase text-xs tracking-widest hover:text-slate-600 transition-colors"
              >
                Escolher outro hino
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const moveSong = (index: number, direction: 'up' | 'down') => {
    const newSongs = [...draft.songs];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newSongs.length) return;
    [newSongs[index], newSongs[targetIndex]] = [newSongs[targetIndex], newSongs[index]];
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const shareViaWhatsApp = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let message = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${draft.description}\n\n`;
    message += `*Escala do Culto:*\n`;
    message += `🚪 Portão: ${draft.roles.gate || '-'}\n`;
    if (!dateInfo.isWednesday) {
      message += `🎵 Louvor: ${draft.roles.praise || '-'}\n`;
      if (!dateInfo.isMonday) message += `🎤 Palavra: ${draft.roles.word || '-'}\n`;
      if (draft.roles.word !== 'TRANSMISSÃO') message += `📖 Texto Bíblico: ${draft.roles.scripture || '-'}\n`;
    }
    message += `\n*Louvores:* \n`;
    draft.songs.forEach((song, i) => { message += `${i + 1}. ${song}\n`; });
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className={`bg-white rounded-[3rem] shadow-2xl p-8 md:p-12 animate-fadeIn border ${editingId ? 'border-amber-400 border-2' : 'border-slate-100'}`}>
      <div className="flex flex-col gap-10">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 bg-slate-50 p-8 rounded-[2.5rem] border border-slate-100">
          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Data do Culto</label>
            <input type="date" value={draft.date} onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} className="w-full bg-white border border-slate-200 rounded-2xl px-5 py-4 font-bold text-slate-700 shadow-sm outline-none" />
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest block mb-3">Tipo de Culto</label>
            {dateInfo.isSunday ? (
              <div className="flex bg-white border border-slate-200 p-1.5 rounded-2xl shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-xl ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-xl ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white' : 'text-slate-400'}`}>DOM</button>
              </div>
            ) : (
              <div className="w-full bg-slate-200/50 border border-slate-200 rounded-2xl px-5 py-4 font-black text-slate-400 text-sm uppercase">{dateInfo.fullName}</div>
            )}
          </div>
        </div>

        <div className="space-y-4">
          <h3 className="font-black text-slate-800 text-sm tracking-widest uppercase flex items-center gap-2">
            <span className="material-icons text-indigo-500 text-sm">assignment_ind</span>
            Escala do Obreiros
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 bg-slate-50/50 p-8 rounded-[2.5rem] border border-slate-100">
            <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🚪 Portão</label>
              <select value={draft.roles.gate} onChange={e => updateRole('gate', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </div>
            {!dateInfo.isWednesday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎵 Louvor</label>
                <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && !dateInfo.isMonday && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">🎤 Palavra</label>
                <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none">
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            {!dateInfo.isWednesday && draft.roles.word !== 'TRANSMISSÃO' && (
              <div className="flex flex-col gap-2">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest">📖 Texto Bíblico</label>
                <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro/Versículo" className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm outline-none" />
              </div>
            )}
          </div>
        </div>

        <div className="space-y-4 relative">
          <div className="flex gap-4">
            <input 
              type="text" 
              value={inputValue} 
              onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
              onFocus={() => setShowSuggestions(true)} 
              className="flex-1 px-8 py-5 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-4 focus:ring-indigo-50 transition-all" 
              placeholder="Pesquisar louvor..." 
            />
            <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white px-8 rounded-2xl active:scale-95 transition-transform"><span className="material-icons">add</span></button>
          </div>
          {showSuggestions && suggestions.length > 0 && (
            <div className="absolute z-[250] w-full bg-white shadow-2xl rounded-[2rem] overflow-hidden border border-slate-200 max-h-80 overflow-y-auto mt-2 animate-fadeIn">
              {suggestions.map(s => (
                <div 
                  key={s} 
                  onMouseDown={() => checkAndAddSong(s)} 
                  className="p-5 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-sm text-slate-700 flex justify-between items-center group"
                >
                  <span className={s.startsWith('(CIAS)') ? 'text-slate-400 font-medium' : 'text-slate-800'}>{s}</span>
                  <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-300 transition-opacity">add_circle</span>
                </div>
              ))}
            </div>
          )}
        </div>

        <div className="space-y-6">
          <div className="flex justify-between items-center px-2">
            <h4 className="font-black text-slate-800 uppercase text-xs tracking-widest">Lista Selecionada</h4>
            {draft.songs.length > 0 && <button onClick={shareViaWhatsApp} className="text-emerald-600 font-black text-[10px] uppercase flex items-center gap-2 bg-emerald-50 px-4 py-2 rounded-full hover:bg-emerald-100 transition-colors"><span className="material-icons text-sm">share</span> Enviar WhatsApp</button>}
          </div>
          <div className="space-y-4">
            {draft.songs.length === 0 ? (
              <div className="py-10 text-center border-2 border-dashed border-slate-100 rounded-[2rem]">
                <p className="text-slate-300 text-xs font-black uppercase tracking-widest">Nenhum hino adicionado</p>
              </div>
            ) : (
              draft.songs.map((s, i) => {
                const stats = songStats[s];
                return (
                  <div key={i} className="flex flex-col p-6 bg-slate-50 rounded-[2rem] border border-slate-100 group hover:bg-white hover:shadow-lg transition-all">
                    <div className="flex items-center justify-between mb-3">
                      <div className="flex items-center gap-3">
                        <span className="bg-indigo-600 text-white w-7 h-7 flex items-center justify-center rounded-full text-[10px] font-black shrink-0">{(i+1)}</span>
