                      </div>
                      <div className="flex gap-1">
                        <button onClick={() => moveSong(i, 'up')} disabled={i === 0} className="w-8 h-8 rounded-full bg-white border border-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 disabled:opacity-30"><span className="material-icons text-sm">arrow_upward</span></button>
                        <button onClick={() => moveSong(i, 'down')} disabled={i === draft.songs.length - 1} className="w-8 h-8 rounded-full bg-white border border-slate-100 flex items-center justify-center text-slate-400 hover:text-indigo-500 disabled:opacity-30"><span className="material-icons text-sm">arrow_downward</span></button>
                        <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="ml-2 w-8 h-8 rounded-full bg-white border border-slate-100 flex items-center justify-center text-rose-300 hover:text-rose-500"><span className="material-icons text-sm">close</span></button>
                      </div>
                    </div>

                    <div className="flex gap-4 pl-10">
                      <button onClick={() => setShowHistoryModal(s)} className="flex items-center gap-1.5 text-[10px] font-black text-indigo-400 bg-white px-3 py-1 rounded-full border border-slate-100 shadow-sm active:scale-95">
                        <span className="material-icons text-[14px]">calendar_month</span>
                        DATAS
                      </button>
                      <div className="flex items-center gap-1.5 text-[10px] font-black text-amber-500 bg-white px-3 py-1 rounded-full border border-slate-100 shadow-sm">
                        <span className="material-icons text-[14px]">equalizer</span>
                        {stats?.count || 0} VEZES
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        <button onClick={() => onSave(draft)} disabled={draft.songs.length === 0} className={`w-full py-6 rounded-3xl font-black text-lg tracking-widest transition-all active:scale-95 ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white shadow-xl shadow-indigo-200' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
          {editingId ? 'ATUALIZAR RELATÓRIO' : 'SALVAR RELATÓRIO'}
        </button>
      </div>

      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-md flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-md shadow-2xl animate-scaleUp text-center">
            <div className="w-24 h-24 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-amber-500 text-5xl">warning</span>
            </div>
            <h3 className="text-2xl font-black text-slate-800 mb-4 tracking-tight uppercase">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed">
              O hino <span className="text-[#1a1c3d] font-black">"{pendingSong.name}"</span> foi cantado há apenas <span className="text-amber-600 font-black">{pendingSong.diff} dias</span> (em {new Date(pendingSong.lastDate + 'T12:00:00').toLocaleDateString('pt-BR')}).
              <br/><br/>
              Deseja adicionar mesmo assim?
            </p>
            <div className="flex flex-col gap-4">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-xl shadow-indigo-900/20 active:scale-95 hover:bg-indigo-700">ADICIONAR MESMO ASSIM</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-xs tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {showHistoryModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[500] p-6 backdrop-blur-sm" onClick={() => setShowHistoryModal(null)}>
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-xl font-black text-slate-800 uppercase leading-tight">{showHistoryModal}</h3>
              <button onClick={() => setShowHistoryModal(null)} className="text-slate-300"><span className="material-icons">close</span></button>
            </div>
            <div className="max-h-60 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              {songStats[showHistoryModal]?.history.map((date, idx) => (
                <div key={idx} className="p-4 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100">
                  <span className="font-bold text-slate-700">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[10px] font-black text-indigo-400">CULTO</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

