import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const filteredHistory = useMemo(() => {
    const sorted = [...history].sort((a, b) => b.date.localeCompare(a.date));
    if (!searchTerm.trim()) return sorted;
    const search = searchTerm.toLowerCase();
    return sorted.filter(r => 
      r.date.includes(search) || 
      r.roles?.word.toLowerCase().includes(search) || 
      r.songs.some(s => s.toLowerCase().includes(search))
    );
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');
    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `🚪 Portão: ${record.roles.gate || '-'}\n`;
    if (day !== 3) { // Exceto quarta
      msg += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `🎤 Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
    }
    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const RoleBadge = ({ icon, label, value }: { icon: string, label: string, value?: string }) => {
    if (!value) return null;
    return (
      <div className="flex items-center gap-2 bg-white border border-slate-100 px-4 py-2 rounded-xl shadow-sm">
        <span className="text-lg">{icon}</span>
        <div className="flex flex-col">
          <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest">{label}</span>
          <span className="text-[11px] font-black text-slate-700">{value}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-10 animate-fadeIn">
      {/* CABEÇALHO DESIGN DA FOTO 1 */}
      <div className="bg-[#1a1c3d] -mx-4 md:-mx-12 px-6 md:px-12 py-12 rounded-b-[4rem] shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-10 opacity-5">
           <span className="material-icons text-[200px] text-white">history</span>
        </div>
        <div className="max-w-4xl mx-auto flex items-center gap-4 relative z-10">
          <div className="relative flex-1 bg-white rounded-full flex items-center px-8 py-5 shadow-2xl border-none">
            <span className="material-icons text-slate-300 mr-4 text-2xl">search</span>
            <input 
              type="text" 
              value={searchTerm} 
              onChange={e => setSearchTerm(e.target.value)} 
              placeholder="Pesquisar..." 
              className="w-full bg-transparent outline-none text-slate-600 font-bold text-lg placeholder:text-slate-300"
            />
          </div>
          <button onClick={() => setShowShareModal(true)} className="bg-white/10 hover:bg-white/20 w-16 h-16 rounded-full flex items-center justify-center transition-all group">
            <span className="material-icons text-white text-3xl group-hover:scale-110">calendar_month</span>
          </button>
          <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] hover:bg-[#ffaa00] w-18 h-18 rounded-full flex items-center justify-center shadow-2xl shadow-orange-950/40 transition-all transform active:scale-90">
            <span className="material-icons text-white text-4xl">auto_stories</span>
          </button>
        </div>
      </div>

      <div className="grid gap-8 max-w-4xl mx-auto pt-4">
        {filteredHistory.length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-200">
            <span className="material-icons text-6xl text-slate-200 mb-4">search_off</span>
            <p className="text-slate-400 font-black uppercase tracking-widest text-xs">Nenhum registro encontrado</p>
          </div>
        ) : (
          filteredHistory.map(r => (
            <div key={r.id} className="bg-white rounded-[3rem] shadow-xl border border-slate-100 overflow-hidden group hover:shadow-2xl transition-all">
              <div className="px-10 py-8 flex justify-between items-center bg-slate-50/50 border-b border-slate-100">
                <div className="flex flex-col">
                  <span className="text-slate-900 font-black text-xl">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em] mt-1">{r.description}</span>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => onEdit(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-amber-500 shadow-sm"><span className="material-icons text-lg">edit</span></button>
                  <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-emerald-500 shadow-sm"><span className="material-icons text-lg">share</span></button>
                  <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-rose-500 shadow-sm"><span className="material-icons text-lg">delete</span></button>
                </div>
              </div>

              <div className="p-8 bg-slate-50/20 border-b border-slate-50 flex flex-wrap gap-3">
                <RoleBadge icon="🚪" label="Portão" value={r.roles.gate} />
                <RoleBadge icon="🎵" label="Louvor" value={r.roles.praise} />
                <RoleBadge icon="🎤" label="Palavra" value={r.roles.word} />
                <RoleBadge icon="📖" label="Texto" value={r.roles.scripture} />
              </div>

              <div className="p-8 bg-white">
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                  {r.songs.map((s, i) => (
                    <div key={i} className="text-[12px] font-bold text-slate-600 flex items-center gap-3 bg-slate-50 p-4 rounded-2xl border border-transparent group-hover:border-slate-100 transition-all">
                      <span className="text-indigo-400 font-black text-[10px] shrink-0">#{(i+1)}</span>
                      <span className="truncate">{s}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          ))
        )}
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm p-12 animate-scaleUp text-center" onClick={e => e.stopPropagation()}>
            <h3 className="text-2xl font-black text-slate-800 mb-10 tracking-tight">EXPORTAR DADOS</h3>
            <div className="space-y-6">
              <button onClick={() => window.open(`https://wa.me/?text=Relatorios`, '_blank')} className="w-full py-6 bg-emerald-600 text-white font-black rounded-3xl flex items-center justify-center gap-4 shadow-2xl shadow-emerald-900/20 active:scale-95 transition-all">
                <span className="material-icons">share</span> RELATÓRIO DO MÊS
              </button>
              <button onClick={() => setShowShareModal(false)} className="w-full py-5 text-slate-400 font-black uppercase text-xs tracking-widest">Fechar</button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-sm" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-xs animate-scaleUp text-center" onClick={e => e.stopPropagation()}>
            <div className="w-24 h-24 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-rose-500 text-5xl">delete_forever</span>
            </div>
            <h3 className="text-2xl font-black text-slate-800 mb-10">Confirmar exclusão?</h3>
            <div className="flex flex-col gap-4">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-6 bg-rose-600 text-white font-black rounded-3xl shadow-xl shadow-rose-900/20 active:scale-95">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-5 text-slate-400 font-black uppercase text-xs tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

