import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, dates: string[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: string[], praise: string[], word: string[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));
    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });
    history.forEach(r => {
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(r.date);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(r.date);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(r.date);
    });
    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.localeCompare(a));
      data[name].praise.sort((a, b) => b.localeCompare(a));
      data[name].word.sort((a, b) => b.localeCompare(a));
    });
    return Object.entries(data).map(([name, val]) => ({ name, ...val })).sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick }: { label: string, count: number, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.15em] mb-2 group-hover:text-indigo-600 transition-colors">{label}</span>
      <span className="text-3xl font-black text-[#1a1c3d] leading-none mb-2">{count}</span>
      <span className="material-icons text-slate-200 text-sm group-hover:text-indigo-100 transition-colors">history</span>
    </button>
  );

  return (
    <div className="space-y-8 animate-fadeIn pb-10 max-w-4xl mx-auto">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Total acumulado de atos realizados</p>
      </div>

      <div className="grid gap-8">
        {stats.map((worker) => (
          <div key={worker.name} className="bg-white rounded-[2rem] overflow-hidden shadow-lg border border-slate-100">
            <div className="bg-[#1a1c3d] px-8 py-6 flex justify-between items-center">
              <h3 className="text-white font-black text-xl tracking-tight uppercase">{worker.name}</h3>
              <div className="bg-[#ffcc00] text-[#1a1c3d] px-4 py-1.5 rounded-full font-black text-[10px] shadow-sm flex items-center gap-1.5">
                <span className="material-icons text-[12px]">stars</span>
                {worker.total} ATOS
              </div>
            </div>

            <div className="p-4 flex gap-3 bg-slate-50/20">
              <StatBox label="Portão" count={worker.gate.length} onClick={() => setModalData({ worker: worker.name, role: 'Portão', dates: worker.gate })} />
              <StatBox label="Louvor" count={worker.praise.length} onClick={() => setModalData({ worker: worker.name, role: 'Louvor', dates: worker.praise })} />
              <StatBox label="Palavra" count={worker.word.length} onClick={() => setModalData({ worker: worker.name, role: 'Palavra', dates: worker.word })} />
            </div>
          </div>
        ))}
      </div>

      {modalData && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[400] p-6 backdrop-blur-sm" onClick={() => setModalData(null)}>
          <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-sm p-10 animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex items-center justify-between mb-8">
              <div>
                <h3 className="text-2xl font-black text-slate-800 leading-tight uppercase">{modalData.worker}</h3>
                <span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">{modalData.role}</span>
              </div>
              <button onClick={() => setModalData(null)} className="text-slate-300">
                <span className="material-icons">close</span>
              </button>
            </div>
            <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar space-y-3">
              {modalData.dates.map((d, i) => (
                <div key={i} className="flex justify-between items-center p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  <span className="font-bold text-slate-700">{new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-indigo-400 font-black text-xs">#{modalData.dates.length - i}</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

