                    <div className="p-10 bg-white">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {r.songs.map((s, i) => (
                          <div key={i} className="text-xs font-bold text-slate-600 flex items-center gap-4 bg-slate-50/50 p-4 rounded-2xl border border-transparent group-hover:border-slate-100 transition-all">
                            <span className="bg-white w-6 h-6 flex items-center justify-center rounded-lg text-[9px] font-black text-indigo-400 border border-slate-100 shadow-sm">{i+1}</span>
                            <span className="truncate">{s}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
