      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[400] p-6 backdrop-blur-xl" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm p-14 animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-10 tracking-tighter uppercase">Enviar Mensal</h3>
            <div className="space-y-4 max-h-80 overflow-y-auto pr-2 custom-scrollbar">
              {Object.keys(groupedHistory).length === 0 ? <p className="text-slate-400 font-bold py-10">Sem dados mensais</p> : 
                Object.keys(groupedHistory).map(month => (
                  <button key={month} onClick={() => { shareMonth(month); setShowShareModal(false); }} className="w-full py-6 bg-slate-50 text-[#1a1c3d] font-black rounded-[2rem] border border-slate-100 hover:bg-emerald-50 hover:border-emerald-100 transition-all active:scale-95 flex items-center justify-center gap-4">
                    <span className="material-icons text-emerald-500">share</span> {month}
                  </button>
                ))
              }
            </div>
            <button onClick={() => setShowShareModal(false)} className="mt-8 text-slate-300 font-black uppercase text-[10px] tracking-widest">Fechar</button>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-20 h-20 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-10">
              <span className="material-icons text-rose-500 text-4xl">delete_forever</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-10 uppercase tracking-tighter">Excluir Relatório?</h3>
            <div className="flex flex-col gap-4">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-6 bg-rose-600 text-white font-black rounded-3xl shadow-xl shadow-rose-900/20 active:scale-95">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

const CACHE_NAME = 'icm-gestao-v6';
const PRECACHE_ASSETS = [
  '/',
  '/index.html',
  '/index.tsx',
  '/manifest.json',
  '/types.ts',
  '/constants.ts',
  '/praiseList.ts',
  '/db.ts',
  '/App.tsx',
  'https://cdn-icons-png.flaticon.com/512/1672/1672225.png',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/icon?family=Material+Icons',
  'https://fonts.gstatic.com/s/materialicons/v142/flUhRq6tzZclQEJ-Vdg-IuiaDsNcIhQ8tQ.woff2',
  'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800;900&display=swap'
];

const ESM_DEPS = [
  'https://esm.sh/react@^19.2.3',
  'https://esm.sh/react-dom@^19.2.3',
  'https://esm.sh/react@^19.2.3/',
  'https://esm.sh/react-dom@^19.2.3/'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return Promise.allSettled(
        [...PRECACHE_ASSETS, ...ESM_DEPS].map(url => 
          cache.add(url).catch(err => console.warn(`Falha no cache: ${url}`))
        )
      );
    })
  );
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((keys) => {
      return Promise.all(
        keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
      );
    })
  );
  self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  if (url.host === 'esm.sh' || url.host.includes('fonts.') || url.host.includes('cdn.tailwindcss.com') || url.host.includes('flaticon.com')) {
    event.respondWith(
      caches.match(request).then((cachedResponse) => {
        if (cachedResponse) return cachedResponse;
        return fetch(request).then((networkResponse) => {
          if (networkResponse.status === 200) {
            const cacheCopy = networkResponse.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, cacheCopy));
          }
          return networkResponse;
        }).catch(() => new Response("Offline", { status: 503 }));
      })
    );
    return;
  }

  event.respondWith(
    fetch(request)
      .then((networkResponse) => {
        if (request.method === 'GET' && networkResponse.status === 200) {
          const cacheCopy = networkResponse.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, cacheCopy));
        }
        return networkResponse;
      })
      .catch(() => {
        return caches.match(request).then((cachedResponse) => {
          if (cachedResponse) return cachedResponse;
          if (request.mode === 'navigate') return caches.match('/index.html') || caches.match('/');
          return new Response("Offline", { status: 503 });
        });
      })
  );
});

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

// Fix: Move Label and FormInput outside of the ServiceForm component 
// to avoid re-definition on every render and fix "children" prop missing errors in some TS environments.
const Label = ({ children }: { children: React.ReactNode }) => (
  <label className="text-[12px] font-black text-slate-400 uppercase tracking-widest block mb-3 text-center md:text-left">{children}</label>
);

const FormInput = ({ children }: { children: React.ReactNode }) => (
  <div className="bg-slate-50 border border-slate-100 rounded-[2rem] px-8 py-5 shadow-sm transition-all focus-within:shadow-xl focus-within:bg-white focus-within:border-indigo-100">
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  // Drag and Drop Logic
  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-2xl mx-auto space-y-8 animate-fadeIn">
      {/* CARD PRINCIPAL */}
      <div className="bg-white rounded-[4rem] shadow-2xl p-10 md:p-14 border border-white">

        <div className="space-y-10">
          {/* DATA DO CULTO */}
          <div className="flex flex-col items-center">
            <Label>Data do Culto</Label>
            <FormInput>
              <input 
                type="date" 
                value={draft.date} 
                onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                className="w-full bg-transparent font-black text-2xl text-[#1a1c3d] text-center outline-none" 
              />
            </FormInput>
            <div className="mt-4 bg-indigo-50 px-6 py-2 rounded-full">
              <span className="text-indigo-600 font-black text-xs uppercase tracking-widest">DIA: {dateInfo.name}</span>
            </div>
          </div>

          {/* PORTÃO */}
          <div className="flex flex-col">
            <Label>Portão</Label>
            <FormInput>
              <select 
                value={draft.roles.gate} 
                onChange={e => updateRole('gate', e.target.value)} 
                className="w-full bg-transparent font-black text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
              >
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </FormInput>
          </div>

          {/* MENSAGEM ESPECIAL: QUARTA FEIRA */}
          {dateInfo.isWednesday && (
             <div className="bg-indigo-50/80 p-6 rounded-[2rem] border border-indigo-100 flex items-center justify-center gap-4 text-indigo-700 animate-scaleUp">
               <span className="text-2xl">🌸</span>
               <span className="font-black text-xs uppercase tracking-widest text-center">Culto dirigido pelo Grupo de Senhoras</span>
             </div>
          )}

          {/* MENSAGEM ESPECIAL: TRANSMISSÃO */}
          {draft.roles.word === 'TRANSMISSÃO' && (
             <div className="bg-amber-50 p-6 rounded-[2rem] border border-amber-100 flex items-center justify-center gap-4 text-amber-700 animate-scaleUp">
               <span className="text-2xl">📡</span>
               <span className="font-black text-xs uppercase tracking-widest text-center">Culto transmitido via satélite</span>
             </div>
          )}

          {/* DEMAIS CAMPOS SE NÃO FOR QUARTA */}
          {!dateInfo.isWednesday && (
            <div className="grid gap-8">
              <div className="flex flex-col">
                <Label>Louvor (Escala)</Label>
                <FormInput>
                  <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {!dateInfo.isMonday && (
                <div className="flex flex-col">
                  <Label>Palavra</Label>
                  <FormInput>
                    <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>
              )}

              {draft.roles.word !== 'TRANSMISSÃO' && (
                <div className="flex flex-col">
                  <Label>Texto Bíblico</Label>
                  <FormInput>
                    <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-xl text-[#1a1c3d] text-center outline-none placeholder:text-slate-200" />
                  </FormInput>
                </div>
              )}
            </div>
          )}

          {/* BUSCA DE LOUVORES */}
          <div className="space-y-4 relative">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-4">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-8 py-5 bg-slate-50 border border-slate-100 rounded-[2rem] font-black text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Pesquisar..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-18 h-18 rounded-[2rem] flex items-center justify-center active:scale-90 transition-transform shadow-xl"><span className="material-icons text-3xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-full bg-white shadow-2xl rounded-[2.5rem] overflow-hidden border border-slate-100 max-h-80 overflow-y-auto mt-4 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-6 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-black text-sm text-slate-700 flex justify-between items-center group">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-400 transition-opacity">add_circle</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* LISTA DE LOUVORES COM DRAG & DROP */}
          <div className="space-y-5">
            <div className="flex justify-between items-center px-4">
              <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Ordem dos Louvores (Arraste para mover)</span>
              <span className="bg-indigo-600 text-white text-[10px] font-black px-3 py-1 rounded-full">{draft.songs.length} Hinos</span>
            </div>
            <div className="space-y-3">
              {draft.songs.length === 0 ? (
                <div className="py-12 text-center border-2 border-dashed border-slate-100 rounded-[2.5rem] bg-slate-50/30">
                  <p className="text-slate-300 text-xs font-black uppercase tracking-widest">Nenhum louvor selecionado</p>
                </div>
              ) : (
                draft.songs.map((s, i) => {
                  const stats = songStats[s];
                  return (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex flex-col p-6 bg-slate-50/50 rounded-[2rem] border border-slate-100 cursor-move transition-all active:scale-95 group hover:bg-white hover:shadow-xl ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4">
                          <span className="material-icons text-slate-300 text-lg">drag_indicator</span>
                          <span className="font-black text-slate-700 text-sm">#{i+1} {s}</span>
                        </div>
                        <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500"><span className="material-icons">close</span></button>
                      </div>
                      <div className="flex gap-4 mt-3 pl-10">
                        <button onClick={() => setShowHistoryModal(s)} className="flex items-center gap-1.5 text-[9px] font-black text-indigo-400 bg-white px-3 py-1.5 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-xs">calendar_month</span> DATAS
                        </button>
                        <div className="flex items-center gap-1.5 text-[9px] font-black text-amber-500 bg-white px-3 py-1.5 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-xs">analytics</span> {stats?.count || 0} VEZES
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          <button 
            onClick={() => onSave(draft)} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-8 rounded-[2.5rem] font-black text-xl tracking-widest transition-all active:scale-90 flex items-center justify-center gap-4 shadow-2xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white shadow-indigo-900/30' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons text-2xl">edit_note</span>
            {editingId ? 'ATUALIZAR DADOS' : 'CONFIRMAR'}
          </button>
        </div>
      </div>

      {/* MODAIS: RECORRÊNCIA E HISTÓRICO (MANTIDOS COM ESTILO NOVO) */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[4rem] p-14 w-full max-w-md shadow-2xl animate-scaleUp text-center border border-white">
            <div className="w-24 h-24 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-10">
              <span className="material-icons text-amber-500 text-5xl">warning_amber</span>
            </div>
            <h3 className="text-3xl font-black text-[#1a1c3d] mb-4 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-10 leading-relaxed text-sm">
              Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Deseja prosseguir?
            </p>
            <div className="flex flex-col gap-4">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-6 bg-indigo-600 text-white font-black rounded-3xl shadow-xl active:scale-95">ADICIONAR MESMO ASSIM</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-xs tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}

      {showHistoryModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[500] p-6 backdrop-blur-md" onClick={() => setShowHistoryModal(null)}>
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-sm animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-10">
              <h3 className="text-xl font-black text-[#1a1c3d] uppercase tracking-tighter pr-4">{showHistoryModal}</h3>
              <button onClick={() => setShowHistoryModal(null)} className="w-10 h-10 bg-slate-100 rounded-full flex items-center justify-center text-slate-300"><span className="material-icons">close</span></button>
            </div>
            <div className="max-h-80 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
              {songStats[showHistoryModal]?.history.map((date, idx) => (
                <div key={idx} className="p-5 bg-slate-50 rounded-2xl flex justify-between items-center border border-slate-100 hover:bg-white hover:shadow-lg transition-all">
                  <span className="font-black text-slate-700">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[10px] font-black text-indigo-400 bg-white px-3 py-1 rounded-full border border-slate-100">CANTADO</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} DE ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `🚪 Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) { // Exceto quarta
      msg += `🎵 Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `🎤 Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `📖 Texto Bíblico: ${record.roles.scripture || '-'}\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const records = groupedHistory[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const RoleBadge = ({ icon, label, value }: { icon: string, label: string, value?: string }) => {
    if (!value) return null;
    return (
      <div className="flex items-center gap-3 bg-white border border-slate-100 px-4 py-2.5 rounded-2xl shadow-sm">
        <span className="text-xl">{icon}</span>
        <div className="flex flex-col">
          <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">{label}</span>
          <span className="text-[12px] font-black text-[#1a1c3d]">{value}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-12 animate-fadeIn max-w-3xl mx-auto pb-10">
      {/* BUSCA REESTILIZADA */}
      <div className="bg-white rounded-[2.5rem] shadow-xl p-6 md:p-8 flex items-center gap-5 border border-white">
        <div className="flex-1 bg-slate-50 rounded-2xl flex items-center px-6 py-4 border border-slate-100">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar histórico..." 
            className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
          />
        </div>
        <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] text-white w-14 h-14 rounded-2xl flex items-center justify-center shadow-xl shadow-orange-900/20 active:scale-90 transition-transform">
          <span className="material-icons text-2xl">ios_share</span>
        </button>
      </div>

      <div className="space-y-16">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-24 bg-white rounded-[4rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-6xl text-slate-100 mb-4">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-xs">Nenhum registro encontrado</p>
          </div>
        ) : (
          Object.entries(groupedHistory).map(([month, records]) => (
            <div key={month} className="space-y-8 animate-fadeIn">
              <div className="flex items-center gap-6 px-4">
                <h3 className="font-black text-[#1a1c3d] text-xl tracking-tighter uppercase">{month}</h3>
                <div className="flex-1 h-[2px] bg-slate-200/50 rounded-full"></div>
                <button onClick={() => shareMonth(month)} className="text-[10px] font-black text-indigo-500 uppercase tracking-widest bg-indigo-50 px-4 py-2 rounded-full hover:bg-indigo-100 transition-colors">Enviar Mês</button>
              </div>

              <div className="grid gap-8">
                {records.map(r => (
                  <div key={r.id} className="bg-white rounded-[3rem] shadow-xl border border-white overflow-hidden group hover:shadow-2xl transition-all">
                    <div className="px-10 py-8 flex justify-between items-center bg-slate-50/40 border-b border-slate-50">
                      <div>
                        <span className="text-[#1a1c3d] font-black text-2xl">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                        <div className="mt-1 flex items-center gap-2">
                           <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                           <span className="text-[10px] font-black text-indigo-500 uppercase tracking-[0.2em]">{r.description}</span>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <button onClick={() => onEdit(r)} className="w-11 h-11 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-amber-500 shadow-sm"><span className="material-icons text-xl">edit</span></button>
                        <button onClick={() => shareIndividual(r)} className="w-11 h-11 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-emerald-500 shadow-sm"><span className="material-icons text-xl">share</span></button>
                        <button onClick={() => setItemToDelete(r.id)} className="w-11 h-11 bg-white border border-slate-100 rounded-xl flex items-center justify-center text-rose-500 shadow-sm"><span className="material-icons text-xl">delete</span></button>
                      </div>
                    </div>

                    <div className="p-8 bg-slate-50/20 border-b border-slate-50 flex flex-wrap gap-4">
                      <RoleBadge icon="🚪" label="Portão" value={r.roles.gate} />
                      <RoleBadge icon="🎵" label="Louvor" value={r.roles.praise} />
                      <RoleBadge icon="🎤" label="Palavra" value={r.roles.word} />
                      <RoleBadge icon="📖" label="Texto" value={r.roles.scripture} />
                    </div>

                    <div className="p-10 bg-white">
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                        {r.songs.map((s, i) => (
                          <div key={i} className="text-xs font-bold text-slate-600 flex items-center gap-4 bg-slate-50/50 p-4 rounded-2xl border border-transparent group-hover:border-slate-100 transition-all">
                            <span className="bg-white w-6 h-6 flex items-center justify-center rounded-lg text-[9px] font-black text-indigo-400 border border-slate-100 shadow-sm">{i+1}</span>
                            <span className="truncate">{s}</span>
                          </div>
                        ))}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          ))
        )}
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[400] p-6 backdrop-blur-xl" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[4rem] shadow-2xl w-full max-w-sm p-14 animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-10 tracking-tighter uppercase">Enviar Mensal</h3>
            <div className="space-y-4 max-h-80 overflow-y-auto pr-2 custom-scrollbar">
              {Object.keys(groupedHistory).length === 0 ? <p className="text-slate-400 font-bold py-10">Sem dados mensais</p> : 
                // Fix: Cast Object.keys to string[] to resolve 'unknown' type error in environments with incomplete Object type definitions.
                (Object.keys(groupedHistory) as string[]).map(month => (
                  <button key={month} onClick={() => { shareMonth(month); setShowShareModal(false); }} className="w-full py-6 bg-slate-50 text-[#1a1c3d] font-black rounded-[2rem] border border-slate-100 hover:bg-emerald-50 hover:border-emerald-100 transition-all active:scale-95 flex items-center justify-center gap-4">
                    <span className="material-icons text-emerald-500">share</span> {month}
                  </button>
                ))
              }
            </div>
            <button onClick={() => setShowShareModal(false)} className="mt-8 text-slate-300 font-black uppercase text-[10px] tracking-widest">Fechar</button>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[4rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-20 h-20 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-10">
              <span className="material-icons text-rose-500 text-4xl">delete_forever</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-10 uppercase tracking-tighter">Excluir Relatório?</h3>
            <div className="flex flex-col gap-4">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-6 bg-rose-600 text-white font-black rounded-3xl shadow-xl shadow-rose-900/20 active:scale-95">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

