import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children: React.ReactNode }) => (
  <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-3xl px-6 py-4 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-xl mx-auto space-y-6 animate-fadeIn">
      <div className="bg-white rounded-[3.5rem] shadow-2xl p-8 md:p-12 border border-white">

        <div className="space-y-8">
          {/* DATA DO CULTO */}
          <div className="flex flex-col items-center">
            <Label>Data do Culto</Label>
            <FormInput className="w-full">
              <input 
                type="date" 
                value={draft.date} 
                onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                className="w-full bg-transparent font-black text-xl md:text-2xl text-[#1a1c3d] text-center outline-none" 
              />
            </FormInput>
            <div className="mt-3 bg-indigo-50 px-5 py-1.5 rounded-full">
              <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest leading-none">DIA: {dateInfo.name}</span>
            </div>
          </div>

          {/* SELETOR EBD/DOM NO DOMINGO */}
          {dateInfo.isSunday && (
            <div className="flex flex-col">
              <Label>Período</Label>
              <div className="flex bg-slate-50 border border-slate-100 p-1.5 rounded-[2rem] shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-[1.5rem] transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-[1.5rem] transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
              </div>
            </div>
          )}

          {/* PORTÃO */}
          <div className="flex flex-col">
            <Label>Portão</Label>
            <FormInput>
              <select 
                value={draft.roles.gate} 
                onChange={e => updateRole('gate', e.target.value)} 
                className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
              >
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </FormInput>
          </div>

          {/* MENSAGEM ESPECIAL: QUARTA FEIRA */}
          {dateInfo.isWednesday && (
             <div className="bg-indigo-50/80 p-5 rounded-[2rem] border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
               <span className="text-xl">🌸</span>
               <span className="font-black text-[10px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
             </div>
          )}

          {/* DEMAIS CAMPOS */}
          {!dateInfo.isWednesday && (
            <div className="space-y-6">
              <div className="flex flex-col">
                <Label>Louvor (Escala)</Label>
                <FormInput>
                  <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {!dateInfo.isMonday && (
                <div className="flex flex-col">
                  <Label>Palavra</Label>
                  <FormInput>
                    <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>
              )}

              {/* MENSAGEM TRANSMISSÃO OU TEXTO BÍBLICO */}
              <div className="flex flex-col min-h-[80px] justify-end">
                {draft.roles.word === 'TRANSMISSÃO' ? (
                  <div className="bg-amber-50 p-5 rounded-[2rem] border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                    <span className="text-xl">📡</span>
                    <span className="font-black text-[10px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                  </div>
                ) : (
                  <>
                    <Label>Texto Bíblico</Label>
                    <FormInput>
                      <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none placeholder:text-slate-200" />
                    </FormInput>
                  </>
                )}
              </div>
            </div>
          )}

          {/* ADICIONAR LOUVORES */}
          <div className="space-y-4 relative">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-3">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-6 py-4 bg-slate-50 border border-slate-100 rounded-[2rem] font-bold text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Pesquisar..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-14 h-14 rounded-2xl flex items-center justify-center active:scale-90 transition-transform shadow-xl shrink-0"><span className="material-icons text-2xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-full bg-white shadow-2xl rounded-[2rem] overflow-hidden border border-slate-100 max-h-80 overflow-y-auto mt-2 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-5 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-sm text-slate-700 flex justify-between items-center group">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-400 transition-opacity">add_circle</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* LISTA DE SELECIONADOS */}
          <div className="space-y-4">
            <div className="flex justify-between items-center px-2">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Louvores Selecionados</span>
              <span className="bg-indigo-600 text-white text-[9px] font-black px-3 py-1 rounded-full">{draft.songs.length} Hinos</span>
            </div>
            <div className="space-y-2.5">
              {draft.songs.length === 0 ? (
                <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-[2rem] bg-slate-50/30">
                  <p className="text-slate-300 text-[10px] font-black uppercase tracking-widest">Vazio</p>
                </div>
              ) : (
                draft.songs.map((s, i) => {
                  const stats = songStats[s];
                  return (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex flex-col p-5 bg-slate-50/50 rounded-[1.5rem] border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-lg ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <span className="material-icons text-slate-300 text-base">drag_indicator</span>
                          <span className="font-bold text-slate-700 text-sm truncate max-w-[200px]">#{i+1} {s}</span>
                        </div>
                        <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500"><span className="material-icons text-xl">close</span></button>
                      </div>
                      <div className="flex gap-3 mt-2.5 pl-8">
                        <button onClick={() => setShowHistoryModal(s)} className="flex items-center gap-1 text-[8px] font-black text-indigo-400 bg-white px-2.5 py-1 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-[10px]">calendar_month</span> DATAS
                        </button>
                        <div className="flex items-center gap-1 text-[8px] font-black text-amber-500 bg-white px-2.5 py-1 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-[10px]">analytics</span> {stats?.count || 0} VEZES
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          <button 
            onClick={() => onSave(draft)} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-6 rounded-3xl font-black text-lg tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons">save</span>
            {editingId ? 'ATUALIZAR' : 'CONFIRMAR'}
          </button>
        </div>
      </div>

      {/* MODAL RECORRENCIA */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-8 text-amber-500">
              <span className="material-icons text-4xl">warning_amber</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-3 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-xs">
              Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL HISTORICO HINO */}
      {showHistoryModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[500] p-6 backdrop-blur-md" onClick={() => setShowHistoryModal(null)}>
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-lg font-black text-[#1a1c3d] uppercase tracking-tighter pr-4 truncate">{showHistoryModal}</h3>
              <button onClick={() => setShowHistoryModal(null)} className="w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center text-slate-300"><span className="material-icons">close</span></button>
            </div>
            <div className="max-h-60 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
              {songStats[showHistoryModal]?.history.map((date, idx) => (
                <div key={idx} className="p-4 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                  <span className="font-bold text-slate-700 text-sm">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[9px] font-black text-indigo-400 uppercase">Cantado</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    // Removendo possíveis caracteres especiais ou quebras problemáticas para WhatsApp
    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) { // Exceto quarta
      msg += `Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      else msg += `📡 Culto via Satélite\n`;
    } else {
      msg += `🌸 Culto Senhoras\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const records = groupedHistory[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-2xl mx-auto pb-10">
      {/* CABEÇALHO DE BUSCA ESTILO IMAGEM 1 */}
      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar..." 
            className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
          />
        </div>
        <button className="bg-[#1a1c3d] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl active:scale-90 transition-transform">
          <span className="material-icons">calendar_month</span>
        </button>
        <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shadow-orange-950/20 active:scale-90 transition-transform">
          <span className="material-icons">auto_stories</span>
        </button>
      </div>

      <div className="space-y-10">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-5xl text-slate-100 mb-3">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">Sem registros</p>
          </div>
        ) : (
          Object.entries(groupedHistory).map(([month, records]) => (
            <div key={month} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] whitespace-nowrap">{month}</span>
                <div className="flex-1 h-[1px] bg-slate-200/50"></div>
              </div>

              <div className="grid gap-6">
                {records.map(r => {
                  const dayCode = dayOfWeekNamesShort[new Date(r.date + 'T12:00:00').getDay()];
                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-xl border border-slate-50 p-8 flex justify-between items-start group hover:shadow-2xl transition-all">
                      <div>
                        <span className="text-indigo-600 font-black text-[11px] uppercase tracking-widest block mb-1">{dayCode}</span>
                        <h4 className="text-[#1a1c3d] font-black text-2xl tracking-tighter">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</h4>
                        <div className="mt-3 flex items-center gap-2">
                           <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                           <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{r.description}</span>
                        </div>
                      </div>

                      <div className="flex gap-2.5">
                        <button onClick={() => onEdit(r)} className="w-11 h-11 bg-amber-50 rounded-2xl flex items-center justify-center text-amber-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">edit</span>
                        </button>
                        <button onClick={() => shareIndividual(r)} className="w-11 h-11 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">share</span>
                        </button>
                        <button onClick={() => setItemToDelete(r.id)} className="w-11 h-11 bg-rose-50 rounded-2xl flex items-center justify-center text-rose-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">delete</span>
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>

      {/* MODAL RELATÓRIO MENSAL - ESTILO IMAGEM 2 */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[400] p-6 backdrop-blur-sm" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-scaleUp" onClick={e => e.stopPropagation()}>
            {/* Header Navy Blue */}
            <div className="bg-[#1a1c3d] p-10 relative">
              <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block mb-1">REGISTRO DE ESCALA</span>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter">RELATÓRIO MENSAL</h3>
              <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            {/* Body */}
            <div className="p-10 bg-white flex flex-col gap-4">
              <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-3">
                {Object.keys(groupedHistory).length === 0 ? (
                  <p className="text-slate-400 font-bold py-10 text-center">Sem dados mensais</p>
                ) : (
                  (Object.keys(groupedHistory) as string[]).map(month => (
                    <button 
                      key={month} 
                      onClick={() => { shareMonth(month); setShowShareModal(false); }} 
                      className="w-full py-6 bg-indigo-50/50 text-[#1a1c3d] font-black rounded-3xl border border-indigo-100/50 hover:bg-indigo-100 transition-all active:scale-95 text-lg tracking-tight"
                    >
                      {month}
                    </button>
                  ))
                )}
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-full py-6 bg-slate-50 text-slate-800 font-black rounded-3xl uppercase text-sm tracking-widest mt-2 active:scale-95"
              >
                FECHAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DELETAR */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-rose-500 text-3xl">delete_outline</span>
            </div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter">Excluir Relatório?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

// Add optional children to fix "missing property children" error in some environments
const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

// Add optional children to fix "missing property children" error in some environments
const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-3xl px-6 py-4 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-xl mx-auto space-y-6 animate-fadeIn">
      <div className="bg-white rounded-[3.5rem] shadow-2xl p-8 md:p-12 border border-white">

        <div className="space-y-8">
          {/* DATA DO CULTO */}
          <div className="flex flex-col items-center">
            <Label>Data do Culto</Label>
            <FormInput className="w-full">
              <input 
                type="date" 
                value={draft.date} 
                onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                className="w-full bg-transparent font-black text-xl md:text-2xl text-[#1a1c3d] text-center outline-none" 
              />
            </FormInput>
            <div className="mt-3 bg-indigo-50 px-5 py-1.5 rounded-full">
              <span className="text-indigo-600 font-black text-[10px] uppercase tracking-widest leading-none">DIA: {dateInfo.name}</span>
            </div>
          </div>

          {/* SELETOR EBD/DOM NO DOMINGO */}
          {dateInfo.isSunday && (
            <div className="flex flex-col">
              <Label>Período</Label>
              <div className="flex bg-slate-50 border border-slate-100 p-1.5 rounded-[2rem] shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-3 text-xs font-black rounded-[1.5rem] transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-3 text-xs font-black rounded-[1.5rem] transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
              </div>
            </div>
          )}

          {/* PORTÃO */}
          <div className="flex flex-col">
            <Label>Portão</Label>
            <FormInput>
              <select 
                value={draft.roles.gate} 
                onChange={e => updateRole('gate', e.target.value)} 
                className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
              >
                <option value="">Selecione...</option>
                {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
              </select>
            </FormInput>
          </div>

          {/* MENSAGEM ESPECIAL: QUARTA FEIRA */}
          {dateInfo.isWednesday && (
             <div className="bg-indigo-50/80 p-5 rounded-[2rem] border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
               <span className="text-xl">🌸</span>
               <span className="font-black text-[10px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
             </div>
          )}

          {/* DEMAIS CAMPOS */}
          {!dateInfo.isWednesday && (
            <div className="space-y-6">
              <div className="flex flex-col">
                <Label>Louvor (Escala)</Label>
                <FormInput>
                  <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {!dateInfo.isMonday && (
                <div className="flex flex-col">
                  <Label>Palavra</Label>
                  <FormInput>
                    <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>
              )}

              {/* MENSAGEM TRANSMISSÃO OU TEXTO BÍBLICO */}
              <div className="flex flex-col min-h-[80px] justify-end">
                {draft.roles.word === 'TRANSMISSÃO' ? (
                  <div className="bg-amber-50 p-5 rounded-[2rem] border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                    <span className="text-xl">📡</span>
                    <span className="font-black text-[10px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                  </div>
                ) : (
                  <>
                    <Label>Texto Bíblico</Label>
                    <FormInput>
                      <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none placeholder:text-slate-200" />
                    </FormInput>
                  </>
                )}
              </div>
            </div>
          )}

          {/* ADICIONAR LOUVORES */}
          <div className="space-y-4 relative">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-3">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-6 py-4 bg-slate-50 border border-slate-100 rounded-[2rem] font-bold text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Pesquisar..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-14 h-14 rounded-2xl flex items-center justify-center active:scale-90 transition-transform shadow-xl shrink-0"><span className="material-icons text-2xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-full bg-white shadow-2xl rounded-[2rem] overflow-hidden border border-slate-100 max-h-80 overflow-y-auto mt-2 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-5 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-sm text-slate-700 flex justify-between items-center group">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-400 transition-opacity">add_circle</span>
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* LISTA DE SELECIONADOS */}
          <div className="space-y-4">
            <div className="flex justify-between items-center px-2">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Louvores Selecionados</span>
              <span className="bg-indigo-600 text-white text-[9px] font-black px-3 py-1 rounded-full">{draft.songs.length} Hinos</span>
            </div>
            <div className="space-y-2.5">
              {draft.songs.length === 0 ? (
                <div className="py-8 text-center border-2 border-dashed border-slate-100 rounded-[2rem] bg-slate-50/30">
                  <p className="text-slate-300 text-[10px] font-black uppercase tracking-widest">Vazio</p>
                </div>
              ) : (
                draft.songs.map((s, i) => {
                  const stats = songStats[s];
                  return (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex flex-col p-5 bg-slate-50/50 rounded-[1.5rem] border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-lg ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <span className="material-icons text-slate-300 text-base">drag_indicator</span>
                          <span className="font-bold text-slate-700 text-sm truncate max-w-[200px]">#{i+1} {s}</span>
                        </div>
                        <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500"><span className="material-icons text-xl">close</span></button>
                      </div>
                      <div className="flex gap-3 mt-2.5 pl-8">
                        <button onClick={() => setShowHistoryModal(s)} className="flex items-center gap-1 text-[8px] font-black text-indigo-400 bg-white px-2.5 py-1 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-[10px]">calendar_month</span> DATAS
                        </button>
                        <div className="flex items-center gap-1 text-[8px] font-black text-amber-500 bg-white px-2.5 py-1 rounded-full border border-slate-100 shadow-sm">
                          <span className="material-icons text-[10px]">analytics</span> {stats?.count || 0} VEZES
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>

          <button 
            onClick={() => onSave(draft)} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-6 rounded-3xl font-black text-lg tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons">save</span>
            {editingId ? 'ATUALIZAR' : 'CONFIRMAR'}
          </button>
        </div>
      </div>

      {/* MODAL RECORRENCIA */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-20 h-20 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-8 text-amber-500">
              <span className="material-icons text-4xl">warning_amber</span>
            </div>
            <h3 className="text-2xl font-black text-[#1a1c3d] mb-3 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-xs">
              Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-5 bg-indigo-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-4 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL HISTORICO HINO */}
      {showHistoryModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[500] p-6 backdrop-blur-md" onClick={() => setShowHistoryModal(null)}>
          <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-sm animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="flex justify-between items-center mb-8">
              <h3 className="text-lg font-black text-[#1a1c3d] uppercase tracking-tighter pr-4 truncate">{showHistoryModal}</h3>
              <button onClick={() => setShowHistoryModal(null)} className="w-8 h-8 bg-slate-100 rounded-full flex items-center justify-center text-slate-300"><span className="material-icons">close</span></button>
            </div>
            <div className="max-h-60 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
              {songStats[showHistoryModal]?.history.map((date, idx) => (
                <div key={idx} className="p-4 bg-slate-50 rounded-xl flex justify-between items-center border border-slate-100">
                  <span className="font-bold text-slate-700 text-sm">{new Date(date + 'T12:00:00').toLocaleDateString('pt-BR')}</span>
                  <span className="text-[9px] font-black text-indigo-400 uppercase">Cantado</span>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

