import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    // Removendo possíveis caracteres especiais ou quebras problemáticas para WhatsApp
    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) { // Exceto quarta
      msg += `Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      else msg += `📡 Culto via Satélite\n`;
    } else {
      msg += `🌸 Culto Senhoras\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const records = groupedHistory[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-2xl mx-auto pb-10">
      {/* CABEÇALHO DE BUSCA ESTILO IMAGEM 1 */}
      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar..." 
            className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
          />
        </div>
        <button className="bg-[#1a1c3d] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl active:scale-90 transition-transform">
          <span className="material-icons">calendar_month</span>
        </button>
        <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shadow-orange-950/20 active:scale-90 transition-transform">
          <span className="material-icons">auto_stories</span>
        </button>
      </div>

      <div className="space-y-10">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-5xl text-slate-100 mb-3">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">Sem registros</p>
          </div>
        ) : (
          Object.entries(groupedHistory).map(([month, records]) => (
            <div key={month} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] whitespace-nowrap">{month}</span>
                <div className="flex-1 h-[1px] bg-slate-200/50"></div>
              </div>

              <div className="grid gap-6">
                {records.map(r => {
                  const dayCode = dayOfWeekNamesShort[new Date(r.date + 'T12:00:00').getDay()];
                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-xl border border-slate-50 p-8 flex justify-between items-start group hover:shadow-2xl transition-all">
                      <div>
                        <span className="text-indigo-600 font-black text-[11px] uppercase tracking-widest block mb-1">{dayCode}</span>
                        <h4 className="text-[#1a1c3d] font-black text-2xl tracking-tighter">{new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')}</h4>
                        <div className="mt-3 flex items-center gap-2">
                           <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full"></div>
                           <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{r.description}</span>
                        </div>
                      </div>

                      <div className="flex gap-2.5">
                        <button onClick={() => onEdit(r)} className="w-11 h-11 bg-amber-50 rounded-2xl flex items-center justify-center text-amber-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">edit</span>
                        </button>
                        <button onClick={() => shareIndividual(r)} className="w-11 h-11 bg-emerald-50 rounded-2xl flex items-center justify-center text-emerald-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">share</span>
                        </button>
                        <button onClick={() => setItemToDelete(r.id)} className="w-11 h-11 bg-rose-50 rounded-2xl flex items-center justify-center text-rose-500 active:scale-90 transition-transform">
                          <span className="material-icons text-xl">delete</span>
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>

      {/* MODAL RELATÓRIO MENSAL - ESTILO IMAGEM 2 */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[400] p-6 backdrop-blur-sm" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-scaleUp" onClick={e => e.stopPropagation()}>
            {/* Header Navy Blue */}
            <div className="bg-[#1a1c3d] p-10 relative">
              <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block mb-1">REGISTRO DE ESCALA</span>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter">RELATÓRIO MENSAL</h3>
              <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            {/* Body */}
            <div className="p-10 bg-white flex flex-col gap-4">
              <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-3">
                {Object.keys(groupedHistory).length === 0 ? (
                  <p className="text-slate-400 font-bold py-10 text-center">Sem dados mensais</p>
                ) : (
                  // Use Object.entries to avoid 'unknown' type errors during iteration
                  Object.entries(groupedHistory).map(([month]) => (
                    <button 
                      key={month} 
                      onClick={() => { shareMonth(month); setShowShareModal(false); }} 
                      className="w-full py-6 bg-indigo-50/50 text-[#1a1c3d] font-black rounded-3xl border border-indigo-100/50 hover:bg-indigo-100 transition-all active:scale-95 text-lg tracking-tight"
                    >
                      {month}
                    </button>
                  ))
                )}
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-full py-6 bg-slate-50 text-slate-800 font-black rounded-3xl uppercase text-sm tracking-widest mt-2 active:scale-95"
              >
                FECHAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DELETAR */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8">
              <span className="material-icons text-rose-500 text-3xl">delete_outline</span>
            </div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter">Excluir Relatório?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-5 py-3.5 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleInternalSave = () => {
    onSave(draft);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 2500);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const shareOnlyPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES - ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-xl mx-auto space-y-6 animate-fadeIn">
      <div className="bg-white rounded-[3rem] shadow-2xl p-7 md:p-12 border border-white relative overflow-hidden">

        {/* Toast de Sucesso */}
        {showSuccess && (
          <div className="absolute inset-x-0 top-0 bg-emerald-500 text-white p-4 flex items-center justify-center gap-2 animate-fadeIn z-[100] font-black text-xs uppercase tracking-widest">
            <span className="material-icons">check_circle</span> Relatório salvo com sucesso!
          </div>
        )}

        <div className="space-y-7">
          {/* DATA DO CULTO */}
          <div className="flex flex-col items-center">
            <Label>Data do Culto</Label>
            <FormInput className="w-full">
              <input 
                type="date" 
                value={draft.date} 
                onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
              />
            </FormInput>
            <div className="mt-2.5 bg-indigo-50 px-4 py-1 rounded-full">
              <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest leading-none">DIA: {dateInfo.name}</span>
            </div>
          </div>

          {/* SELETOR EBD/DOM NO DOMINGO */}
          {dateInfo.isSunday && (
            <div className="flex flex-col">
              <Label>Período</Label>
              <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl shadow-sm">
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-md' : 'text-slate-400'}`}>EBD</button>
                <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-md' : 'text-slate-400'}`}>DOM</button>
              </div>
            </div>
          )}

          {/* 1. SEÇÃO DE LOUVORES (AGORA ANTES DOS OBREIROS) */}
          <div className="space-y-4 pt-4 border-t border-slate-50">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-2">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Pesquisar..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-[calc(100%-3.5rem)] left-7 md:left-12 bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center group">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons opacity-0 group-hover:opacity-100 text-indigo-400 text-sm transition-opacity">add_circle</span>
                  </div>
                ))}
              </div>
            )}

            {/* LISTA DE SELECIONADOS */}
            <div className="space-y-3 pt-2">
              <div className="flex justify-between items-center px-1">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Ordem dos Louvores</span>
                {draft.songs.length > 0 && (
                  <button onClick={shareOnlyPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 active:scale-95">
                    <span className="material-icons text-xs">share</span> COMPARTILHAR LOUVORES
                  </button>
                )}
              </div>
              <div className="space-y-2 max-h-72 overflow-y-auto pr-1 custom-scrollbar">
                {draft.songs.length === 0 ? (
                  <div className="py-6 text-center border-2 border-dashed border-slate-100 rounded-2xl bg-slate-50/20">
                    <p className="text-slate-300 text-[9px] font-black uppercase tracking-widest">Aguardando hinos...</p>
                  </div>
                ) : (
                  draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))
                )}
              </div>
            </div>
          </div>

          {/* 2. ESCALA DE OBREIROS */}
          <div className="space-y-5 pt-6 border-t border-slate-50">
            <div className="flex flex-col">
              <Label>Portão</Label>
              <FormInput>
                <select 
                  value={draft.roles.gate} 
                  onChange={e => updateRole('gate', e.target.value)} 
                  className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                >
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </FormInput>
            </div>

            {/* MENSAGEM ESPECIAL: QUARTA FEIRA */}
            {dateInfo.isWednesday && (
               <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
                 <span className="text-lg">🌸</span>
                 <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
               </div>
            )}

            {!dateInfo.isWednesday && (
              <div className="space-y-5">
                <div className="flex flex-col">
                  <Label>Louvor (Escala)</Label>
                  <FormInput>
                    <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>

                {!dateInfo.isMonday && (
                  <div className="flex flex-col">
                    <Label>Palavra</Label>
                    <FormInput>
                      <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>
                )}

                {/* MENSAGEM TRANSMISSÃO OU TEXTO BÍBLICO NO MESMO ESPAÇO */}
                <div className="flex flex-col min-h-[70px] justify-end">
                  {draft.roles.word === 'TRANSMISSÃO' ? (
                    <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                      <span className="text-lg">📡</span>
                      <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                    </div>
                  ) : (
                    <>
                      <Label>Texto Bíblico</Label>
                      <FormInput>
                        <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none placeholder:text-slate-200" />
                      </FormInput>
                    </>
                  )}
                </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleInternalSave} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white shadow-indigo-900/20' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons text-xl">save</span>
            {editingId ? 'ATUALIZAR RELATÓRIO' : 'CONFIRMAR E SALVAR'}
          </button>
        </div>
      </div>

      {/* MODAL RECORRENCIA (MANTIDO) */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6 text-amber-500">
              <span className="material-icons text-3xl">warning_amber</span>
            </div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">
              Cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?
            </p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) { // Exceto quarta
      msg += `Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      else msg += `📡 Culto via Satélite\n`;
    } else {
      msg += `🌸 Culto Senhoras\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const records = groupedHistory[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const RoleItem = ({ label, value }: { label: string, value?: string }) => {
    if (!value) return null;
    return (
      <div className="flex flex-col border-l-2 border-indigo-100 pl-3">
        <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">{label}</span>
        <span className="text-[11px] font-black text-[#1a1c3d] leading-none">{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-2xl mx-auto pb-10 px-1">
      {/* CABEÇALHO DE BUSCA */}
      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar..." 
            className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
          />
        </div>
        <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shadow-orange-950/20 active:scale-90 transition-transform">
          <span className="material-icons">share</span>
        </button>
      </div>

      <div className="space-y-10">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-5xl text-slate-100 mb-3">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">Sem registros</p>
          </div>
        ) : (
          Object.entries(groupedHistory).map(([month, records]) => (
            <div key={month} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] whitespace-nowrap">{month}</span>
                <div className="flex-1 h-[1px] bg-slate-200/40"></div>
              </div>

              <div className="grid gap-6">
                {records.map(r => {
                  const dateObj = new Date(r.date + 'T12:00:00');
                  const dayCode = dayOfWeekNamesShort[dateObj.getDay()];
                  const isLadiesDay = dateObj.getDay() === 3;
                  const isSatellite = r.roles.word === 'TRANSMISSÃO';

                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-xl border border-slate-50 overflow-hidden flex flex-col hover:shadow-2xl transition-all group">
                      {/* Top Bar - Data e Botões */}
                      <div className="px-8 py-6 flex justify-between items-center bg-slate-50/40 border-b border-slate-50">
                        <div className="flex items-center gap-4">
                          <div className="bg-white px-3 py-1.5 rounded-xl border border-slate-100 flex flex-col items-center justify-center shadow-sm">
                            <span className="text-indigo-600 font-black text-[9px] uppercase leading-none">{dayCode}</span>
                            <span className="text-[#1a1c3d] font-black text-base leading-none mt-1">{dateObj.getDate().toString().padStart(2, '0')}</span>
                          </div>
                          <div className="flex flex-col">
                            <h4 className="text-[#1a1c3d] font-black text-lg tracking-tighter leading-none">{month.split(' / ')[0]} {dateObj.getFullYear()}</h4>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">{r.description}</span>
                          </div>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => onEdit(r)} className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500 active:scale-90"><span className="material-icons text-lg">edit</span></button>
                          <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-emerald-50 rounded-xl flex items-center justify-center text-emerald-500 active:scale-90"><span className="material-icons text-lg">share</span></button>
                          <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center text-rose-500 active:scale-90"><span className="material-icons text-lg">delete</span></button>
                        </div>
                      </div>

                      {/* Detalhes da Escala */}
                      <div className="p-8 space-y-6 bg-white">
                        {/* Selos de Status */}
                        {(isLadiesDay || isSatellite) && (
                          <div className="flex gap-2 mb-2">
                             {isLadiesDay && <span className="bg-indigo-50 text-indigo-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-indigo-100 uppercase tracking-widest flex items-center gap-1">🌸 Senhoras</span>}
                             {isSatellite && <span className="bg-amber-50 text-amber-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-amber-100 uppercase tracking-widest flex items-center gap-1">📡 Satélite</span>}
                          </div>
                        )}

                        {/* Obreiros */}
                        <div className="flex flex-wrap gap-x-8 gap-y-4">
                          <RoleItem label="Portão" value={r.roles.gate} />
                          {!isLadiesDay && (
                            <>
                              <RoleItem label="Louvor" value={r.roles.praise} />
                              <RoleItem label="Palavra" value={r.roles.word} />
                              {!isSatellite && <RoleItem label="Texto" value={r.roles.scripture} />}
                            </>
                          )}
                        </div>

                        {/* Louvores */}
                        <div className="pt-6 border-t border-slate-50">
                           <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest block mb-4">Louvores do Culto</span>
                           <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                             {r.songs.map((s, idx) => (
                               <div key={idx} className="bg-slate-50/50 p-3 rounded-xl flex items-center gap-3 border border-transparent group-hover:border-slate-100 transition-all">
                                 <span className="text-[10px] font-black text-indigo-400">#{(idx+1)}</span>
                                 <span className="text-[11px] font-bold text-slate-600 truncate">{s}</span>
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>

      {/* MODAL RELATÓRIO MENSAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-scaleUp border border-white" onClick={e => e.stopPropagation()}>
            <div className="bg-[#1a1c3d] p-10 relative">
              <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block mb-1">GESTÃO DE OBREIROS</span>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter">RELATÓRIO MENSAL</h3>
              <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            <div className="p-10 bg-white flex flex-col gap-4">
              <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-3">
                {Object.keys(groupedHistory).length === 0 ? (
                  <p className="text-slate-400 font-bold py-10 text-center text-xs">Nenhum mês registrado ainda</p>
                ) : (
                  Object.keys(groupedHistory).map(month => (
                    <button 
                      key={month} 
                      onClick={() => { shareMonth(month); setShowShareModal(false); }} 
                      className="w-full py-5 bg-indigo-50/50 text-[#1a1c3d] font-black rounded-3xl border border-indigo-100/50 hover:bg-indigo-100 transition-all active:scale-95 text-base tracking-tight flex items-center justify-center gap-3"
                    >
                      <span className="material-icons text-indigo-400">calendar_month</span>
                      {month}
                    </button>
                  ))
                )}
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-full py-5 bg-slate-50 text-slate-800 font-black rounded-3xl uppercase text-xs tracking-widest mt-2 active:scale-95"
              >
                FECHAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DELETAR */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8 text-rose-500">
              <span className="material-icons text-4xl">delete_outline</span>
            </div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter leading-tight">Excluir este relatório permanentemente?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) { // Exceto quarta
      msg += `Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      else msg += `📡 Culto via Satélite\n`;
    } else {
      msg += `🌸 Culto Senhoras\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    // Cast groupedHistory to expected record type to ensure records inference
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const RoleItem = ({ label, value }: { label: string, value?: string }) => {
    if (!value) return null;
    return (
      <div className="flex flex-col border-l-2 border-indigo-100 pl-3">
        <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">{label}</span>
        <span className="text-[11px] font-black text-[#1a1c3d] leading-none">{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-2xl mx-auto pb-10 px-1">
      {/* CABEÇALHO DE BUSCA */}
      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input 
            type="text" 
            value={searchTerm} 
            onChange={e => setSearchTerm(e.target.value)} 
            placeholder="Pesquisar..." 
            className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" 
          />
        </div>
        <button onClick={() => setShowShareModal(true)} className="bg-[#ff9900] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shadow-orange-950/20 active:scale-90 transition-transform">
          <span className="material-icons">share</span>
        </button>
      </div>

      <div className="space-y-10">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-5xl text-slate-100 mb-3">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">Sem registros</p>
          </div>
        ) : (
          // Fix: Cast Object.entries to resolve 'unknown' type error when calling .map()
          (Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
            <div key={month} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] whitespace-nowrap">{month}</span>
                <div className="flex-1 h-[1px] bg-slate-200/40"></div>
              </div>

              <div className="grid gap-6">
                {records.map(r => {
                  const dateObj = new Date(r.date + 'T12:00:00');
                  const dayCode = dayOfWeekNamesShort[dateObj.getDay()];
                  const isLadiesDay = dateObj.getDay() === 3;
                  const isSatellite = r.roles.word === 'TRANSMISSÃO';

                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-xl border border-slate-50 overflow-hidden flex flex-col hover:shadow-2xl transition-all group">
                      {/* Top Bar - Data e Botões */}
                      <div className="px-8 py-6 flex justify-between items-center bg-slate-50/40 border-b border-slate-50">
                        <div className="flex items-center gap-4">
                          <div className="bg-white px-3 py-1.5 rounded-xl border border-slate-100 flex flex-col items-center justify-center shadow-sm">
                            <span className="text-indigo-600 font-black text-[9px] uppercase leading-none">{dayCode}</span>
                            <span className="text-[#1a1c3d] font-black text-base leading-none mt-1">{dateObj.getDate().toString().padStart(2, '0')}</span>
                          </div>
                          <div className="flex flex-col">
                            <h4 className="text-[#1a1c3d] font-black text-lg tracking-tighter leading-none">{month.split(' / ')[0]} {dateObj.getFullYear()}</h4>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">{r.description}</span>
                          </div>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => onEdit(r)} className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500 active:scale-90"><span className="material-icons text-lg">edit</span></button>
                          <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-emerald-50 rounded-xl flex items-center justify-center text-emerald-500 active:scale-90"><span className="material-icons text-lg">share</span></button>
                          <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center text-rose-500 active:scale-90"><span className="material-icons text-lg">delete</span></button>
                        </div>
                      </div>

                      {/* Detalhes da Escala */}
                      <div className="p-8 space-y-6 bg-white">
                        {/* Selos de Status */}
                        {(isLadiesDay || isSatellite) && (
                          <div className="flex gap-2 mb-2">
                             {isLadiesDay && <span className="bg-indigo-50 text-indigo-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-indigo-100 uppercase tracking-widest flex items-center gap-1">🌸 Senhoras</span>}
                             {isSatellite && <span className="bg-amber-50 text-amber-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-amber-100 uppercase tracking-widest flex items-center gap-1">📡 Satélite</span>}
                          </div>
                        )}

                        {/* Obreiros */}
                        <div className="flex flex-wrap gap-x-8 gap-y-4">
                          <RoleItem label="Portão" value={r.roles.gate} />
                          {!isLadiesDay && (
                            <>
                              <RoleItem label="Louvor" value={r.roles.praise} />
                              <RoleItem label="Palavra" value={r.roles.word} />
                              {!isSatellite && <RoleItem label="Texto" value={r.roles.scripture} />}
                            </>
                          )}
                        </div>

                        {/* Louvores */}
                        <div className="pt-6 border-t border-slate-50">
                           <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest block mb-4">Louvores do Culto</span>
                           <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                             {r.songs.map((s, idx) => (
                               <div key={idx} className="bg-slate-50/50 p-3 rounded-xl flex items-center gap-3 border border-transparent group-hover:border-slate-100 transition-all">
                                 <span className="text-[10px] font-black text-indigo-400">#{(idx+1)}</span>
                                 <span className="text-[11px] font-bold text-slate-600 truncate">{s}</span>
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>
          ))
        )}
      </div>

      {/* MODAL RELATÓRIO MENSAL */}
      {showShareModal && (
        <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-scaleUp border border-white" onClick={e => e.stopPropagation()}>
            <div className="bg-[#1a1c3d] p-10 relative">
              <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block mb-1">GESTÃO DE OBREIROS</span>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter">RELATÓRIO MENSAL</h3>
              <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>

            <div className="p-10 bg-white flex flex-col gap-4">
              <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-3">
                {Object.keys(groupedHistory).length === 0 ? (
                  <p className="text-slate-400 font-bold py-10 text-center text-xs">Nenhum mês registrado ainda</p>
                ) : (
                  // Fix: Cast Object.keys to string[] to resolve 'unknown' type error when calling .map()
                  (Object.keys(groupedHistory) as string[]).map(month => (
                    <button 
                      key={month} 
                      onClick={() => { shareMonth(month); setShowShareModal(false); }} 
                      className="w-full py-5 bg-indigo-50/50 text-[#1a1c3d] font-black rounded-3xl border border-indigo-100/50 hover:bg-indigo-100 transition-all active:scale-95 text-base tracking-tight flex items-center justify-center gap-3"
                    >
                      <span className="material-icons text-indigo-400">calendar_month</span>
                      {month}
                    </button>
                  ))
                )}
              </div>
              <button 
                onClick={() => setShowShareModal(false)} 
                className="w-full py-5 bg-slate-50 text-slate-800 font-black rounded-3xl uppercase text-xs tracking-widest mt-2 active:scale-95"
              >
                FECHAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL DELETAR */}
      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[400] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8 text-rose-500">
              <span className="material-icons text-4xl">delete_outline</span>
            </div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter leading-tight">Excluir este relatório permanentemente?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [showHistoryModal, setShowHistoryModal] = useState<string | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 3000);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
      {showSuccess && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 bg-emerald-500 text-white px-8 py-4 rounded-full shadow-2xl z-[1000] flex items-center gap-3 animate-scaleUp font-black text-xs uppercase tracking-widest">
          <span className="material-icons">check_circle</span> Registro Salvo com Sucesso!
        </div>
      )}

      <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
        <div className="space-y-8">
          {/* DATA E PERÍODO */}
          <div className="grid grid-cols-1 gap-6">
            <div className="flex flex-col items-center">
              <Label>Data do Culto</Label>
              <FormInput className="w-full">
                <input 
                  type="date" 
                  value={draft.date} 
                  onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                  className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                />
              </FormInput>
              <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
              </div>
            </div>

            {dateInfo.isSunday && (
              <div className="flex flex-col">
                <Label>Período</Label>
                <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                  <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                  <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                </div>
              </div>
            )}
          </div>

          {/* 1. SEÇÃO DE LOUVORES (AGORA PRIMEIRO) */}
          <div className="space-y-4 pt-6 border-t border-slate-50">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-2">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Hino ou Nº..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                {draft.songs.length > 0 && (
                  <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                    <span className="material-icons text-xs">share</span> COMPARTILHAR LOUVORES
                  </button>
                )}
              </div>
              <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                {draft.songs.map((s, i) => (
                  <div 
                    key={`${s}-${i}`} 
                    draggable 
                    onDragStart={(e) => onDragStart(e, i)}
                    onDragOver={(e) => onDragOver(e, i)}
                    onDragEnd={() => setDraggedIndex(null)}
                    className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                  >
                    <div className="flex items-center gap-3 overflow-hidden">
                      <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                      <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                    </div>
                    <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* 2. ESCALA DE OBREIROS */}
          <div className="space-y-5 pt-6 border-t border-slate-50">
            <div className="flex flex-col">
              <Label>Portão</Label>
              <FormInput>
                <select 
                  value={draft.roles.gate} 
                  onChange={e => updateRole('gate', e.target.value)} 
                  className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                >
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </FormInput>
            </div>

            {dateInfo.isWednesday && (
               <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
                 <span className="text-lg">🌸</span>
                 <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
               </div>
            )}

            {!dateInfo.isWednesday && (
              <div className="space-y-5">
                <div className="flex flex-col">
                  <Label>Louvor</Label>
                  <FormInput>
                    <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>

                {!dateInfo.isMonday && (
                  <div className="flex flex-col">
                    <Label>Palavra</Label>
                    <FormInput>
                      <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>
                )}

                <div className="flex flex-col min-h-[70px] justify-end">
                  {draft.roles.word === 'TRANSMISSÃO' ? (
                    <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                      <span className="text-lg">📡</span>
                      <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                    </div>
                  ) : (
                    <>
                      <Label>Texto Bíblico</Label>
                      <FormInput>
                        <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                      </FormInput>
                    </>
                  )}
                </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleSave} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons">save</span>
            {editingId ? 'ATUALIZAR' : 'CONFIRMAR'}
          </button>
        </div>
      </div>

      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6 text-amber-500"><span className="material-icons text-3xl">warning_amber</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?</p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';

interface Props {
  history: ServiceRecord[];
  onDelete: (id: string) => void;
  onEdit: (record: ServiceRecord) => void;
  onClearAll: () => void;
}

const HistoryList: React.FC<Props> = ({ history, onDelete, onEdit }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [showShareModal, setShowShareModal] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);

  const monthNames = ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"];
  const dayOfWeekNamesShort = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];

  const groupedHistory = useMemo(() => {
    const filtered = history.filter(r => 
      r.date.includes(searchTerm) || 
      r.roles?.word?.toLowerCase().includes(searchTerm.toLowerCase()) || 
      r.songs.some(s => s.toLowerCase().includes(searchTerm.toLowerCase()))
    ).sort((a, b) => b.date.localeCompare(a.date));

    const groups: Record<string, ServiceRecord[]> = {};
    filtered.forEach(record => {
      const date = new Date(record.date + 'T12:00:00');
      const key = `${monthNames[date.getMonth()]} / ${date.getFullYear()}`;
      if (!groups[key]) groups[key] = [];
      groups[key].push(record);
    });
    return groups;
  }, [history, searchTerm]);

  const shareIndividual = (record: ServiceRecord) => {
    const d = new Date(record.date + 'T12:00:00');
    const day = d.getDay();
    const dateFormatted = d.toLocaleDateString('pt-BR');

    let msg = `*Relatório ICM Santo Antônio II - ${dateFormatted}*\n\n`;
    msg += `*Culto:* ${record.description}\n\n`;
    msg += `*Escala:*\n`;
    msg += `Portão: ${record.roles.gate || '-'}\n`;

    if (day !== 3) {
      msg += `Louvor: ${record.roles.praise || '-'}\n`;
      if (day !== 1) msg += `Palavra: ${record.roles.word || '-'}\n`;
      if (record.roles.word !== 'TRANSMISSÃO') msg += `Texto Bíblico: ${record.roles.scripture || '-'}\n`;
      else msg += `📡 Culto via Satélite\n`;
    } else {
      msg += `🌸 Culto Senhoras\n`;
    }

    msg += `\n*Louvores:* \n`;
    record.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareMonth = (monthKey: string) => {
    const records = (groupedHistory as Record<string, ServiceRecord[]>)[monthKey];
    let msg = `*RESUMO ICM SANTO ANTÔNIO II - ${monthKey}*\n\n`;
    records.forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} - ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const shareAll = () => {
    let msg = `*HISTÓRICO COMPLETO ICM SANTO ANTÔNIO II*\n\n`;
    history.slice(0, 30).forEach(r => {
      msg += `📅 ${new Date(r.date + 'T12:00:00').toLocaleDateString('pt-BR')} | ${r.description}\n`;
    });
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const InfoTag = ({ label, value, icon }: { label: string, value?: string, icon: string }) => {
    if (!value) return null;
    return (
      <div className="flex flex-col border-l-2 border-indigo-100 pl-3">
        <div className="flex items-center gap-1 mb-0.5">
          <span className="material-icons text-[10px] text-slate-300">{icon}</span>
          <span className="text-[8px] font-black text-slate-300 uppercase tracking-widest">{label}</span>
        </div>
        <span className="text-[11px] font-black text-[#1a1c3d] truncate">{value}</span>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fadeIn max-w-2xl mx-auto pb-10">
      <div className="flex items-center gap-3">
        <div className="flex-1 bg-white rounded-full flex items-center px-6 py-4 shadow-xl border border-slate-50">
          <span className="material-icons text-slate-300 mr-3">search</span>
          <input type="text" value={searchTerm} onChange={e => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="w-full bg-transparent font-bold text-slate-600 outline-none placeholder:text-slate-300" />
        </div>
        <button onClick={shareAll} title="Compartilhar Tudo" className="bg-[#1a1c3d] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl active:scale-90 transition-transform">
          <span className="material-icons">history_edu</span>
        </button>
        <button onClick={() => setShowShareModal(true)} title="Relatório Mensal" className="bg-[#ff9900] text-white w-14 h-14 rounded-full flex items-center justify-center shadow-xl shadow-orange-950/20 active:scale-90 transition-transform">
          <span className="material-icons">auto_stories</span>
        </button>
      </div>

      <div className="space-y-12">
        {Object.keys(groupedHistory).length === 0 ? (
          <div className="text-center py-20 bg-white rounded-[3rem] border-2 border-dashed border-slate-100">
            <span className="material-icons text-5xl text-slate-100 mb-3">history_toggle_off</span>
            <p className="text-slate-300 font-black uppercase tracking-widest text-[10px]">Sem registros</p>
          </div>
        ) : (
          (Object.entries(groupedHistory) as [string, ServiceRecord[]][]).map(([month, records]) => (
            <div key={month} className="space-y-6">
              <div className="flex items-center gap-4 px-4">
                <span className="text-[11px] font-black text-slate-300 uppercase tracking-[0.2em] whitespace-nowrap">{month}</span>
                <div className="flex-1 h-[1px] bg-slate-200/50"></div>
              </div>

              <div className="grid gap-8">
                {records.map(r => {
                  const dateObj = new Date(r.date + 'T12:00:00');
                  const dayCode = dayOfWeekNamesShort[dateObj.getDay()];
                  const isLadiesDay = dateObj.getDay() === 3;
                  const isSatellite = r.roles.word === 'TRANSMISSÃO';

                  return (
                    <div key={r.id} className="bg-white rounded-[2.5rem] shadow-xl border border-slate-50 overflow-hidden group hover:shadow-2xl transition-all">
                      <div className="bg-slate-50/50 px-8 py-5 flex justify-between items-center border-b border-slate-100">
                        <div className="flex items-center gap-4">
                          <div className="bg-white px-3 py-1.5 rounded-xl border border-slate-100 flex flex-col items-center justify-center shadow-sm">
                            <span className="text-indigo-600 font-black text-[9px] uppercase leading-none">{dayCode}</span>
                            <span className="text-[#1a1c3d] font-black text-base leading-none mt-1">{dateObj.getDate().toString().padStart(2, '0')}</span>
                          </div>
                          <div className="flex flex-col">
                            <h4 className="text-[#1a1c3d] font-black text-lg tracking-tighter leading-none">{month.split(' / ')[0]} {dateObj.getFullYear()}</h4>
                            <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">{r.description}</span>
                          </div>
                        </div>
                        <div className="flex gap-2">
                          <button onClick={() => onEdit(r)} className="w-10 h-10 bg-amber-50 rounded-xl flex items-center justify-center text-amber-500 active:scale-90 transition-transform"><span className="material-icons text-lg">edit</span></button>
                          <button onClick={() => shareIndividual(r)} className="w-10 h-10 bg-emerald-50 rounded-xl flex items-center justify-center text-emerald-500 active:scale-90 transition-transform"><span className="material-icons text-lg">share</span></button>
                          <button onClick={() => setItemToDelete(r.id)} className="w-10 h-10 bg-rose-50 rounded-xl flex items-center justify-center text-rose-500 active:scale-90 transition-transform"><span className="material-icons text-lg">delete</span></button>
                        </div>
                      </div>

                      <div className="p-8 space-y-6">
                        {(isLadiesDay || isSatellite) && (
                          <div className="flex gap-2">
                             {isLadiesDay && <span className="bg-indigo-50 text-indigo-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-indigo-100 uppercase tracking-widest flex items-center gap-1">🌸 Senhoras</span>}
                             {isSatellite && <span className="bg-amber-50 text-amber-600 text-[8px] font-black px-3 py-1.5 rounded-full border border-amber-100 uppercase tracking-widest flex items-center gap-1">📡 Satélite</span>}
                          </div>
                        )}

                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                          <InfoTag label="Portão" value={r.roles.gate} icon="door_front" />
                          {!isLadiesDay && (
                            <>
                              <InfoTag label="Louvor" value={r.roles.praise} icon="music_note" />
                              <InfoTag label="Palavra" value={r.roles.word} icon="record_voice_over" />
                              {!isSatellite && <InfoTag label="Texto" value={r.roles.scripture} icon="menu_book" />}
                            </>
                          )}
                        </div>

                        <div className="pt-6 border-t border-slate-50">
                           <div className="flex items-center gap-2 mb-3">
                              <span className="material-icons text-indigo-400 text-sm">queue_music</span>
                              <span className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Louvores do Culto</span>
                           </div>
                           <div className="grid gap-2">
                             {r.songs.map((s, idx) => (
                               <div key={idx} className="bg-slate-50/50 p-3 rounded-xl flex items-center gap-3 border border-transparent hover:border-indigo-50 hover:bg-white transition-all">
                                 <span className="text-[10px] font-black text-indigo-400">#{(idx+1)}</span>
                                 <span className="text-[11px] font-bold text-slate-600 truncate">{s}</span>
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))
        )}
      </div>

      {showShareModal && (
        <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[500] p-6 backdrop-blur-sm" onClick={() => setShowShareModal(false)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-sm overflow-hidden animate-scaleUp" onClick={e => e.stopPropagation()}>
            <div className="bg-[#1a1c3d] p-10 relative">
              <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block mb-1">REGISTRO DE ESCALA</span>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter">RELATÓRIO MENSAL</h3>
              <button onClick={() => setShowShareModal(false)} className="absolute top-8 right-8 w-10 h-10 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90">
                <span className="material-icons text-xl">close</span>
              </button>
            </div>
            <div className="p-10 bg-white flex flex-col gap-4">
              <div className="max-h-60 overflow-y-auto pr-2 custom-scrollbar flex flex-col gap-3">
                {Object.keys(groupedHistory).length === 0 ? (
                  <p className="text-slate-400 font-bold py-10 text-center text-xs">Sem dados mensais</p>
                ) : (
                  (Object.keys(groupedHistory) as string[]).map(month => (
                    <button key={month} onClick={() => { shareMonth(month); setShowShareModal(false); }} className="w-full py-6 bg-indigo-50/50 text-[#1a1c3d] font-black rounded-3xl border border-indigo-100/50 hover:bg-indigo-100 transition-all active:scale-95 text-lg tracking-tight">
                      {month}
                    </button>
                  ))
                )}
              </div>
              <button onClick={() => setShowShareModal(false)} className="w-full py-6 bg-slate-50 text-slate-800 font-black rounded-3xl uppercase text-sm tracking-widest mt-2 active:scale-95">FECHAR</button>
            </div>
          </div>
        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[500] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8 text-rose-500"><span className="material-icons text-4xl">delete_outline</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter leading-tight">Excluir este relatório permanentemente?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useEffect, useMemo } from 'react';
import { INITIAL_PRAISE_LIST } from './constants';
import { ServiceRecord, SongStats, ServiceDraft } from './types';
import ServiceForm from './components/ServiceForm';
import HistoryList from './components/HistoryList';
import RankingList from './components/RankingList';
import BackupRestore from './components/BackupRestore';
import UnplayedList from './components/UnplayedList';
import WorkerStats from './components/WorkerStats';
import WorkerRanking from './components/WorkerRanking';
import { initDB, saveData, loadData } from './db';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'workers' | 'suggestions' | 'praise-ranking' | 'unplayed' | 'settings'>('new');
  const [history, setHistory] = useState<ServiceRecord[]>([]);
  const [customSongs, setCustomSongs] = useState<string[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [isOffline, setIsOffline] = useState(!navigator.onLine);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const getTodayDate = () => {
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
  };

  const emptyRoles = { gate: '', praise: '', word: '', scripture: '' };

  const [draft, setDraft] = useState<ServiceDraft>({
    date: getTodayDate(),
    description: '',
    songs: [],
    roles: { ...emptyRoles }
  });

  useEffect(() => {
    const handleOnline = () => setIsOffline(false);
    const handleOffline = () => setIsOffline(true);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    const setup = async () => {
      try {
        await initDB();
        const data = await loadData();
        if (data) {
          if (data.history) setHistory(data.history);
          if (data.customSongs) setCustomSongs(data.customSongs);
          if (data.draft) setDraft({ ...data.draft, date: getTodayDate(), roles: data.draft.roles || { ...emptyRoles } });
        }
      } catch (e) {
        console.error("Erro no DB", e);
      } finally {
        setIsLoading(false);
      }
    };
    setup();
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    if (!isLoading) saveData({ history, customSongs, draft });
  }, [history, customSongs, draft, isLoading]);

  const fullSongList = useMemo(() => {
    return [...new Set([...INITIAL_PRAISE_LIST, ...customSongs])].sort((a, b) => a.localeCompare(b));
  }, [customSongs]);

  const songStats = useMemo(() => {
    const stats: Record<string, SongStats> = {};
    history.forEach(record => {
      record.songs.forEach(song => {
        if (!stats[song]) stats[song] = { song, count: 0, lastDate: null, history: [] };
        stats[song].count++;
        stats[song].history.push(record.date);
      });
    });
    Object.keys(stats).forEach(s => {
      stats[s].history.sort((a, b) => b.localeCompare(a));
      stats[s].lastDate = stats[s].history[0];
    });
    return stats;
  }, [history]);

  const saveRecord = (data: Omit<ServiceRecord, 'id'>) => {
    if (editingId) {
      setHistory(prev => prev.map(r => r.id === editingId ? { ...data, id: editingId } : r));
      setEditingId(null);
    } else {
      setHistory(prev => [{ ...data, id: crypto.randomUUID() }, ...prev]);
    }
    setDraft({ date: getTodayDate(), description: '', songs: [], roles: { ...emptyRoles } });
  };

  const menuItems = [
    { id: 'new', icon: 'add_circle', label: 'Novo Culto' },
    { id: 'history', icon: 'history', label: 'Histórico' },
    { id: 'workers', icon: 'emoji_events', label: 'Ranking Obreiros' },
    { id: 'suggestions', icon: 'assignment_ind', label: 'Escala / Sugestão' },
    { id: 'praise-ranking', icon: 'trending_up', label: 'Ranking Hinos' },
    { id: 'unplayed', icon: 'assignment_late', label: 'Hinos Restantes' },
    { id: 'settings', icon: 'settings', label: 'Backup / Sistema' },
  ] as const;

  const handleTabChange = (id: typeof activeTab) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
    window.scrollTo(0,0);
  };

  const AppBrand = () => (
    <div className="flex items-center gap-5">
      <div className="w-16 h-16 bg-white rounded-2xl shadow-xl flex items-center justify-center p-2.5">
        <img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" alt="Logo" className="w-full h-full object-contain" />
      </div>
      <div className="flex flex-col">
        <div className="flex items-center gap-2">
           <div className="w-2 h-2 bg-amber-400 rounded-full animate-pulse"></div>
           <span className="text-white/60 font-black text-[10px] tracking-[0.2em] uppercase">Gestão de Culto</span>
        </div>
        <h1 className="text-white font-black text-2xl tracking-tighter leading-tight uppercase">Santo Antônio II</h1>
        <div className="mt-1 bg-white/10 self-start px-3 py-1 rounded-full flex items-center gap-2">
           <span className="material-icons text-amber-400 text-xs">analytics</span>
           <span className="text-white font-black text-[10px] uppercase">{history.length} Cultos Registrados</span>
        </div>
      </div>
    </div>
  );

  if (isLoading) return <div className="min-h-screen bg-[#1a1c3d] flex flex-col items-center justify-center text-white p-10"><img src="https://cdn-icons-png.flaticon.com/512/1672/1672225.png" className="w-20 h-20 animate-bounce mb-6" /><p className="font-black tracking-widest text-sm animate-pulse">CARREGANDO SISTEMA...</p></div>;

  return (
    <div className="min-h-screen bg-slate-100 flex flex-col md:flex-row">
      {/* SIDEBAR DESKTOP */}
      <aside className="hidden md:flex w-96 bg-[#1a1c3d] flex-col sticky top-0 h-screen shadow-2xl z-[150]">
        <div className="p-12 border-b border-white/5">
          <AppBrand />
        </div>
        <nav className="flex-1 py-10 overflow-y-auto custom-scrollbar">
          {menuItems.map(item => (
            <button 
              key={item.id}
              onClick={() => handleTabChange(item.id)}
              className={`w-full flex items-center gap-6 px-12 py-6 transition-all duration-300 ${activeTab === item.id ? 'bg-amber-400 text-[#1a1c3d] font-black' : 'text-white/40 hover:text-white hover:bg-white/5'}`}
            >
              <span className="material-icons text-2xl">{item.icon}</span>
              <span className="text-sm uppercase font-black tracking-widest">{item.label}</span>
            </button>
          ))}
        </nav>
      </aside>

      {/* HEADER MOBILE */}
      <header className="md:hidden bg-[#1a1c3d] text-white p-6 sticky top-0 z-[200] flex justify-between items-center shadow-2xl rounded-b-[2rem]">
        <AppBrand />
        <button onClick={() => setIsMobileMenuOpen(true)} className="p-4 bg-white/10 rounded-2xl active:scale-90 transition-transform">
          <span className="material-icons text-3xl">menu</span>
        </button>
      </header>

      {/* MOBILE DRAWER */}
      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-[300] md:hidden">
          <div className="absolute inset-0 bg-[#1a1c3d]/90 backdrop-blur-lg" onClick={() => setIsMobileMenuOpen(false)}></div>
          <div className="absolute top-0 right-0 bottom-0 w-[85%] bg-[#1a1c3d] shadow-2xl flex flex-col animate-fadeIn border-l border-white/5">
            <div className="p-10 flex justify-between items-center border-b border-white/5">
              <span className="text-white/40 font-black text-xs tracking-widest uppercase">Navegação Principal</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="w-12 h-12 bg-white/5 rounded-full flex items-center justify-center text-white/40"><span className="material-icons">close</span></button>
            </div>
            <nav className="flex-1 py-6 overflow-y-auto">
              {menuItems.map(item => (
                <button 
                  key={item.id}
                  onClick={() => handleTabChange(item.id)}
                  className={`w-full flex items-center gap-8 px-10 py-7 border-b border-white/5 ${activeTab === item.id ? 'text-amber-400 bg-white/5 font-black' : 'text-white/60'}`}
                >
                  <span className="material-icons text-3xl">{item.icon}</span>
                  <span className="text-base font-black uppercase tracking-widest">{item.label}</span>
                </button>
              ))}
            </nav>
          </div>
        </div>
      )}

      {/* MAIN CONTENT AREA */}
      <main className="flex-1 min-w-0">
        {isOffline && <div className="bg-amber-500 text-white text-[10px] font-black uppercase py-2.5 text-center sticky top-[92px] md:top-0 z-[190] shadow-lg">Você está operando offline. Os dados serão salvos localmente.</div>}

        <div className="p-4 md:p-16 animate-fadeIn max-w-6xl mx-auto">
          {activeTab === 'new' && <ServiceForm onSave={saveRecord} songStats={songStats} fullSongList={fullSongList} onRegisterNewSong={s => setCustomSongs(prev => [...prev, s])} draft={draft} setDraft={setDraft} editingId={editingId} onCancelEdit={() => setEditingId(null)} totalRecords={history.length} />}
          {activeTab === 'history' && <HistoryList history={history} onDelete={id => setHistory(prev => prev.filter(r => r.id !== id))} onEdit={r => { setEditingId(r.id); setDraft({ ...r }); setActiveTab('new'); }} onClearAll={() => {}} />}
          {activeTab === 'workers' && <WorkerRanking history={history} />}
          {activeTab === 'suggestions' && <WorkerStats history={history} />}
          {activeTab === 'praise-ranking' && <RankingList songStats={songStats} />}
          {activeTab === 'unplayed' && <UnplayedList fullSongList={fullSongList} history={history} />}
          {activeTab === 'settings' && <BackupRestore history={history} customSongs={customSongs} onRestore={(h, c) => { setHistory(h); setCustomSongs(c); }} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showSuccess, setShowSuccess] = useState(false);
  const [showFinalizeModal, setShowFinalizeModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleOpenFinalize = () => {
    setShowFinalizeModal(true);
  };

  const handleConfirmAndSave = () => {
    onSave(draft);
    setShowFinalizeModal(false);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 3000);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
      {/* Toast de Sucesso Pós-Salvamento */}
      {showSuccess && (
        <div className="fixed top-6 left-1/2 -translate-x-1/2 bg-emerald-500 text-white px-8 py-4 rounded-full shadow-2xl z-[1000] flex items-center gap-3 animate-scaleUp font-black text-xs uppercase tracking-widest">
          <span className="material-icons">check_circle</span> Registro Salvo com Sucesso!
        </div>
      )}

      <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
        <div className="space-y-8">
          {/* DATA E PERÍODO */}
          <div className="grid grid-cols-1 gap-6">
            <div className="flex flex-col items-center">
              <Label>Data do Culto</Label>
              <FormInput className="w-full">
                <input 
                  type="date" 
                  value={draft.date} 
                  onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                  className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                />
              </FormInput>
              <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
              </div>
            </div>

            {dateInfo.isSunday && (
              <div className="flex flex-col">
                <Label>Período</Label>
                <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                  <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                  <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                </div>
              </div>
            )}
          </div>

          {/* 1. SEÇÃO DE LOUVORES (AGORA PRIMEIRO) */}
          <div className="space-y-4 pt-6 border-t border-slate-50">
            <Label>Adicionar Louvores</Label>
            <div className="flex gap-2">
              <input 
                type="text" 
                value={inputValue} 
                onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                placeholder="Hino ou Nº..." 
              />
              <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
            </div>
            {showSuggestions && suggestions.length > 0 && (
              <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                {suggestions.map(s => (
                  <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                    <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                    <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                  </div>
                ))}
              </div>
            )}

            <div className="space-y-3">
              <div className="flex justify-between items-center px-1">
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                {draft.songs.length > 0 && (
                  <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                    <span className="material-icons text-xs">share</span> COMPARTILHAR LOUVORES
                  </button>
                )}
              </div>
              <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                {draft.songs.map((s, i) => (
                  <div 
                    key={`${s}-${i}`} 
                    draggable 
                    onDragStart={(e) => onDragStart(e, i)}
                    onDragOver={(e) => onDragOver(e, i)}
                    onDragEnd={() => setDraggedIndex(null)}
                    className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                  >
                    <div className="flex items-center gap-3 overflow-hidden">
                      <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                      <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                    </div>
                    <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* 2. ESCALA DE OBREIROS */}
          <div className="space-y-5 pt-6 border-t border-slate-50">
            <div className="flex flex-col">
              <Label>Portão</Label>
              <FormInput>
                <select 
                  value={draft.roles.gate} 
                  onChange={e => updateRole('gate', e.target.value)} 
                  className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                >
                  <option value="">Selecione...</option>
                  {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </FormInput>
            </div>

            {dateInfo.isWednesday && (
               <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
                 <span className="text-lg">🌸</span>
                 <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
               </div>
            )}

            {!dateInfo.isWednesday && (
              <div className="space-y-5">
                <div className="flex flex-col">
                  <Label>Louvor</Label>
                  <FormInput>
                    <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                      <option value="">Selecione...</option>
                      {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                    </select>
                  </FormInput>
                </div>

                {!dateInfo.isMonday && (
                  <div className="flex flex-col">
                    <Label>Palavra</Label>
                    <FormInput>
                      <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>
                )}

                <div className="flex flex-col min-h-[70px] justify-end">
                  {draft.roles.word === 'TRANSMISSÃO' ? (
                    <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                      <span className="text-lg">📡</span>
                      <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                    </div>
                  ) : (
                    <>
                      <Label>Texto Bíblico</Label>
                      <FormInput>
                        <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                      </FormInput>
                    </>
                  )}
                </div>
              </div>
            )}
          </div>

          <button 
            onClick={handleOpenFinalize} 
            disabled={draft.songs.length === 0} 
            className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
          >
            <span className="material-icons">save</span>
            {editingId ? 'ATUALIZAR' : 'CONFIRMAR'}
          </button>
        </div>
      </div>

      {/* MODAL DE FINALIZAÇÃO (CONFORME IMAGEM DE REFERÊNCIA) */}
      {showFinalizeModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 backdrop-blur-md flex items-center justify-center z-[1000] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3.5rem] p-10 md:p-14 w-full max-w-sm shadow-2xl animate-scaleUp text-center flex flex-col items-center">

            {/* Ícone no topo */}
            <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mb-10">
              <span className="material-icons text-indigo-500 text-4xl">checklist</span>
            </div>

            <h3 className="text-2xl font-black text-[#1a1c3d] mb-3 tracking-tighter">Finalizar Registro?</h3>
            <p className="text-slate-400 font-medium mb-10 leading-relaxed text-sm">
              Confirme a data para salvar este culto:
            </p>

            {/* Input de Data estilizado conforme imagem */}
            <div className="w-full mb-10">
              <div className="bg-slate-50 border border-slate-100 rounded-[1.5rem] px-8 py-5 flex items-center justify-between shadow-sm">
                <span className="font-black text-[#1a1c3d] text-lg">
                  {new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                </span>
                <span className="material-icons text-indigo-200">expand_more</span>
              </div>
            </div>

            <div className="w-full flex flex-col gap-6">
              <button 
                onClick={handleConfirmAndSave} 
                className="w-full py-6 bg-[#4f46e5] text-white font-black rounded-[1.5rem] shadow-xl shadow-indigo-200 active:scale-95 transition-all text-sm uppercase tracking-widest"
              >
                CONFIRMAR E SALVAR
              </button>

              <button 
                onClick={() => setShowFinalizeModal(false)} 
                className="text-slate-400 font-black uppercase text-[11px] tracking-widest hover:text-[#1a1c3d] transition-colors"
              >
                VOLTAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL RECORRENCIA */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[500] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6 text-amber-500"><span className="material-icons text-3xl">warning_amber</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?</p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ServiceForm;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);
  const [showFinalizeModal, setShowFinalizeModal] = useState(false);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleOpenFinalize = () => {
    setShowFinalizeModal(true);
  };

  const handleConfirmAndSave = () => {
    onSave(draft);
    setShowFinalizeModal(false);
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <>
      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
        <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
          <div className="space-y-8">
            {/* DATA E PERÍODO */}
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col items-center">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input 
                    type="date" 
                    value={draft.date} 
                    onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                    className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                  />
                </FormInput>
                <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                  <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            {/* 1. SEÇÃO DE LOUVORES (AGORA PRIMEIRO) */}
            <div className="space-y-4 pt-6 border-t border-slate-50">
              <Label>Adicionar Louvores</Label>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={inputValue} 
                  onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                  placeholder="Hino ou Nº..." 
                />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                      <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                  {draft.songs.length > 0 && (
                    <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                      <span className="material-icons text-xs">share</span> COMPARTILHAR LOUVORES
                    </button>
                  )}
                </div>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                  {draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* 2. ESCALA DE OBREIROS */}
            <div className="space-y-5 pt-6 border-t border-slate-50">
              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select 
                    value={draft.roles.gate} 
                    onChange={e => updateRole('gate', e.target.value)} 
                    className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                  >
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {dateInfo.isWednesday && (
                <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
                  <span className="text-lg">🌸</span>
                  <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
                </div>
              )}

              {!dateInfo.isWednesday && (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <Label>Louvor</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col min-h-[70px] justify-end">
                    {draft.roles.word === 'TRANSMISSÃO' ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                        <span className="text-lg">📡</span>
                        <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                      </div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>

            <button 
              onClick={handleOpenFinalize} 
              disabled={draft.songs.length === 0} 
              className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
            >
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR' : 'CONFIRMAR'}
            </button>
          </div>
        </div>
      </div>

      {/* MODAL DE FINALIZAÇÃO - Movido para fora do container com transform/animação para corrigir posicionamento */}
      {showFinalizeModal && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 backdrop-blur-md flex items-center justify-center z-[2000] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3.5rem] p-10 md:p-14 w-full max-w-sm shadow-2xl animate-scaleUp text-center flex flex-col items-center">

            {/* Ícone no topo */}
            <div className="w-20 h-20 bg-indigo-50 rounded-full flex items-center justify-center mb-10">
              <span className="material-icons text-indigo-500 text-4xl">checklist</span>
            </div>

            <h3 className="text-2xl font-black text-[#1a1c3d] mb-3 tracking-tighter">Finalizar Registro?</h3>
            <p className="text-slate-400 font-medium mb-10 leading-relaxed text-sm">
              Confirme a data para salvar este culto:
            </p>

            {/* Input de Data estilizado conforme imagem */}
            <div className="w-full mb-10">
              <div className="bg-slate-50 border border-slate-100 rounded-[1.5rem] px-8 py-5 flex items-center justify-between shadow-sm">
                <span className="font-black text-[#1a1c3d] text-lg">
                  {new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                </span>
                <span className="material-icons text-indigo-200">expand_more</span>
              </div>
            </div>

            <div className="w-full flex flex-col gap-6">
              <button 
                onClick={handleConfirmAndSave} 
                className="w-full py-6 bg-[#4f46e5] text-white font-black rounded-[1.5rem] shadow-xl shadow-indigo-200 active:scale-95 transition-all text-sm uppercase tracking-widest"
              >
                CONFIRMAR E SALVAR
              </button>

              <button 
                onClick={() => setShowFinalizeModal(false)} 
                className="text-slate-400 font-black uppercase text-[11px] tracking-widest hover:text-[#1a1c3d] transition-colors"
              >
                VOLTAR
              </button>
            </div>
          </div>
        </div>
      )}

      {/* MODAL RECORRENCIA - Movido para fora do container para consistência de posicionamento */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[2000] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6 text-amber-500"><span className="material-icons text-3xl">warning_amber</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?</p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props { history: ServiceRecord[]; }

const CULTOS = [
  { id: 'SEG', label: 'SEGUNDA', fullName: 'SEGUNDA-FEIRA', roles: ['gate', 'word'] },
  { id: 'TER', label: 'TERÇA', fullName: 'TERÇA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'QUA', label: 'QUARTA', fullName: 'QUARTA-FEIRA', roles: ['gate'] },
  { id: 'QUI', label: 'QUINTA', fullName: 'QUINTA-FEIRA', roles: ['gate', 'praise', 'word'] },
  { id: 'SÁB', label: 'SÁBADO', fullName: 'SÁBADO', roles: ['gate', 'praise', 'word'] },
  { id: 'EBD', label: 'EBD', fullName: 'EBD', roles: ['gate', 'praise', 'word'] },
  { id: 'DOM', label: 'DOM', fullName: 'DOM', roles: ['gate', 'praise', 'word'] }
];

const WorkerStats: React.FC<Props> = ({ history }) => {
  const [expandedDay, setExpandedDay] = useState<string | null>(null);
  const [expandedRoles, setExpandedRoles] = useState<Record<string, boolean>>({});

  const officialWorkers = useMemo(() => WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name)), []);

  const getStats = (dayFullName: string, role: 'gate' | 'praise' | 'word') => {
    const today = new Date(); today.setHours(12, 0, 0, 0);
    return officialWorkers.map(name => {
      const filtered = history.filter(r => r.description === dayFullName && r.roles[role] === name).sort((a, b) => b.date.localeCompare(a.date));
      const lastDate = filtered[0]?.date || null;
      let daysSince = Infinity;
      if (lastDate) daysSince = Math.ceil((today.getTime() - new Date(lastDate + 'T12:00:00').getTime()) / (1000 * 60 * 60 * 24));
      return { name, lastDate, daysSince };
    }).sort((a, b) => b.daysSince - a.daysSince);
  };

  const toggleRole = (dayId: string, role: string) => {
    const key = `${dayId}-${role}`;
    setExpandedRoles(prev => ({ ...prev, [key]: !prev[key] }));
  };

  return (
    <div className="space-y-6 animate-fadeIn pb-10">
      <div className="px-2">
        <h2 className="text-2xl font-black text-slate-800">Sugestão de Escala</h2>
        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Quem realizou a função há mais tempo</p>
      </div>

      <div className="grid gap-4">
        {CULTOS.map(culto => (
          <div key={culto.id} className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
            <button onClick={() => setExpandedDay(expandedDay === culto.id ? null : culto.id)} className="w-full px-6 py-5 flex items-center justify-between bg-slate-50/50">
              <div className="flex items-center gap-4">
                <div className={`w-10 h-10 rounded-2xl flex items-center justify-center font-black text-[10px] shadow-sm ${expandedDay === culto.id ? 'bg-indigo-600 text-white' : 'bg-white text-slate-400'}`}>{culto.id}</div>
                <span className="font-black text-slate-700 text-sm tracking-wide">{culto.fullName}</span>
              </div>
              <span className={`material-icons text-slate-300 transition-transform ${expandedDay === culto.id ? 'rotate-180' : ''}`}>expand_more</span>
            </button>

            {expandedDay === culto.id && (
              <div className="p-6 space-y-6 animate-fadeIn">
                {culto.roles.map(role => {
                  const isRoleExpanded = expandedRoles[`${culto.id}-${role}`];
                  const stats = getStats(culto.fullName, role as any);
                  return (
                    <div key={role} className="border border-slate-50 rounded-2xl overflow-hidden">
                      <button onClick={() => toggleRole(culto.id, role)} className="w-full px-4 py-3 flex items-center justify-between bg-white hover:bg-slate-50">
                        <div className="flex items-center gap-2">
                          <span className="material-icons text-indigo-400 text-sm">{role === 'gate' ? 'door_front' : role === 'praise' ? 'music_note' : 'record_voice_over'}</span>
                          <span className="font-black text-[10px] text-slate-500 uppercase tracking-widest">{role === 'gate' ? 'Portão' : role === 'praise' ? 'Louvor' : 'Palavra'}</span>
                        </div>
                        <span className={`material-icons text-slate-200 text-sm transition-transform ${isRoleExpanded ? 'rotate-180' : ''}`}>keyboard_arrow_down</span>
                      </button>
                      {isRoleExpanded && (
                        <div className="p-4 bg-slate-50/30 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                          {stats.map((worker, i) => (
                            <div key={worker.name} className={`flex items-center justify-between p-3 rounded-xl border ${i === 0 ? 'bg-indigo-50/50 border-indigo-100' : 'bg-white border-transparent'}`}>
                              <span className="text-xs font-bold text-slate-700">{worker.name}</span>
                              <div className="text-right">
                                <span className={`text-[9px] font-black uppercase ${worker.daysSince === Infinity ? 'text-emerald-500' : 'text-indigo-400'}`}>
                                  {worker.daysSince === Infinity ? 'Ainda não executou função' : `${worker.daysSince}d`}
                                </span>
                              </div>
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

export default WorkerStats;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, dates: string[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, { gate: string[], praise: string[], word: string[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));
    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });
    history.forEach(r => {
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(r.date);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(r.date);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(r.date);
    });
    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.localeCompare(a));
      data[name].praise.sort((a, b) => b.localeCompare(a));
      data[name].word.sort((a, b) => b.localeCompare(a));
    });
    return Object.entries(data).map(([name, val]) => ({ name, ...val })).sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick }: { label: string, count: number, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.15em] mb-2 group-hover:text-indigo-600 transition-colors">{label}</span>
      <span className="text-3xl font-black text-[#1a1c3d] leading-none mb-2">{count}</span>
