        </div>
      )}

      {itemToDelete && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 flex items-center justify-center z-[500] p-6 backdrop-blur-md" onClick={() => setItemToDelete(null)}>
          <div className="bg-white rounded-[3.5rem] p-12 w-full max-w-xs animate-scaleUp text-center border border-white" onClick={e => e.stopPropagation()}>
            <div className="w-16 h-16 bg-rose-50 rounded-full flex items-center justify-center mx-auto mb-8 text-rose-500"><span className="material-icons text-4xl">delete_outline</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-8 uppercase tracking-tighter leading-tight">Excluir este relatório permanentemente?</h3>
            <div className="flex flex-col gap-3">
              <button onClick={() => { onDelete(itemToDelete!); setItemToDelete(null); }} className="w-full py-5 bg-rose-600 text-white font-black rounded-2xl shadow-lg active:scale-95">SIM, EXCLUIR</button>
              <button onClick={() => setItemToDelete(null)} className="w-full py-4 text-slate-300 font-black uppercase text-[10px] tracking-widest">Cancelar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HistoryList;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord, SongStats, ServiceDraft } from '../types';
import { WORKERS_LIST } from '../constants';

const Label = ({ children }: { children?: React.ReactNode }) => (
  <label className="text-[10px] md:text-[11px] font-black text-slate-400 uppercase tracking-widest block mb-2 text-center md:text-left">{children}</label>
);

const FormInput = ({ children, className = "" }: { children?: React.ReactNode, className?: string }) => (
  <div className={`bg-slate-50 border border-slate-100 rounded-2xl px-4 py-3 shadow-sm transition-all focus-within:shadow-md focus-within:bg-white focus-within:border-indigo-100 ${className}`}>
    {children}
  </div>
);

interface Props {
  onSave: (record: Omit<ServiceRecord, 'id'>) => void;
  songStats: Record<string, SongStats>;
  fullSongList: string[];
  onRegisterNewSong: (song: string) => void;
  draft: ServiceDraft;
  setDraft: React.Dispatch<React.SetStateAction<ServiceDraft>>;
  editingId: string | null;
  onCancelEdit: () => void;
  totalRecords?: number;
}

const ServiceForm: React.FC<Props> = ({ onSave, songStats, fullSongList, onRegisterNewSong, draft, setDraft, editingId, onCancelEdit }) => {
  const [inputValue, setInputValue] = useState('');
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [pendingSong, setPendingSong] = useState<{name: string, diff: number, lastDate: string} | null>(null);
  const [draggedIndex, setDraggedIndex] = useState<number | null>(null);

  const dayOfWeekNames = ['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'];
  const fullDayNames = ['DOMINGO', 'SEGUNDA-FEIRA', 'TERÇA-FEIRA', 'QUARTA-FEIRA', 'QUINTA-FEIRA', 'SEXTA-FEIRA', 'SÁBADO'];

  const dateInfo = useMemo(() => {
    const d = new Date(draft.date + 'T12:00:00');
    const dayIndex = d.getDay();
    return { name: dayOfWeekNames[dayIndex], fullName: fullDayNames[dayIndex], isSunday: dayIndex === 0, isMonday: dayIndex === 1, isWednesday: dayIndex === 3 };
  }, [draft.date]);

  useEffect(() => {
    if (!dateInfo.isSunday && !editingId) setDraft(prev => ({ ...prev, description: dateInfo.fullName }));
    else if (dateInfo.isSunday && !editingId && !['EBD', 'DOM'].includes(draft.description)) setDraft(prev => ({ ...prev, description: 'DOM' }));
  }, [dateInfo, editingId]);

  const updateRole = (role: keyof typeof draft.roles, name: string) => {
    setDraft(prev => ({ ...prev, roles: { ...prev.roles, [role]: name } }));
  };

  const handleSave = () => {
    onSave(draft);
    // Feedback visual opcional pode ser adicionado aqui se necessário
  };

  const checkAndAddSong = (songName: string) => {
    const name = songName.trim();
    if (!name) return;
    if (!fullSongList.includes(name)) onRegisterNewSong(name);

    const stats = songStats[name];
    if (stats && stats.lastDate) {
      const lastDate = new Date(stats.lastDate + 'T12:00:00');
      const today = new Date(); today.setHours(12, 0, 0, 0);
      const diffDays = Math.ceil(Math.abs(today.getTime() - lastDate.getTime()) / (1000 * 60 * 60 * 24));

      if (diffDays <= 30) { 
        setPendingSong({ name, diff: diffDays, lastDate: stats.lastDate }); 
        return; 
      }
    }
    executeAdd(name);
  };

  const executeAdd = (name: string) => {
    setDraft(prev => ({ ...prev, songs: [...prev.songs, name] }));
    setInputValue('');
    setShowSuggestions(false);
    setPendingSong(null);
  };

  const shareDraftPraise = () => {
    const dateFormatted = new Date(draft.date + 'T12:00:00').toLocaleDateString('pt-BR');
    let msg = `*LOUVORES ICM SANTO ANTÔNIO II*\nData: ${dateFormatted}\n\n`;
    draft.songs.forEach((s, i) => msg += `${i + 1}. ${s}\n`);
    window.open(`https://wa.me/?text=${encodeURIComponent(msg)}`, '_blank');
  };

  const onDragStart = (e: React.DragEvent, index: number) => {
    setDraggedIndex(index);
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedIndex === null || draggedIndex === index) return;
    const newSongs = [...draft.songs];
    const item = newSongs[draggedIndex];
    newSongs.splice(draggedIndex, 1);
    newSongs.splice(index, 0, item);
    setDraggedIndex(index);
    setDraft(prev => ({ ...prev, songs: newSongs }));
  };

  const suggestions = useMemo(() => {
    if (inputValue.length < 2) return [];
    const lowerInput = inputValue.toLowerCase();
    return fullSongList
      .filter(s => s.toLowerCase().includes(lowerInput))
      .sort((a, b) => {
        const aIsCias = a.startsWith('(CIAS)');
        const bIsCias = b.startsWith('(CIAS)');
        if (aIsCias && !bIsCias) return 1;
        if (!aIsCias && bIsCias) return -1;
        return 0; 
      })
      .slice(0, 30);
  }, [inputValue, fullSongList]);

  return (
    <>
      <div className="max-w-xl mx-auto space-y-6 animate-fadeIn pb-20">
        <div className="bg-white rounded-[3rem] shadow-2xl p-6 md:p-12 border border-white">
          <div className="space-y-8">
            {/* DATA E PERÍODO */}
            <div className="grid grid-cols-1 gap-6">
              <div className="flex flex-col items-center">
                <Label>Data do Culto</Label>
                <FormInput className="w-full">
                  <input 
                    type="date" 
                    value={draft.date} 
                    onChange={(e) => setDraft(prev => ({ ...prev, date: e.target.value }))} 
                    className="w-full bg-transparent font-black text-lg md:text-xl text-[#1a1c3d] text-center outline-none" 
                  />
                </FormInput>
                <div className="mt-2 bg-indigo-50 px-4 py-1 rounded-full">
                  <span className="text-indigo-600 font-black text-[9px] uppercase tracking-widest">DIA: {dateInfo.name}</span>
                </div>
              </div>

              {dateInfo.isSunday && (
                <div className="flex flex-col">
                  <Label>Período</Label>
                  <div className="flex bg-slate-50 border border-slate-100 p-1 rounded-2xl">
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'EBD' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'EBD' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>EBD</button>
                    <button onClick={() => setDraft(prev => ({ ...prev, description: 'DOM' }))} className={`flex-1 py-2.5 text-[11px] font-black rounded-xl transition-all ${draft.description === 'DOM' ? 'bg-[#1a1c3d] text-white shadow-lg' : 'text-slate-400'}`}>DOM</button>
                  </div>
                </div>
              )}
            </div>

            {/* 1. SEÇÃO DE LOUVORES */}
            <div className="space-y-4 pt-6 border-t border-slate-50">
              <Label>Adicionar Louvores</Label>
              <div className="flex gap-2">
                <input 
                  type="text" 
                  value={inputValue} 
                  onChange={e => {setInputValue(e.target.value); setShowSuggestions(true);}} 
                  className="flex-1 px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-700 outline-none focus:ring-4 focus:ring-indigo-50 focus:bg-white transition-all shadow-sm" 
                  placeholder="Hino ou Nº..." 
                />
                <button onClick={() => checkAndAddSong(inputValue)} className="bg-[#1a1c3d] text-white w-12 h-12 rounded-xl flex items-center justify-center active:scale-90 transition-transform shadow-lg shrink-0"><span className="material-icons text-xl">add</span></button>
              </div>
              {showSuggestions && suggestions.length > 0 && (
                <div className="absolute z-[250] w-[calc(100%-3rem)] md:w-[calc(100%-6rem)] bg-white shadow-2xl rounded-2xl overflow-hidden border border-slate-100 max-h-60 overflow-y-auto mt-1 animate-fadeIn">
                  {suggestions.map(s => (
                    <div key={s} onMouseDown={() => checkAndAddSong(s)} className="p-4 hover:bg-slate-50 cursor-pointer border-b border-slate-50 font-bold text-xs text-slate-700 flex justify-between items-center">
                      <span className={s.startsWith('(CIAS)') ? 'text-slate-400' : 'text-[#1a1c3d]'}>{s}</span>
                      <span className="material-icons text-indigo-400 text-sm">add_circle</span>
                    </div>
                  ))}
                </div>
              )}

              <div className="space-y-3">
                <div className="flex justify-between items-center px-1">
                  <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Hinos Selecionados</span>
                  {draft.songs.length > 0 && (
                    <button onClick={shareDraftPraise} className="flex items-center gap-1.5 text-[9px] font-black text-emerald-600 bg-emerald-50 px-3 py-1 rounded-full border border-emerald-100 hover:bg-emerald-100 transition-colors">
                      <span className="material-icons text-xs">share</span> COMPARTILHAR LOUVORES
                    </button>
                  )}
                </div>
                <div className="space-y-2 max-h-80 overflow-y-auto pr-1 custom-scrollbar">
                  {draft.songs.map((s, i) => (
                    <div 
                      key={`${s}-${i}`} 
                      draggable 
                      onDragStart={(e) => onDragStart(e, i)}
                      onDragOver={(e) => onDragOver(e, i)}
                      onDragEnd={() => setDraggedIndex(null)}
                      className={`flex items-center justify-between p-3.5 bg-slate-50/50 rounded-xl border border-slate-100 cursor-move transition-all active:scale-95 hover:bg-white hover:shadow-md ${draggedIndex === i ? 'drag-ghost' : ''}`}
                    >
                      <div className="flex items-center gap-3 overflow-hidden">
                        <span className="material-icons text-slate-300 text-sm">drag_indicator</span>
                        <span className="font-bold text-slate-700 text-[13px] truncate">#{i+1} {s}</span>
                      </div>
                      <button onClick={() => setDraft(prev => ({...prev, songs: prev.songs.filter((_, idx) => idx !== i)}))} className="text-rose-200 hover:text-rose-500 ml-2"><span className="material-icons text-lg">close</span></button>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* 2. ESCALA DE OBREIROS */}
            <div className="space-y-5 pt-6 border-t border-slate-50">
              <div className="flex flex-col">
                <Label>Portão</Label>
                <FormInput>
                  <select 
                    value={draft.roles.gate} 
                    onChange={e => updateRole('gate', e.target.value)} 
                    className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer"
                  >
                    <option value="">Selecione...</option>
                    {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </FormInput>
              </div>

              {dateInfo.isWednesday && (
                <div className="bg-indigo-50/80 p-4 rounded-2xl border border-indigo-100 flex items-center justify-center gap-3 text-indigo-700 animate-scaleUp">
                  <span className="text-lg">🌸</span>
                  <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto dirigido pelo Grupo de Senhoras</span>
                </div>
              )}

              {!dateInfo.isWednesday && (
                <div className="space-y-5">
                  <div className="flex flex-col">
                    <Label>Louvor</Label>
                    <FormInput>
                      <select value={draft.roles.praise} onChange={e => updateRole('praise', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                        <option value="">Selecione...</option>
                        {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                      </select>
                    </FormInput>
                  </div>

                  {!dateInfo.isMonday && (
                    <div className="flex flex-col">
                      <Label>Palavra</Label>
                      <FormInput>
                        <select value={draft.roles.word} onChange={e => updateRole('word', e.target.value)} className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none appearance-none cursor-pointer">
                          <option value="">Selecione...</option>
                          {WORKERS_LIST.map(n => <option key={n} value={n}>{n}</option>)}
                        </select>
                      </FormInput>
                    </div>
                  )}

                  <div className="flex flex-col min-h-[70px] justify-end">
                    {draft.roles.word === 'TRANSMISSÃO' ? (
                      <div className="bg-amber-50 p-4 rounded-2xl border border-amber-100 flex items-center justify-center gap-3 text-amber-700 animate-scaleUp">
                        <span className="text-lg">📡</span>
                        <span className="font-black text-[9px] uppercase tracking-widest text-center leading-tight">Culto transmitido via satélite</span>
                      </div>
                    ) : (
                      <>
                        <Label>Texto Bíblico</Label>
                        <FormInput>
                          <input type="text" value={draft.roles.scripture} onChange={e => updateRole('scripture', e.target.value)} placeholder="Livro / Versículo" className="w-full bg-transparent font-black text-base text-[#1a1c3d] text-center outline-none" />
                        </FormInput>
                      </>
                    )}
                  </div>
                </div>
              )}
            </div>

            <button 
              onClick={handleSave} 
              disabled={draft.songs.length === 0} 
              className={`w-full py-5 rounded-2xl font-black text-base tracking-widest transition-all active:scale-95 flex items-center justify-center gap-3 shadow-xl ${draft.songs.length > 0 ? 'bg-[#1a1c3d] text-white' : 'bg-slate-200 text-slate-400 cursor-not-allowed shadow-none'}`}
            >
              <span className="material-icons">save</span>
              {editingId ? 'ATUALIZAR REGISTRO' : 'CONFIRMAR E SALVAR'}
            </button>

            {editingId && (
              <button 
                onClick={onCancelEdit}
                className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest hover:text-rose-500 transition-colors"
              >
                CANCELAR EDIÇÃO
              </button>
            )}
          </div>
        </div>
      </div>

      {/* MODAL RECORRENCIA */}
      {pendingSong && (
        <div className="fixed inset-0 bg-[#1a1c3d]/95 backdrop-blur-xl flex items-center justify-center z-[2000] p-6 animate-fadeIn">
          <div className="bg-white rounded-[3rem] p-10 w-full max-w-sm shadow-2xl animate-scaleUp text-center">
            <div className="w-16 h-16 bg-amber-50 rounded-full flex items-center justify-center mx-auto mb-6 text-amber-500"><span className="material-icons text-3xl">warning_amber</span></div>
            <h3 className="text-xl font-black text-[#1a1c3d] mb-2 uppercase tracking-tighter">Hino Recorrente</h3>
            <p className="text-slate-500 font-bold mb-8 leading-relaxed text-[11px]">Este hino foi cantado há <span className="text-amber-600 font-black">{pendingSong.diff} dias</span>. Prosseguir?</p>
            <div className="flex flex-col gap-3">
              <button onClick={() => executeAdd(pendingSong.name)} className="w-full py-4 bg-indigo-600 text-white font-black rounded-xl shadow-lg active:scale-95">SIM, ADICIONAR</button>
              <button onClick={() => setPendingSong(null)} className="w-full py-3 text-slate-400 font-black uppercase text-[10px] tracking-widest">Escolher outro</button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default ServiceForm;

import React, { useState, useMemo } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface WorkerEvent {
  date: string;
  description: string;
}

interface WorkerStatsData {
  gate: WorkerEvent[];
  praise: WorkerEvent[];
  word: WorkerEvent[];
  total: number;
}

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, events: WorkerEvent[] } | null>(null);

  const stats = useMemo(() => {
    const data: Record<string, WorkerStatsData> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));

    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });

    history.forEach(r => {
      const event = { date: r.date, description: r.description };
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(event);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(event);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(event);
    });

    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.date.localeCompare(a.date));
      data[name].praise.sort((a, b) => b.date.localeCompare(a.date));
      data[name].word.sort((a, b) => b.date.localeCompare(a.date));
    });

    return Object.entries(data)
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick, icon }: { label: string, count: number, onClick: () => void, icon: string }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-2xl p-4 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-md group"
    >
      <div className="flex items-center gap-1 mb-2">
        <span className="material-icons text-[10px] text-slate-300 group-hover:text-indigo-400 transition-colors">{icon}</span>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-[0.15em] group-hover:text-indigo-600 transition-colors">{label}</span>
      </div>
      <span className="text-3xl font-black text-[#1a1c3d] leading-none">{count}</span>
      <div className="mt-2 w-5 h-0.5 bg-slate-100 rounded-full group-hover:w-8 group-hover:bg-indigo-400 transition-all"></div>
    </button>
  );

  return (
    <>
      <div className="space-y-8 animate-fadeIn pb-10 max-w-4xl mx-auto">
        <div className="px-2">
          <h2 className="text-2xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
          <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mt-1">Total acumulado de atos realizados</p>
        </div>

        <div className="grid gap-8">
          {stats.map((worker) => (
            <div key={worker.name} className="bg-white rounded-[2.5rem] overflow-hidden shadow-xl border border-slate-50 group transition-all">
              <div className="bg-[#1a1c3d] px-8 py-6 flex justify-between items-center relative overflow-hidden">
                <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/5 rounded-full blur-2xl"></div>

                <h3 className="text-white font-black text-xl tracking-tight uppercase relative z-10">{worker.name}</h3>
                <div className="bg-[#ffcc00] text-[#1a1c3d] px-4 py-2 rounded-full font-black text-[10px] shadow-lg flex items-center gap-2 relative z-10">
                  <span className="material-icons text-[14px]">military_tech</span>
                  {worker.total} ATOS TOTAIS
                </div>
              </div>

              <div className="p-5 flex gap-3 bg-slate-50/30">
                <StatBox label="Portão" count={worker.gate.length} icon="door_front" onClick={() => setModalData({ worker: worker.name, role: 'Portão', events: worker.gate })} />
                <StatBox label="Louvor" count={worker.praise.length} icon="music_note" onClick={() => setModalData({ worker: worker.name, role: 'Louvor', events: worker.praise })} />
                <StatBox label="Palavra" count={worker.word.length} icon="record_voice_over" onClick={() => setModalData({ worker: worker.name, role: 'Palavra', events: worker.word })} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {modalData && (
        <div className="fixed inset-0 bg-[#1a1c3d]/90 flex items-center justify-center z-[3000] p-6 backdrop-blur-md animate-fadeIn" onClick={() => setModalData(null)}>
          <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-md overflow-hidden animate-scaleUp border border-white" onClick={e => e.stopPropagation()}>

            <div className="bg-[#1a1c3d] p-10 relative">
              <div className="flex items-center gap-2 mb-1">
                <span className="material-icons text-indigo-400 text-sm">history</span>
                <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.2em] block">DETALHES DE ATIVIDADE</span>
              </div>
              <h3 className="text-white font-black text-2xl uppercase tracking-tighter leading-tight">{modalData.worker}</h3>
              <div className="mt-3 flex gap-2">
                <div className="bg-white/10 px-3 py-1.5 rounded-xl inline-flex items-center gap-2">
                  <span className="text-indigo-200 font-black text-[10px] uppercase tracking-widest">{modalData.role}</span>
                </div>
                <div className="bg-amber-400 px-3 py-1.5 rounded-xl inline-flex items-center gap-2">
                  <span className="text-[#1a1c3d] font-black text-[10px] uppercase tracking-widest">{modalData.events.length} VEZES</span>
                </div>
              </div>

              <button onClick={() => setModalData(null)} className="absolute top-8 right-8 w-12 h-12 bg-white/10 rounded-2xl flex items-center justify-center text-white/40 active:scale-90 transition-transform">
                <span className="material-icons text-2xl">close</span>
              </button>
            </div>

            <div className="p-8 bg-white flex flex-col">
              <div className="max-h-[50vh] overflow-y-auto pr-2 custom-scrollbar space-y-3">
                {modalData.events.length === 0 ? (
                  <div className="py-20 text-center">
                    <span className="material-icons text-slate-100 text-6xl mb-4">event_busy</span>
                    <p className="text-slate-400 font-black text-xs uppercase tracking-widest">Nenhum registro encontrado</p>
                  </div>
                ) : (
                  modalData.events.map((ev, i) => (
                    <div key={i} className="flex justify-between items-center p-5 bg-slate-50 rounded-2xl border border-slate-100 shadow-sm group">
                      <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-white rounded-2xl flex items-center justify-center border border-slate-100 shadow-sm">
                          <span className="text-[10px] font-black text-indigo-600">#{modalData.events.length - i}</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="font-black text-[#1a1c3d] text-base leading-none mb-1">
                            {new Date(ev.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                          </span>
                          <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">
                            Culto: {ev.description}
                          </span>
                        </div>
                      </div>
                      <span className="material-icons text-slate-200 group-hover:text-indigo-400 transition-colors">event_available</span>
                    </div>
                  ))
                )}
              </div>

              <button 
                onClick={() => setModalData(null)} 
                className="w-full mt-8 py-5 bg-slate-100 text-slate-500 font-black rounded-[2rem] uppercase text-[11px] tracking-widest active:scale-95 transition-all hover:bg-slate-200"
              >
                VOLTAR AO RANKING
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

