              <div className="flex items-center gap-2 mb-3">
                <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse"></div>
                <span className="text-indigo-400 font-black text-[10px] md:text-[11px] uppercase tracking-[0.3em]">Histórico de Atividade</span>
              </div>

              <div className="flex justify-between items-end">
                <div>
                  <h3 className="text-white font-black text-3xl md:text-4xl uppercase tracking-tighter leading-none mb-4">{modalData.worker}</h3>
                  <div className="flex gap-3">
                    <div className="bg-white/10 px-4 py-2 rounded-2xl border border-white/5 flex items-center gap-2">
