              </div>
            </div>

            {/* LISTA ROLÁVEL DE DATAS */}
            <div className="flex-1 overflow-y-auto p-6 md:p-12 bg-slate-50 custom-scrollbar">
              <div className="max-w-xl mx-auto space-y-4">
                {modalData.events.length === 0 ? (
                  <div className="py-24 text-center">
                    <span className="material-icons text-slate-200 text-8xl mb-4">history_toggle_off</span>
                    <p className="text-slate-400 font-black text-xs uppercase tracking-[0.4em]">Nenhum registro</p>
