                ) : (
                  modalData.events.map((ev, i) => (
                    <div 
                      key={i} 
                      className="flex justify-between items-center p-6 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-indigo-100 transition-all group"
