                      <div className="flex items-center gap-5">
                        <div className="w-14 h-14 bg-slate-50 rounded-[1.5rem] flex items-center justify-center border border-slate-100 group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-inner">
                          <span className="text-xs font-black">#{modalData.events.length - i}</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="font-black text-[#1a1c3d] text-xl tracking-tight mb-1">
                            {new Date(ev.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                          </span>
                          <div className="flex items-center gap-2">
                            <span className="w-2 h-2 rounded-full bg-emerald-400"></span>
                            <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                              {ev.description}
                            </span>
                          </div>
                        </div>
                      </div>
                      <div className="w-10 h-10 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-500">
                        <span className="material-icons text-xl">done_all</span>
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* BOTÃO INFERIOR FIXO (MOBILE) */}
            <div className="p-6 md:p-10 bg-white border-t border-slate-100 md:hidden">
               <button 
                onClick={() => setModalData(null)} 
                className="w-full py-6 bg-[#1a1c3d] text-white font-black rounded-[2.5rem] uppercase text-[12px] tracking-[0.2em] shadow-2xl active:scale-95 transition-all"
              >
                VOLTAR AO RANKING
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default WorkerRanking;

import React, { useState, useMemo, useEffect } from 'react';
import { ServiceRecord } from '../types';
import { WORKERS_LIST } from '../constants';

interface WorkerEvent {
  date: string;
  description: string;
}

interface Props {
  history: ServiceRecord[];
}

const WorkerRanking: React.FC<Props> = ({ history }) => {
  const [modalData, setModalData] = useState<{ worker: string, role: string, events: WorkerEvent[] } | null>(null);

  // Bloqueia o scroll do body quando a tela fixa está aberta
  useEffect(() => {
    if (modalData) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }
    return () => { document.body.style.overflow = 'unset'; };
  }, [modalData]);

  const stats = useMemo(() => {
    const data: Record<string, { gate: WorkerEvent[], praise: WorkerEvent[], word: WorkerEvent[], total: number }> = {};
    const officialWorkers = WORKERS_LIST.filter(name => !['VISITANTE', 'TRANSMISSÃO'].includes(name));

    officialWorkers.forEach(name => {
      data[name] = { gate: [], praise: [], word: [], total: 0 };
    });

    history.forEach(r => {
      const event = { date: r.date, description: r.description };
      if (r.roles.gate && data[r.roles.gate]) data[r.roles.gate].gate.push(event);
      if (r.roles.praise && data[r.roles.praise]) data[r.roles.praise].praise.push(event);
      if (r.roles.word && data[r.roles.word]) data[r.roles.word].word.push(event);
    });

    Object.keys(data).forEach(name => {
      data[name].total = data[name].gate.length + data[name].praise.length + data[name].word.length;
      data[name].gate.sort((a, b) => b.date.localeCompare(a.date));
      data[name].praise.sort((a, b) => b.date.localeCompare(a.date));
      data[name].word.sort((a, b) => b.date.localeCompare(a.date));
    });

    return Object.entries(data)
      .map(([name, val]) => ({ name, ...val }))
      .sort((a, b) => b.total - a.total);
  }, [history]);

  const StatBox = ({ label, count, onClick, icon }: { label: string, count: number, onClick: () => void, icon: string }) => (
    <button 
      onClick={onClick}
      className="flex-1 bg-white rounded-3xl p-5 shadow-sm border border-slate-100 flex flex-col items-center justify-center transition-all active:scale-95 hover:shadow-lg hover:border-indigo-100 group"
    >
      <div className="flex items-center gap-1.5 mb-2">
        <span className="material-icons text-[14px] text-slate-300 group-hover:text-indigo-500 transition-colors">{icon}</span>
        <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest group-hover:text-indigo-600 transition-colors">{label}</span>
      </div>
      <span className="text-4xl font-black text-[#1a1c3d] leading-none">{count}</span>
      <div className="mt-3 w-6 h-1 bg-slate-100 rounded-full group-hover:w-10 group-hover:bg-indigo-400 transition-all"></div>
    </button>
  );

  return (
    <>
      <div className="space-y-8 animate-fadeIn pb-10 max-w-4xl mx-auto">
        <div className="px-2 text-center md:text-left">
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Atividades por Obreiro</h2>
          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mt-2">Clique nos números para ver o histórico detalhado</p>
        </div>

        <div className="grid gap-8">
          {stats.map((worker) => (
            <div key={worker.name} className="bg-white rounded-[3rem] overflow-hidden shadow-2xl border border-white group transition-all">
              <div className="bg-[#1a1c3d] px-10 py-8 flex flex-col md:flex-row justify-between items-center gap-4 relative overflow-hidden">
                <div className="absolute -right-10 -top-10 w-40 h-40 bg-white/5 rounded-full blur-3xl"></div>

                <div className="flex flex-col items-center md:items-start relative z-10">
                  <span className="text-indigo-400 font-black text-[9px] uppercase tracking-[0.3em] mb-1">Obreiro Selecionado</span>
                  <h3 className="text-white font-black text-2xl tracking-tight uppercase">{worker.name}</h3>
                </div>

                <div className="bg-[#ffcc00] text-[#1a1c3d] px-6 py-3 rounded-2xl font-black text-[11px] shadow-xl flex items-center gap-2 relative z-10">
                  <span className="material-icons text-[18px]">workspace_premium</span>
                  {worker.total} ATOS NO TOTAL
                </div>
              </div>

              <div className="p-6 flex flex-wrap md:flex-nowrap gap-4 bg-slate-50/50">
                <StatBox label="Portão" count={worker.gate.length} icon="door_front" onClick={() => setModalData({ worker: worker.name, role: 'Portão', events: worker.gate })} />
                <StatBox label="Louvor" count={worker.praise.length} icon="music_note" onClick={() => setModalData({ worker: worker.name, role: 'Louvor', events: worker.praise })} />
                <StatBox label="Palavra" count={worker.word.length} icon="record_voice_over" onClick={() => setModalData({ worker: worker.name, role: 'Palavra', events: worker.word })} />
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* TELA FIXA DE HISTÓRICO (FULL OVERLAY) */}
      {modalData && (
        <div className="fixed inset-0 bg-[#1a1c3d] z-[5000] flex flex-col animate-slideUp overflow-hidden">
          {/* CABEÇALHO FIXO NO TOPO */}
          <div className="bg-[#1a1c3d] p-8 pt-12 md:p-12 border-b border-white/5 shadow-2xl shrink-0 z-10">
            <div className="max-w-2xl mx-auto flex justify-between items-end">
              <div className="space-y-3">
                <div className="flex items-center gap-2">
                  <div className="w-2 h-2 bg-indigo-400 rounded-full animate-pulse"></div>
                  <span className="text-indigo-400 font-black text-[10px] md:text-[11px] uppercase tracking-[0.3em]">Relatório Detalhado</span>
                </div>
                <h3 className="text-white font-black text-3xl md:text-5xl uppercase tracking-tighter leading-none">{modalData.worker}</h3>
                <div className="flex gap-3">
                  <div className="bg-white/10 px-4 py-2 rounded-2xl border border-white/5 flex items-center gap-2">
                    <span className="material-icons text-indigo-300 text-sm">assignment</span>
                    <span className="text-white font-black text-[11px] uppercase tracking-widest">{modalData.role}</span>
                  </div>
                  <div className="bg-amber-400 px-4 py-2 rounded-2xl flex items-center gap-2 shadow-lg shadow-amber-900/20">
                    <span className="text-[#1a1c3d] font-black text-[11px] uppercase tracking-widest">{modalData.events.length} Atos</span>
                  </div>
                </div>
              </div>

              <button 
                onClick={() => setModalData(null)} 
                className="w-16 h-16 bg-white/5 rounded-3xl flex items-center justify-center text-white/50 hover:text-white hover:bg-white/10 active:scale-90 transition-all border border-white/10"
              >
                <span className="material-icons text-3xl">close</span>
              </button>
            </div>
          </div>

          {/* LISTA ROLÁVEL DE DATAS */}
          <div className="flex-1 overflow-y-auto bg-slate-50 px-6 py-10 md:px-12">
            <div className="max-w-xl mx-auto space-y-4 pb-20">
              {modalData.events.length === 0 ? (
                <div className="py-24 text-center">
                  <span className="material-icons text-slate-200 text-8xl mb-4">history_toggle_off</span>
                  <p className="text-slate-400 font-black text-xs uppercase tracking-[0.4em]">Nenhum registro encontrado</p>
                </div>
              ) : (
                modalData.events.map((ev, i) => (
                  <div 
                    key={i} 
                    className="flex justify-between items-center p-6 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl hover:border-indigo-100 transition-all group animate-fadeIn"
                    style={{ animationDelay: `${i * 0.05}s` }}
                  >
                    <div className="flex items-center gap-5">
                      <div className="w-14 h-14 bg-slate-50 rounded-[1.5rem] flex items-center justify-center border border-slate-100 group-hover:bg-indigo-600 group-hover:text-white transition-all shadow-inner">
                        <span className="text-xs font-black">#{modalData.events.length - i}</span>
                      </div>
                      <div className="flex flex-col">
                        <span className="font-black text-[#1a1c3d] text-xl tracking-tight mb-1">
                          {new Date(ev.date + 'T12:00:00').toLocaleDateString('pt-BR')}
                        </span>
                        <div className="flex items-center gap-2">
                          <span className="w-2 h-2 rounded-full bg-emerald-400"></span>
                          <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                            Culto: {ev.description}
                          </span>
                        </div>
                      </div>
                    </div>
                    <div className="w-10 h-10 rounded-full bg-emerald-50 flex items-center justify-center text-emerald-500 shrink-0">
                      <span className="material-icons text-xl">verified</span>
                    </div>
                  </div>
                ))
              )}
            </div>
          </div>

          {/* RODAPÉ FIXO PARA FECHAR NO MOBILE */}
          <div className="p-6 md:p-10 bg-white border-t border-slate-100 shadow-2xl md:hidden shrink-0">
            <button 
              onClick={() => setModalData(null)} 
              className="w-full py-6 bg-[#1a1c3d] text-white font-black rounded-[2.5rem] uppercase text-[12px] tracking-[0.2em] shadow-xl active:scale-95 transition-all"
            >
              FECHAR RELATÓRIO
            </button>
          </div>
        </div>
      )}
    </>
  );
};

export default WorkerRanking;
